#include <iostream>
#include <complex>
#include <cmath>
 
using namespace std;
 
int main()
{
    for (int n = 2; n <= 5; n++)
    {
        cout << n << " roots of 1:" << endl;
        for (auto r : roots(n))
        {
            cout << "  " << r << endl;
        }
    }
}
 
vector<complex<double>> roots(int n)
{
    vector<complex<double>> r(n);
    for (int i = 0; i < n; i++)
    {
        r[i] = polar(1.0, 2 * M_PI * i / n);
    }
    return r;
}

#include <iostream>
 
using namespace std;
 
int main()
{
    bool doors[100];
 
    // the 100 passes called for in the task description
    for (int pass = 1; pass <= 100; pass++) {
        for (int door = pass-1; door < 100; door += pass) {
            doors[door] =!doors[door];
        }
    }
 
    // one more pass to answer the question
    for (int i = 0; i < 100; i++) {
        if (doors[i]) {
            cout << "1";
        } else {
            cout << "0";
        }
 
        if (i%10 == 9) {
            cout << "\n";
        } else {
            cout << " ";
        }
 
    }
}

