bool prime(int a) {
    return!(a < 2 || any_of(2, int(sqrt(a)) + 1, [a](int x) { return a % x == 0; }));
}

void insertSort(int A[], int n){
  for(int i = 1; i < n; i++){
    int value = A[i];
    int j = i - 1;
    while(j >= 0 && A[j] > value){
      A[j + 1] = A[j];
      j = j - 1;
    }
    A[j + 1] = value;
  }
}

