#include <iostream>
#include <chrono>
#include <functional>
 
using namespace std;
 
typedef function<int(int)> Func;
 
int cube(int n) { return n * n * n; }
 
long* benchmark(int n, Func func, int arg) {
    long* times = new long[n];
    for (int i = 0; i < n; i++) {
         auto m = chrono::high_resolution_clock::now();
         func(arg);
         times[i] = chrono::duration_cast<chrono::nanoseconds>(chrono::high_resolution_clock::now() - m).count();
    }
    return times;
} 
 
int main() {
    cout << "\nTimings (nanoseconds) : " << endl;
    for (int time : benchmark(10, cube, 5)) cout << time << endl;
}

#include <iostream>
#include <vector>
#include <cmath>
 
using namespace std;
 
int numPrimeFactors(unsigned x) {
    unsigned p = 2;
    int pf = 0;
    if (x == 1)
        return 1;
    else {
        while (true) {
            if (!(x % p)) {
                pf++;
                x /= p;
                if (x == 1)
                    return pf;
            }
            else
                ++p;
        }
    }
}
 
void primeFactors(unsigned x, vector<unsigned>& arr) {
    unsigned p = 2;
    int pf = 0;
    if (x == 1)
        arr[pf] = 1;
    else {
        while (true) {
            if (!(x % p)) {
                arr[pf++] = p;
                x /= p;
                if (x == 1)
                    return;
            }
            else
                p++;
        }
    }
}
 
unsigned sumDigits(unsigned x) {
    unsigned sum = 0, y;
    while (x) {
        y = x % 10;
        sum += y;
        x /= 10;
    }
    return sum;
}
 
unsigned sumFactors(vector<unsigned>& arr, int size) {
    unsigned sum = 0;
    for (int a = 0; a < size; a++)
        sum += sumDigits(arr[a]);
    return sum;
}
 
void listAllSmithNumbers(unsigned x) {
    vector<unsigned> arr;
    for (unsigned a = 4; a < x; a++) {
        int numfactors = numPrimeFactors(a);
        arr.resize(numfactors);
        if (numfactors < 2)
            continue;	
        primeFactors(a, arr);	
        if (sumDigits(a) == sumFactors(arr,numfactors))
            cout << a << " ";
    }
}
 
int main(int argc, char* argv[]) {
    cout << "All the Smith Numbers < 10000 are:\n";
    listAllSmithNumbers(10000);
    return 0;
}

#include <iostream>
#include <cmath>
 
using namespace std;
 
int main()
{
  double lat, lng, ref, slat, hra, hla;
  int h;
  
  cout << "Enter latitude       => ";
  cin >> lat;
  cout << "Enter longitude      => ";
  cin >> lng;
  cout << "Enter legal meridian => ";
  cin >> ref;
  cout << endl;
  
  slat = sin(lat * M_PI / 180);
  cout << "    sine of latitude:   %.3f" << slat << endl;
  cout << "    diff longitude:     %.3f" << (lng-ref) << endl;
  cout << endl;
  cout << "Hour, sun hour angle, dial hour line angle from 6am to 6pm" << endl;
  
  for (h = -6; h < 7; h++)
  {
    hra = 15 * h;
    hra -= lng - ref;
    hla = atan(slat * tan(hra * M_PI / 180)) * 180 / M_PI;
    cout << "HR=" << h << "; HRA=" << hra << "; HLA=" << hla << endl;
  }
  
  return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <iomanip>
 
using namespace std;
 
int turn(int base, int n) {
    int sum = 0;
    int n2 = n;
    while (n2!= 0) {
        int re = n2 % base;
        n2 /= base;
        sum += re;
    }
    return sum % base;
}
 
void fairShare(int base, int count) {
    cout << "Base " << setw(2) << base << ":";
    for (int i = 0; i < count; i++) {
        int t = turn(base, i);
        cout << " " << setw(2) << t;
    }
    cout << endl;
}
 
void turnCount(int base, int count) {
    vector<int> cnt(base, 0);
    for (int i = 0; i < count; i++) {
        int t = turn(base, i);
        cnt[t]++;
    }
 
    int minTurn = INT_MAX;
    int maxTurn = INT_MIN;
    int portion = 0;
    for (int i = 0; i < base; i++) {
        int num = cnt[i];
        if (num > 0) {
            portion++;
        }
        if (num < minTurn) {
            minTurn = num;
        }
        if (num > maxTurn) {
            maxTurn = num;
        }
    }
 
    cout << "  With " << base << " people: ";
    if (minTurn == 0) {
        cout << "Only " << portion << " have a turn" << endl;
    } else if (minTurn == maxTurn) {
        cout << minTurn << endl;
    } else {
        cout << minTurn << " or " << maxTurn << endl;
    }
}
 
int main() {
    fairShare(2, 25);
    fairShare(3, 25);
    fairShare(5, 25);
    fairShare(11, 25);
 
    cout << "How many times does each get a turn in 50000 iterations?" << endl;
    turnCount(191, 50000);
    turnCount(1377, 50000);
    turnCount(49999, 50000);
    turnCount(50000, 50000);
    turnCount(50001, 50000);
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string s1 = "thisisatest";
    string s2 = "testing123testing";
    int len1 = s1.length();
    int len2 = s2.length();
    int ir = 0, jr = -1;
    for (int i1 = 0; i1 < len1; i1++) {
        int i2 = s2.find(s1[i1]);
        while (i2 >= 0) {
            int j1 = i1, j2 = i2;
            while (j1 < len1 && j2 < len2 && s2[j2] == s1[j1]) {
                if (j1-i1 >= jr-ir) {
                    ir = i1;
                    jr = j1;
                }
                j1++;
                j2++;
            }
            i2 = s2.find(s1[i1], i2+1);
        }
    }
    cout << s1.substr(ir, jr-ir+1) << endl;
    return 0;
}

#include <iostream>
#include <cmath>
#include <vector>
#include <algorithm>
 
using namespace std;
 
int PopulationCount(long n)
{
    int cnt = 0;
    do
    {
        if ((n & 1)!= 0) 
        {
            cnt++;
        }
    } while ((n >>= 1) > 0);
 
    return cnt;
}
 
bool isPrime(int x)
{
    if (x <= 2 || (x & 1) == 0)
    {
        return x == 2;
    }
 
    auto limit = sqrt(x);
    for (int i = 3; i <= limit; i += 2)
    {
        if (x % i == 0)
        {
            return false;
        }
    }
 
    return true;
}
 
vector<int> Pernicious(int start, int count, int take)
{
    vector<int> result;
    for (int i = start; i < start + count; i++)
    {
        if (isPrime(PopulationCount(i)))
        {
            result.push_back(i);
        }
    }
 
    return result;
}
 
int main()
{
    auto result = Pernicious(0, INT_MAX, 25);
    for (auto n : result)
    {
        cout << n << " ";
    }
 
    cout << endl;
 
    result = Pernicious(888888877, 11, 11);
    for (auto n : result)
    {
        cout << n << " ";
    }
 
    cin.get();
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
 
using namespace std;
 
template <typename T>
T quickselect(vector<T> a, int k) {
  vector<T> arr = a;
  while (true) {
    int pivot_index = rand() % arr.size();
    T pivot = arr[pivot_index];
    arr.erase(arr.begin() + pivot_index);
    vector<T> left, right;
    for (auto x : arr) {
      if (x < pivot) {
        left.push_back(x);
      } else {
        right.push_back(x);
      }
    }
    if (k == left.size()) {
      return pivot;
    } else if (k < left.size()) {
      arr = left;
    } else {
      k = k - left.size() - 1;
      arr = right;
    }
  }
}
 
int main() {
  vector<int> v = {9, 8, 7, 6, 5, 0, 1, 2, 3, 4};
  for (int i = 0; i < v.size(); i++) {
    cout << quickselect(v, i) << endl;
  }
}

#include <iostream>
#include <string>
#include <map>
#include <cmath>

// Shannon entropy in bits per symbol.
double entropy(std::string str) {
  int len = str.length();

  // Build a frequency map from the string.
  std::map<char, int> frequencies;
  for (char c : str) {
    frequencies[c] = (frequencies[c] || 0) + 1;
  }

  // Sum the frequency of each character.
  double sum = 0;
  for (auto const& [key, val] : frequencies) {
    sum -= val / len * std::log2(val / len);
  }
  return sum;
}

int main() {
  std::cout << entropy("1223334444") << std::endl;        // 1.84644
  std::cout << entropy("0") << std::endl;                 // 0
  std::cout << entropy("01") << std::endl;                // 1
  std::cout << entropy("0123") << std::endl;              // 2
  std::cout << entropy("01234567") << std::endl;          // 3
  std::cout << entropy("0123456789abcdef") << std::endl;  // 4
}

#include <iostream>
#include <string>
#include <map>
#include <algorithm>
 
using namespace std;
 
string soundex(string s) {
    string a = s;
    transform(a.begin(), a.end(), a.begin(), ::tolower);
    string f = a.substr(0, 1);
    string r = "";
    map<char, string> codes = {
        {'a', ""}, {'e', ""}, {'i', ""}, {'o', ""}, {'u', ""},
        {'b', "1"}, {'f', "1"}, {'p', "1"}, {'v', "1"},
        {'c', "2"}, {'g', "2"}, {'j', "2"}, {'k', "2"}, {'q', "2"}, {'s', "2"}, {'x', "2"}, {'z', "2"},
        {'d', "3"}, {'t', "3"},
        {'l', "4"},
        {'m', "5"}, {'n', "5"},
        {'r', "6"}
    };
 
    for (int i = 1; i < a.length(); i++) {
        if (codes[a[i]]!= codes[a[i - 1]]) {
            r += codes[a[i]];
        }
    }
 
    return (f + r + "000").substr(0, 4);
}
 
int main() {
    map<string, string> tests = {
        {"Soundex", "S532"},
        {"Example", "E251"},
        {"Sownteks", "S532"},
        {"Ekzampul", "E251"},
        {"Euler", "E460"},
        {"Gauss", "G200"},
        {"Hilbert", "H416"},
        {"Knuth", "K530"},
        {"Lloyd", "L300"},
        {"Lukasiewicz", "L222"},
        {"Ellery", "E460"},
        {"Ghosh", "G200"},
        {"Heilbronn", "H416"},
        {"Kant", "K530"},
        {"Ladd", "L300"},
        {"Lissajous", "L222"},
        {"Wheaton", "W350"},
        {"Ashcraft", "A226"},
        {"Burroughs", "B622"},
        {"Burrows", "B620"},
        {"O'Hara", "O600"}
    };
 
    for (auto i : tests) {
        cout << i.first << "\t" << i.second << "\t" << soundex(i.first) << "\t" << (soundex(i.first) == i.second) << endl;
    }
 
    return 0;
}

#include <iostream>
#include <vector>
 
using namespace std;
 
typedef vector<int> Vector;
typedef vector<Vector> Matrix;
 
Matrix zigzagMatrix(int n) {
    Matrix result(n, Vector(n));
    bool down = false;
    int count = 0;
    for (int col = 0; col < n; col++) {
        if (down) 
            for (int row = 0; row <= col; row++) result[row][col - row] = count++;
        else 
            for (int row = col; row >= 0; row--) result[row][col - row] = count++;
        down =!down;
    }
    for (int row = 1; row < n; row++) {
        if (down)
            for (int col = n - 1; col >= row; col--) result[row + n - 1 - col][col] = count++;
        else
            for (int col = row; col < n; col++) result[row + n - 1 - col][col] = count++;
        down =!down;
    }
    return result;
}
 
void printMatrix(Matrix m) {
    for (int i = 0; i < m.size(); i++) {
        for (int j = 0; j < m.size(); j++) cout << " " << m[i][j];
        cout << endl;
    }
    cout << endl;
}
 
int main() {
    printMatrix(zigzagMatrix(5));
    printMatrix(zigzagMatrix(10));
}

#include <iostream>
#include <string>
#include <vector>
#include <cstdlib>
#include <ctime>
 
using namespace std;
 
struct symbols {
    char k, q, r, b, n;
};
 
const symbols A = {'K', 'Q', 'R', 'B', 'N'};
const symbols W = {'♔', '♕', '♖', '♗', '♘'};
const symbols B = {'♚', '♛', '♜', '♝', '♞'};
 
const vector<string> krn = {
    "nnrkr", "nrnkr", "nrknr", "nrkrn",
    "rnnkr", "rnknr", "rnkrn",
    "rknnr", "rknrn",
    "rkrnn"};
 
string chess960(const symbols& sym, int id) {
    string pos(8, 0);
    int q = id/4, r = id%4;
    pos[r*2+1] = sym.b;
    q /= 4, r = q%4;
    pos[r*2] = sym.b;
    q /= 6, r = q%6;
    for (int i = 0; ; i++) {
        if (pos[i]!= 0) {
            continue;
        }
        if (r == 0) {
            pos[i] = sym.q;
            break;
        }
        r--;
    }
    int i = 0;
    for (char f : krn[q]) {
        for (; pos[i]!= 0; i++);
        switch (f) {
        case 'k':
            pos[i] = sym.k;
            break;
        case 'r':
            pos[i] = sym.r;
            break;
        case 'n':
            pos[i] = sym.n;
            break;
        }
    }
    return pos;
}
 
int main() {
    cout << " ID  Start position\n";
    for (int id : {0, 518, 959}) {
        cout << " " << id << "  " << chess960(A, id) << '\n';
    }
    cout << "\nRandom\n";
    srand(time(0));
    for (int i = 0; i < 5; i++) {
        cout << chess960(W, rand()%960) << '\n';
    }
}

