#include <iostream>
#include <cmath>
 
double agm(double a, double g) {
    double aa = a;
    double gg = g;
    double ta;
    double epsilon = 1.0e-16;
 
    while (true) {
        ta = (aa + gg) / 2.0;
        if (std::abs(aa - ta) <= epsilon) return ta;
        gg = std::sqrt(aa * gg);
        aa = ta;
    }
}
 
int main() {
    std::cout << agm(1.0, 1.0 / std::sqrt(2.0)) << std::endl;
}

// A doubly linked list of strings;
#include <iostream>
#include <string>
 
using namespace std;
 
class ListEntry {
public:
    const char *value;
    ListEntry *next;
    ListEntry *prev;
};
 
class LinkedList {
public:
    ListEntry *next;
    ListEntry *prev;
};
 
class ListIterator {
public:
    ListEntry  *link;
    LinkedList *head;
};
 
LinkedList *NewList() {
    ListEntry *le = new ListEntry;
    if (le) {
        le->value = NULL;
        le->next = le->prev = NULL;
    }
    return le;
}
 
int LL_Append(LinkedList *ll, const char *newVal) 
{
    ListEntry *le = new ListEntry;
    if (le) {
        le->value = strdup(newVal);
        le->prev = ll->prev;
        le->next = NULL;
        if (le->prev) 
            le->prev->next = le;
        else
            ll->next = le;
        ll->prev = le;
    }
    return (le!= NULL);
}
 
int LI_Insert(ListIterator *iter, const char *newVal)
{
    ListEntry *crnt = iter->link;
    ListEntry *le = new ListEntry;
    if (le) {
        le->value = strdup(newVal);
        if ( crnt == iter->head) {
            le->prev = NULL;
            le->next = crnt->next;
            crnt->next = le;
            if (le->next)
                le->next->prev = le;
            else 
                crnt->prev = le;
        }
        else {
            le->prev = ( crnt == NULL)? iter->head->prev : crnt->prev;
            le->next = crnt;
            if (le->prev)
                le->prev->next = le;
            else
                iter->head->next = le;
            if (crnt) 
                crnt->prev = le;
            else 
                iter->head->prev = le;
        }
    }
    return (le!= NULL);
}
 
ListIterator *LL_GetIterator(LinkedList *ll ) 
{
    ListIterator *liter = new ListIterator;
    liter->head = ll;
    liter->link = ll;
    return liter;
}
 
#define LLI_Delete( iter ) \
    {delete iter; \
    iter = NULL;}
 
int LLI_AtEnd(ListIterator *iter)
{
    return iter->link == NULL;
}
const char *LLI_Value(ListIterator *iter)
{
    return (iter->link)? iter->link->value: NULL;
}
int LLI_Next(ListIterator *iter)
{
    if (iter->link) iter->link = iter->link->next;
    return(iter->link!= NULL);
}
int LLI_Prev(ListIterator *iter)
{
    if (iter->link) iter->link = iter->link->prev;
    return(iter->link!= NULL);
}
 
int main() 
{
    static const char *contents[] = {"Read", "Orage", "Yeller", 
                                     "Glean", "Blew", "Burple"};
    int ix;
    LinkedList *ll = NewList();    //new linked list
    ListIterator *iter;
 
    for (ix=0; ix<6; ix++)        //insert contents
        LL_Append(ll, contents[ix]);
 
    iter = LL_GetIterator(ll);    //get an iterator
    cout << "forward\n";
    while(LLI_Next(iter))         //iterate forward
        cout << "value=" << LLI_Value(iter) << endl;    
    LLI_Delete(iter);             //delete iterator
 
    cout << "\nreverse\n";
    iter = LL_GetIterator(ll);
    while(LLI_Prev(iter))         //iterate reverse 
        cout << "value=" << LLI_Value(iter) << endl;
    LLI_Delete(iter);
                        //uhhh-- delete list??
    return 0;
}

