#include <iostream>
#include <string>
#include <cmath>
#include <sstream>

using namespace std;

bool isNarc(int x) {
    string str = to_string(x);
    int i, sum = 0, l = str.length();
    if (x < 0) {
        return false;
    } else {
        for (i = 0; i < l; i++) {
            sum += pow(str.at(i), l);
        }
    }
    return sum == x;
}

string main(){
    int n[25];
    int count = 0;
    for (int x = 0; count < 25; x++){
        if (isNarc(x)){
            n[count] = x;
            count++;
        }
    }
    stringstream ss;
    for (int i = 0; i < 25; i++) {
        ss << n[i] << " ";
    }
    return ss.str();
}

#include <iostream>
