using namespace std;
 
template <typename T>
string compare_and_report(T string1, T string2) {
    vector<string> strings = {string1, string2};
    int difference = strings[0].length() - strings[1].length();
    if (difference == 0) { // equal
        return "\"" + strings[0] + "\" and \"" + strings[1] + "\" are of equal length, " + to_string(strings[0].length());
    } else if (difference > 1) { // string1 > string2
        return "\"" + strings[0] + "\" has length " + to_string(strings[0].length()) + " and is the longest\n\"" + strings[1] + "\" has length " + to_string(strings[1].length()) + " and is the shortest";
    } else { // string2 > string1
        return "\"" + strings[1] + "\" has length " + to_string(strings[1].length()) + " and is the longest\n\"" + strings[0] + "\" has length " + to_string(strings[0].length()) + " and is the shortest";
    }
}
 
int main() {
    cout << compare_and_report("a", "b") << endl;
    cout << endl << compare_and_report("cd", "e") << endl;
    cout << endl << compare_and_report("f", "gh") << endl;
}

#include <iostream>
#include <vector>
 
int make_change(const std::vector<int>& coins, int cents) {
    int size = cents + 1;
    std::vector<int> ways(size, 0);
    ways[0] = 1;
    for (auto coin : coins) {
        for (int amount = coin; amount < size; ++amount) {
            ways[amount] += ways[amount - coin];
        }
    }
    return ways[cents];
}
 
int main() {
    std::cout << make_change({1,5,10,25}, 100) << std::endl;
    std::cout << make_change({1,5,10,25,50,100}, 100000) << std::endl;
}

