#include <iostream>
#include <vector>
#include <cmath>
 
using namespace std;
 
bool isPrime(int n){
    int x = floor(sqrt(n)), i = 2;
 
    while ((i <= x) && (n % i!= 0)) i++;
 
    return (x < i);
}
 
vector<long long> smooth(int n, int s, int k){
    vector<vector<long long>> p;
    for (int i = 2; i <= n; i++){
        if (isPrime(i)){
            p.push_back({i, {1}, 0});
        }
    }
 
    vector<long long> res;
    for (int i = 0; i < s + k; i++){
        long long m = p[0][1][p[0][2]];
 
        for (int j = 1; j < p.size(); j++){
            if (p[j][1][p[j][2]] < m) m = p[j][1][p[j][2]];
        }
 
        for (int j = 0; j < p.size(); j++){
            p[j][1].push_back(p[j][0]*m);
            if (p[j][1][p[j][2]] == m) p[j][2]++;
        }
 
        res.push_back(m);
    }
 
    return vector<long long>(res.begin() + s - 1, res.begin() + s - 1 + k);
}
 
// main 
 
int main(){
    string sOut = "";
 
    for (vector<int> x : {{2, 29, 1, 25}, {3, 29, 3000, 3}, {503, 521, 30000, 20}}){
        for (int n = x[0]; n <= x[1]; n++){
            if (isPrime(n)){
                sOut += to_string(x[2]) + " to " + to_string(x[2] - 1 + x[3]) + " " + to_string(n) + "-smooth numbers: ";
                for (long long i : smooth(n, x[2], x[3])) sOut += to_string(i) + " ";
                sOut += "\n";
            }
        }
    }
 
    cout << sOut << endl;
 
    return 0;
}

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <vector>
 
using namespace std;
 
typedef vector<double> vector_t;
 
void normalize(vector_t& v) {
    double invLen = 1 / sqrt(dot(v, v));
    v[0] *= invLen;
    v[1] *= invLen;
    v[2] *= invLen;
}
 
double dot(const vector_t& x, const vector_t& y) {
    return x[0]*y[0] + x[1]*y[1] + x[2]*y[2];
}
 
void drawSphere(int r, double k, double amb, const vector_t& dir, vector<vector<unsigned char> >& img) {
    int w = r*4, h = r*3;
    img.resize(h);
    for (int i = 0; i < h; i++) {
        img[i].resize(w);
    }
    vector_t vec(3);
    for (int x = -r; x < r; x++) {
        for (int y = -r; y < r; y++) {
            if (int z = r*r - x*x - y*y; z >= 0) {
                vec[0] = x;
                vec[1] = y;
                vec[2] = sqrt(z);
                normalize(vec);
                double s = dot(dir, vec);
                if (s < 0) {
                    s = 0;
                }
                double lum = 255 * (pow(s, k) + amb) / (1 + amb);
                if (lum < 0) {
                    lum = 0;
                } else if (lum > 255) {
                    lum = 255;
                }
                img[y+r][x+r] = (unsigned char)lum;
            }
        }
    }
}
 
int main() {
    vector_t dir = {-30, -30, 50};
    normalize(dir);
    vector<vector<unsigned char> > img;
    drawSphere(200, 1.5,.2, dir, img);
    FILE* f = fopen("sphere.png", "wb");
    if (!f) {
        cerr << "Cannot open file" << endl;
        return 1;
    }
    fprintf(f, "P5\n%d %d\n255\n", img[0].size(), img.size());
    for (int i = 0; i < img.size(); i++) {
        fwrite(&img[i][0], 1, img[i].size(), f);
    }
    fclose(f);
    return 0;
}

#include <iostream>
