using namespace std;
 
class Multiplier {
public:
  Multiplier(double a, double b) : a(a), b(b) {}
  double operator()(double m) {
    return a * b * m;
  }
private:
  double a;
  double b;
};
 
int main() {
  vector<pair<double, double>> pairs = {
    {2.0, 0.5},
    {4.0, 0.25},
    {6.0, 0.16666666666666666}
  };
  double testVal = 0.5;
  for (auto& pair : pairs) {
    Multiplier f(pair.first, pair.second);
    double result = f(testVal);
    stringstream ss;
    ss << pair.first << " * " << pair.second << " * " << testVal << " = " << result;
    cout << ss.str() << endl;
  }
}

