#include <iostream>
#include <vector>
#include <stdexcept>
 
using namespace std;
 
class SubRandom {
public:
  SubRandom(int seed = rand()) {
    if (seed < 0 || seed > 999999999)
      throw invalid_argument("seed not in 0..999999999");
 
    vector<int> ary(55);
    ary[0] = seed;
    ary[1] = 1;
    for (int i = 2; i < 55; i++)
      ary[i] = ary[i - 2] - ary[i - 1];
 
    state.resize(34);
    for (int i = 0; i < 34; i++)
      state[i] = ary[(i * 34) % 55];
 
    for (int i = 0; i < 220; i++)
      rand();
  }
 
  SubRandom(const SubRandom& orig) {
    state = orig.state;
  }
 
  int rand() {
    state.push_back((state[54] - state[23]) % 1000000000);
    int ret = state[0];
    state.erase(state.begin());
    return ret;
  }
 
  int seed;
private:
  vector<int> state;
};
 
int main() {
  SubRandom rng(292929);
  for (int i = 0; i < 3; i++)
    cout << rng.rand() << endl;
}

#include <iostream>
