using namespace std;
 
int main(int argc, char* argv[])
{
  vector<int> nums;
  for (int i = 1; i < argc; i++)
    nums.push_back(atoi(argv[i]));
  vector<int> sorted;
  mutex mutex;
  vector<thread> threads;
  for (int n : nums)
    threads.push_back(thread([&](){
      this_thread::sleep_for(chrono::milliseconds(n));
      mutex.lock();
      sorted.push_back(n);
      mutex.unlock();
    }));
  for (thread& t : threads)
    t.join();
  for (int n : sorted)
    cout << n << " ";
  cout << endl;
}

