#include <cmath>
#include <cstdlib>
#include <vector>
#include <algorithm>
#include <iostream>
#include <fstream>
#include <string>
#include <sstream>
 
using namespace std;
 
class RGBColour {
public:
  RGBColour(int r, int g, int b) : r(r), g(g), b(b) {}
  int r, g, b;
  static const RGBColour BLACK;
};
 
const RGBColour RGBColour::BLACK(0, 0, 0);
 
class Pixel {
public:
  Pixel(int x, int y) : x(x), y(y) {}
  int x, y;
};
 
class ColourPixel : public Pixel {
public:
  ColourPixel(int x, int y, RGBColour colour) : Pixel(x, y), colour(colour) {}
  RGBColour colour;
  double distance_to(int px, int py) {
    return hypot(px - x, py - y);
  }
};
 
class Pixmap {
public:
  Pixmap(int width, int height) : width(width), height(height) {
    pixels = new RGBColour*[width];
    for (int i = 0; i < width; i++) {
      pixels[i] = new RGBColour[height];
    }
  }
  ~Pixmap() {
    for (int i = 0; i < width; i++) {
      delete[] pixels[i];
    }
    delete[] pixels;
  }
  int width, height;
  RGBColour** pixels;
  void each_pixel(void (*f)(int, int, Pixmap*)) {
    for (int x = 0; x < width; x++) {
      for (int y = 0; y < height; y++) {
        f(x, y, this);
      }
    }
  }
  void draw_circle(ColourPixel* base, int radius, RGBColour colour) {
    for (int x = 0; x < width; x++) {
      for (int y = 0; y < height; y++) {
        if (hypot(x - base->x, y - base->y) < radius) {
          pixels[x][y] = colour;
        }
      }
    }
  }
  void save_as_png(const char* filename) {
    ofstream file(filename, ios::out | ios::binary);
    file << "P6\n" << width << " " << height << "\n255\n";
    for (int y = 0; y < height; y++) {
      for (int x = 0; x < width; x++) {
        file << (char)pixels[x][y].r << (char)pixels[x][y].g << (char)pixels[x][y].b;
      }
    }
    file.close();
  }
};
 
int main() {
  int width = 300;
  int height = 200;
  int npoints = 20;
  Pixmap pixmap(width, height);
  vector<ColourPixel*> bases;
  for (int i = 0; i < npoints; i++) {
    bases.push_back(new ColourPixel(
      3 + rand() % (width - 6), 3 + rand() % (height - 6),
      RGBColour(rand() % 256, rand() % 256, rand() % 256)
    ));
  }
  pixmap.each_pixel([](int x, int y, Pixmap* pixmap) {
    ColourPixel* nearest = *min_element(bases.begin(), bases.end(), [x, y](ColourPixel* a, ColourPixel* b) {
      return a->distance_to(x, y) < b->distance_to(x, y);
    });
    pixmap->pixels[x][y] = nearest->colour;
  });
  for (auto base : bases) {
    pixmap.pixels[base->x][base->y] = RGBColour::BLACK;
    pixmap.draw_circle(base, 2, RGBColour::BLACK);
  }
  pixmap.save_as_png("voronoi_C++.png");
  return 0;
}

