    istream_iterator<string> start(in), end;
    vector<vector<int>> data(15, vector<int>(15));
    int i = 0;
    while (start!= end) {
        istringstream iss(*start);
        copy(istream_iterator<int>(iss), istream_iterator<int>(), data[i].begin());
        ++start;
        ++i;
    }
 
    for (int r = data.size() - 1; r > 0; r--)
        for (int c = 0; c < data[r].size() - 1; c++)
            data[r - 1][c] += max(data[r][c], data[r][c + 1]);
 
