#include <iostream>
#include <vector>
#include <algorithm>
 
using namespace std;
 
struct item {
    string item;
    double weight;
    double price;
};
 
bool compare(const item& a, const item& b) {
    return a.price/a.weight > b.price/b.weight;
}
 
int main() {
    vector<item> all = {
        {"beef", 3.8, 36},
        {"pork", 5.4, 43},
        {"ham", 3.6, 90},
        {"greaves", 2.4, 45},
        {"flitch", 4.0, 30},
        {"brawn", 2.5, 56},
        {"welt", 3.7, 67},
        {"salami", 3.0, 95},
        {"sausage", 5.9, 98},
    };
    double left = 15.;
    sort(all.begin(), all.end(), compare);
    for (auto i : all) {
        if (i.weight <= left) {
            cout << "take all the " << i.item << endl;
            if (i.weight == left) {
                return 0;
            }
            left -= i.weight;
        } else {
            cout << "take " << left << "kg " << i.item << endl;
            return 0;
        }
    }
}

