#include <iostream>
#include <map>
#include <vector>
 
using namespace std;
 
map<vector<int>, int> memo;
 
int sterling2(int n, int k)
{
  vector<int> key = {n, k};
  if (memo.find(key)!= memo.end())
    return memo[key];
  if (n == 0 && k == 0)
    return 1;
  if (n == 0 || k == 0)
    return 0;
  if (n == k)
    return 1;
  if (k > n)
    return 0;
  int res = k * sterling2(n-1, k) + sterling2(n - 1, k-1);
  memo[key] = res;
  return res;
}
 
int main()
{
  cout << "Sterling2 numbers:" << endl;
  cout << "n/k ";
  for (int n = 0; n <= 12; n++)
    cout << " " << n;
  cout << endl;
  for (int row = 0; row <= 12; row++)
  {
    cout << row << "   ";
    for (int col = 0; col <= row; col++)
      cout << sterling2(row, col) << " ";
    cout << endl;
  }
  cout << endl;
  cout << "Maximum value from the sterling2(100, k)" << endl;
  int max = 0;
  for (int a = 1; a <= 100; a++)
  {
    int res = sterling2(100, a);
    if (res > max)
      max = res;
  }
  cout << max << endl;
}

#include <vector>
#include <algorithm>
#include <functional>
 
using namespace std;
 
template <typename T>
vector<T> bind(vector<T> v, function<vector<T>(T)> func) {
  return accumulate(v.begin(), v.end(), vector<T>(),
    [func](vector<T> acc, T a) { return acc.insert(acc.end(), func(a).begin(), func(a).end()); });
}
 
template <typename T>
vector<T> unit(T elem) {
  return vector<T>(1, elem);
}
 
template <typename T, typename U>
function<vector<U>(T)> lift(function<U(T)> func) {
  return [func](T elem) { return unit<U>(func(elem)); };
}
 
int inc(int n) { return n + 1; }
int doub(int n) { return 2 * n; }
function<vector<int>(int)> listy_inc = lift<int, int>(inc);
function<vector<int>(int)> listy_doub = lift<int, int>(doub);
 
int main() {
  vector<int> v = { 3, 4, 5 };
  vector<int> res = bind(bind(v, listy_inc), listy_doub);
  return 0;
}

