#include <iostream>
#include <vector>
 
using namespace std;
 
vector<vector<int> > bellTriangle(int n)
{
    vector<vector<int> > tri(n);
    for (int i = 0; i < n; i++)
    {
        tri[i].resize(i);
        for (int j = 0; j < i; j++)
        {
            tri[i][j] = 0;
        }
    }
    tri[1][0] = 1;
    for (int i = 2; i < n; i++)
    {
        tri[i][0] = tri[i - 1][i - 2];
        for (int j = 1; j < i; j++)
        {
            tri[i][j] = tri[i][j - 1] + tri[i - 1][j - 1];
        }
    }
    return tri;
}
 
int main()
{
    vector<vector<int> > bt = bellTriangle(51);
    cout << "First fifteen and fiftieth Bell numbers:" << endl;
    for (int i = 1; i <= 15; i++)
    {
        cout << i << ": " << bt[i][0] << endl;
    }
    cout << "50: " << bt[50][0] << endl << endl;
    cout << "The first ten rows of Bell's triangle:" << endl;
    for (int i = 1; i <= 10; i++)
    {
        for (int j = 0; j < i; j++)
        {
            cout << bt[i][j] << " ";
        }
        cout << endl;
    }
    return 0;
}

