#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>
 
using namespace std;
 
class PythagoranTriplesCounter
{
public:
  PythagoranTriplesCounter(int limit)
    : limit(limit), total(0), primitives(0)
  {
    generate_triples(3, 4, 5);
  }
  int total;
  int primitives;
 
private:
  int limit;
 
  void generate_triples(int a, int b, int c)
  {
    int perim = a + b + c;
    if (perim > limit)
      return;
 
    primitives++;
    total += limit / perim;
 
    generate_triples( a-2*b+2*c, 2*a-b+2*c, 2*a-2*b+3*c);
    generate_triples( a+2*b+2*c, 2*a+b+2*c, 2*a+2*b+3*c);
    generate_triples(-a+2*b+2*c,-2*a+b+2*c,-2*a+2*b+3*c);
  }
};
 
int main()
{
  int perim = 10;
  while (perim <= 100000000)
  {
    PythagoranTriplesCounter c(perim);
    cout << perim << " " << c.total << " " << c.primitives << endl;
    perim *= 10;
  }
}

