class Lcg {
private:
    long a;
    long c;
    long m;
    long d;
    long s;
    long state;
public:
    Lcg(long a, long c, long m, long d, long s) {
        this->a = a;
        this->c = c;
        this->m = m;
        this->d = d;
        this->s = s;
        this->state = s;
    }
    long nextInt() {
        state = (a * state + c) % m;
        return state / d;
    }
};
 
int main(int argc, char** argv) {
    std::cout << "First 10 BSD random numbers - seed 0" << std::endl;
    Lcg bsd(1103515245, 12345, 1 << 31, 1, 0);
    for (int i = 1; i <= 10; i++) std::cout << bsd.nextInt() << std::endl;
    std::cout << std::endl << "First 10 MSC random numbers - seed 0" << std::endl;
    Lcg msc(214013, 2531011, 1 << 31, 1 << 16, 0);
    for (int i = 1; i <= 10; i++) std::cout << msc.nextInt() << std::endl;
    return 0;
}

void bline(int x0, int y0, int x1, int y1) {
  int dx = abs(x1 - x0), sx = x0 < x1? 1 : -1;
  int dy = abs(y1 - y0), sy = y0 < y1? 1 : -1; 
  int err = (dx>dy? dx : -dy)/2;
  while (true) {
    setPixel(x0,y0);
    if (x0 === x1 && y0 === y1) break;
    int e2 = err;
    if (e2 > -dx) { err -= dy; x0 += sx; }
    if (e2 < dy) { err += dx; y0 += sy; }
  }
}

