#include <iostream>
#include <string>
#include <cstdlib>
#include <ctime>
using namespace std;
 
struct Player {
  string name;
  int score;
};
 
int roll() { return 1 + rand() % 6; }
 
void round(Player &player) {
  int curSum = 0,
      dice;
  cout << "It's " << player.name << "'s turn (" << player.score << ")." << endl;
  while (true) {
      dice = roll();
      if (dice == 1) {
        cout << "You roll a 1. What a pity!" << endl;
        break;
      } else {
        curSum += dice;
        cout << "You roll a " << dice << " (sum: " << curSum << ")." << endl;
        cout << "Roll again? (y/n): ";
        char c;
        cin >> c;
        if (c == 'n') {
          player.score += curSum;
          break;
        }
      }
  }
}
 
int main() {
  srand(time(0));
  Player players[2];
  int curPlayer = 1,
      gameOver = false;
  cout << "Your name, player #1: ";
  cin >> players[0].name;
  cout << "Your name, player #2: ";
  cin >> players[1].name;
  while (!gameOver) {
    if (curPlayer == 0) curPlayer = 1; else curPlayer = 0;
    round(players[curPlayer]);
    if (players[curPlayer].score >= 100) {
      gameOver = true;
      cout << players[curPlayer].name << " wins (" << players[curPlayer].score << ")." << endl;
    }
  }
  return 0;
}

