using namespace std;
 
vector<long double> ar = {17.0/91, 78.0/85, 19.0/51, 23.0/38, 29.0/33, 77.0/29, 95.0/23, 77.0/19, 1.0/17, 11.0/13, 13.0/11, 15.0/14, 15.0/2, 55.0/1};
 
class Runner {
public:
    Runner() {
        num = 2;
    }
    long double next() {
        num *= detect();
        return num;
    }
private:
    long double num;
    long double detect() {
        for (auto f : ar) {
            if (f * num == floor(f * num)) {
                return f;
            }
        }
        return 0;
    }
};
 
class PrimeGenerator {
public:
    PrimeGenerator() {
        runner = new Runner();
    }
    long double next() {
        long double num = runner->next();
        long double l = log2(num);
        if (l == floor(l)) {
            return l;
        }
        return 0;
    }
private:
    Runner *runner;
};
 
int main() {
    Runner runner;
    PrimeGenerator prime_generator;
    for (int i = 0; i < 20; i++) {
        cout << runner.next() << " ";
    }
    cout << endl;
    for (int i = 0; i < 20; i++) {
        cout << prime_generator.next() << " ";
    }
    cout << endl;
    return 0;
}

