#include <iostream>
#include <vector>
#include <list>
 
using namespace std;
 
int main()
{
    try
    {
        int n = 7;
        int m = 2;
 
        vector<int> order(n);
        list<int> circle;
 
        for (int i = 0; i < n; ++i)
        {
            circle.push_back(i);
        }
 
        int l = 0;
        int j = 0;
        int k = 0;
 
        while (circle.size()!= 0)
        {
            j++;
            if (j == m)
            {
                order[k] = circle.front();
                circle.pop_front();
 
                k++;
                l--;
                j = 0;
            }
 
            if (k == n - 1)
            {
                order[k] = circle.front();
                circle.pop_front();
            }
 
            if (l == circle.size() - 1)
            {
                l = 0;
            }
            else
            {
                l++;
            }
        }
 
        for (int i = 0; i < order.size(); i++)
        {
            cout << order[i] << endl;
        }
    }
    catch (exception e)
    {
        cout << e.what() << endl;
    }
    finally
    {
        cin.get();
    }
}

#include <iostream>
#include <cmath>
#include <SFML/Graphics.hpp>
 
using namespace std;
 
class FractalTree : public sf::RenderWindow {
public:
    FractalTree() : sf::RenderWindow(sf::VideoMode(800, 600), "Fractal Tree") {
        setFramerateLimit(60);
    }
 
    void drawTree(int x1, int y1, double angle, int depth) {
        if (depth == 0) return;
        int x2 = x1 + (int) (cos(angle * M_PI / 180.0) * depth * 10.0);
        int y2 = y1 + (int) (sin(angle * M_PI / 180.0) * depth * 10.0);
        draw(sf::Vertex(sf::Vector2f(x1, y1), sf::Color::Black));
        draw(sf::Vertex(sf::Vector2f(x2, y2), sf::Color::Black));
        drawTree(x2, y2, angle - 20, depth - 1);
        drawTree(x2, y2, angle + 20, depth - 1);
    }
 
    void run() {
        while (isOpen()) {
            sf::Event event;
            while (pollEvent(event)) {
                if (event.type == sf::Event::Closed) close();
            }
            clear();
            drawTree(400, 500, -90, 9);
            display();
        }
    }
};
 
int main() {
    FractalTree app;
    app.run();
    return 0;
}

// version 1.0.6
 
#include <iostream>
#include <vector>
#include <set>
#include <algorithm>
#include <string>
#include <sstream>
#include <iomanip>
#include <cmath>
#include <cstdlib>
#include <ctime>
 
using namespace std;
 
const int ITERATIONS = 500;
const int LIMIT = 10000;
 
// In the sieve,  0 = not Lychrel, 1 = Seed Lychrel, 2 = Related Lychrel
vector<int> lychrelSieve(LIMIT + 1, 0);
vector<int> seedLychrels;
set<string> relatedLychrels;
 
bool isPalindrome(string s) {
    return s == string(s.rbegin(), s.rend());
}
 
string addReverse(string s) {
    string rev(s.rbegin(), s.rend());
    int carry = 0;
    string sum;
    for (int i = s.size() - 1; i >= 0; i--) {
        int digit = (s[i] - '0') + (rev[i] - '0') + carry;
        sum.push_back(digit % 10 + '0');
        carry = digit / 10;
    }
    if (carry) sum.push_back(carry + '0');
    reverse(sum.begin(), sum.end());
    return sum;
}
 
void lychrelTest(int i, vector<string> &seq) {
    if (i < 1) return;
    string s = to_string(i);
    for (int j = 1; j <= ITERATIONS; j++) {
        s = addReverse(s);
        seq.push_back(s);
        if (isPalindrome(s)) return;
    }
    for (int j = 0; j < seq.size(); j++) {
        if (stoi(seq[j]) <= LIMIT) lychrelSieve[stoi(seq[j])] = 2;
        else break;
    }
    int sizeBefore = relatedLychrels.size();
    for (int j = 0; j < seq.size(); j++) relatedLychrels.insert(seq[j]);
    if (relatedLychrels.size() - sizeBefore == seq.size()) {
        seedLychrels.push_back(i);
        lychrelSieve[i] = 1;
    }
    else {
        relatedLychrels.insert(to_string(i));
        lychrelSieve[i] = 2;
    }
}
 
int main() {
    vector<string> seq;
    for (int i = 1; i <= LIMIT; i++)
        if (lychrelSieve[i] == 0) {
            seq.clear();
            lychrelTest(i, seq);
        }
    int related = count(lychrelSieve.begin(), lychrelSieve.end(), 2);
    cout << "Lychrel numbers in the range [1, " << LIMIT << "]" << endl;
    cout << "Maximum iterations = " << ITERATIONS << endl;
    cout << "\nThere are " << seedLychrels.size() << " seed Lychrel numbers, namely" << endl;
    for (int i = 0; i < seedLychrels.size(); i++) cout << seedLychrels[i] << " ";
    cout << "\n\nThere are also " << related << " related Lychrel numbers in this range" << endl;
    vector<int> palindromes;
    for (int i = 1; i <= LIMIT; i++)
        if (lychrelSieve[i] > 0 && isPalindrome(to_string(i))) palindromes.push_back(i);
    cout << "\nThere are " << palindromes.size() << " palindromic Lychrel numbers, namely" << endl;
    for (int i = 0; i < palindromes.size(); i++) cout << palindromes[i] << " ";
    cout << endl;
}

