#include <algorithm>
 
using namespace std;
 
vector<vector<int>> pythagoreanTriples(int n) {
    vector<vector<int>> result;
    for (int x = 1; x <= n; x++) {
        for (int y = x; y <= n; y++) {
            for (int z = y; z <= n; z++) {
                if (x * x + y * y == z * z) {
                    result.push_back(vector<int>{x, y, z});
                }
            }
        }
    }
    return result;
}
 
int main() {
    auto result = pythagoreanTriples(20);
    for (auto triple : result) {
        cout << "(" << triple[0] << ", " << triple[1] << ", " << triple[2] << ")" << endl;
    }
}

#include <iostream>
