int remarkable(int n) {
    return n + int(0.5 + sqrt(n));
}
 
int main() {
    // task 1
    cout << "  n  r(n)" << endl;
    cout << "---  ---" << endl;
    for (int n = 1; n <= 22; n++) {
        cout << " " << n << "  " << remarkable(n) << endl;
    }
 
    // task 2
    const int limit = 1e6;
    cout << "\nChecking for squares for n < " << limit << endl;
    int next = 2;
    int nextSq = 4;
    for (int n = 1; n < limit; n++) {
        int r = remarkable(n);
        if (r == nextSq) {
            throw n;
        } else if (r > nextSq) {
            cout << nextSq << " didn't occur" << endl;
            next++;
            nextSq = next * next;
        }
    }
    cout << "No squares occur for n < " << limit << endl;
}

