#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <algorithm>
 
using namespace std;
 
mutex m;
condition_variable cv;
 
void NumsFromBy(int from, int by, queue<int>& q) {
  for (int i = from; ; i+=by) {
    unique_lock<mutex> lk(m);
    q.push(i);
    lk.unlock();
    cv.notify_one();
  }
}
 
void Filter(queue<int>& in, queue<int>& out, int prime) {
  while (true) {
    unique_lock<mutex> lk(m);
    cv.wait(lk, [&in]{return!in.empty();});
    int i = in.front();
    in.pop();
    lk.unlock();
    if (i%prime!= 0) {            // here is the trial division
      unique_lock<mutex> lk(m);
      out.push(i);
      lk.unlock();
      cv.notify_one();
    }
  }
}
 
void Sieve(queue<int>& out) { 
  out.push(3);
  int q = 9;
  queue<int> ps;
  thread t1(Sieve, ref(ps));                   // separate primes supply
  int p = ps.front();
  ps.pop();
  queue<int> nums;
  thread t2(NumsFromBy, 5, 2, ref(nums));        // end of setup
  for (int i = 0; ; i++) {
    unique_lock<mutex> lk(m);
    cv.wait(lk, [&nums]{return!nums.empty();});
    int n = nums.front();
    nums.pop();
    lk.unlock();
    if (n < q) {
    	out.push(n);                 // n is prime
    } else {
        queue<int> ch1;    // n == q == p*p
        thread t3(Filter, ref(nums), ref(ch1), p);  // creation of a filter by p, at p*p
        nums = ch1;
    	p = ps.front();
    	ps.pop();                 // next prime
    	q = p*p;                  //   and its square
    }
  }
}
 
void primes (queue<int>& c) {
  c.push(2);
  thread t1(Sieve, ref(c));
  t1.join();
}
 
int main() {
  queue<int> ch;
  thread t1(primes, ref(ch));
  cout << "First twenty:";
  for (int i = 0; i < 20; i++) {
    unique_lock<mutex> lk(m);
    cv.wait(lk, [&ch]{return!ch.empty();});
    int n = ch.front();
    ch.pop();
    lk.unlock();
    cout << " " << n;
  }
  cout << endl;
  t1.join();
}

