#include <iostream>
 
bool endsWith89(int n) {
    int digit;
    int sum = 0;
    int nn = n;
    while (true) {
        while (nn > 0) {
            digit = nn % 10;
            sum += digit * digit;
            nn /= 10;
        }
        if (sum == 89) return true;
        if (sum == 1) return false;
        nn = sum;
        sum  = 0;
    }
}
 
int main() {
    int sums[8 * 81 + 1];
    sums[0] = 1;
    sums[1] = 0;
    int s;
    for (int n = 1; n <= 8; n++)
        for (int i = n * 81; i >= 1; i--) 
            for (int j = 1; j <= 9; j++) {
                s = j * j;
                if (s > i) break;
                sums[i] += sums[i - s];
            }
    int count89 = 0; 
    for (int i = 1; i <= 8 * 81; i++) 
        if (endsWith89(i)) count89 += sums[i];
    std::cout << "There are " << count89 << " numbers from 1 to 100 million ending with 89" << std::endl;
}

