void permuteString(vector<string> &result, string beginningString, string endingString)
{
    if (endingString.length() <= 1)
    {
        result.push_back(beginningString + endingString);
    }
    else
    {
        for (int i = 0; i < endingString.length(); i++)
        {
            string newString = endingString.substr(0, i) + endingString.substr(i + 1);
            permuteString(result, beginningString + endingString[i], newString);
        }
    }
}
 
