#include <iostream>
#include <cmath>
 
using namespace std;
 
const unsigned long long CONST = 6364136223846793005;
 
class Pcg32 {
public:
    unsigned long long state, inc;
 
    Pcg32() {
        state = 0x853c49e6748fea9b;
        inc = 0xda3e39cb94b95bdb;
    }
 
    void seed(unsigned long long seedState, unsigned long long seedSequence) {
        state = 0;
        inc = (seedSequence << 1) | 1;
        nextInt();
        state = state + seedState;
        nextInt();
    }
 
    unsigned int nextInt() {
        unsigned long long old = state;
        state = old*CONST + inc;
        unsigned int pcgshifted = (unsigned int)(((old >> 18) ^ old) >> 27);
        unsigned int rot = (unsigned int)(old >> 59);
        return (pcgshifted >> rot) | (pcgshifted << ((-rot) & 31));
    }
 
    double nextFloat() {
        return (double)nextInt() / (1 << 32);
    }
};
 
int main() {
    Pcg32 randomGen;
    randomGen.seed(42, 54);
    for (int i = 0; i < 5; i++) {
        cout << randomGen.nextInt() << endl;
    }
 
    int counts[5] = {0};
    randomGen.seed(987654321, 1);
    for (int i = 0; i < 1e5; i++) {
        int j = (int)floor(randomGen.nextFloat() * 5);
        counts[j]++;
    }
    cout << "\nThe counts for 100,000 repetitions are:" << endl;
    for (int i = 0; i < 5; i++) {
        cout << "  " << i << " : " << counts[i] << endl;
    }
}

