#include <cctype>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <map>
#include <regex>
#include <string>
#include <vector>
 
using namespace std;
 
struct word_count {
    const char* word;
    size_t count;
};
 
int compare_word_count(const void* p1, const void* p2) {
    const word_count* w1 = (const word_count*)p1;
    const word_count* w2 = (const word_count*)p2;
    if (w1->count > w2->count)
        return -1;
    if (w1->count < w2->count)
        return 1;
    return 0;
}
 
bool get_top_words(const char* filename, size_t count) {
    ifstream file(filename);
    if (!file) {
        cerr << "Could not open file " << filename << endl;
        return false;
    }
    string text((istreambuf_iterator<char>(file)),
                istreambuf_iterator<char>());
    if (text.empty()) {
        cerr << "File " << filename << " is empty" << endl;
        return false;
    }
    // Store word counts in a hash table
    map<string, size_t> ht;
    regex regex("\\w+");
    sregex_iterator it(text.begin(), text.end(), regex);
    sregex_iterator end;
    while (it!= end) {
        string word = it->str();
        string lower;
        lower.reserve(word.size());
        for (char c : word)
            lower.push_back(tolower(c));
        auto it = ht.find(lower);
        if (it!= ht.end())
            ++it->second;
        else
            ht.insert(make_pair(lower, 1));
        ++it;
    }
 
    // Sort words in decreasing order of frequency
    vector<word_count> words(ht.size());
    size_t i = 0;
    for (auto it = ht.begin(); it!= ht.end(); ++it) {
        words[i].word = it->first.c_str();
        words[i].count = it->second;
        ++i;
    }
    qsort(&words[0], words.size(), sizeof(word_count), compare_word_count);
 
    // Print the most common words
    if (count > words.size())
        count = words.size();
    cout << "Top " << count << " words" << endl;
    cout << "Rank\tCount\tWord" << endl;
    for (size_t i = 0; i < count; ++i)
        cout << i + 1 << "\t" << words[i].count << "\t" << words[i].word << endl;
    return true;
}
 
int main(int argc, char** argv) {
    if (argc!= 2) {
        cerr << "usage: " << argv[0] << " file" << endl;
        return EXIT_FAILURE;
    }
    if (!get_top_words(argv[1], 10))
        return EXIT_FAILURE;
    return EXIT_SUCCESS;
}

task_description:
From Chung-Chieh Shan (LtU):

Your stair-climbing robot has a very simple low-level API: the "step" function takes no argument and attempts to climb one step as a side effect. Unfortunately, sometimes the attempt fails and the robot clumsily falls one step instead. The "step" function detects what happens and returns a boolean flag: true on success, false on failure.

Write a function "step_up" that climbs one step up [from the initial position] (by repeating "step" attempts if necessary). Assume that the robot is not already at the top of the stairs, and neither does it ever reach the bottom of the stairs. How small can you make "step_up"? Can you avoid using variables (even immutable ones) and numbers?

Here's a pseudo-code of a simple recursive solution without using variables:

func step_up()
{
    if not step() {
        step_up();
        step_up();
    }
}

Inductive proof that step_up() steps up one step, if it terminates:

 Base case (if the step() call returns true): it stepped up one step. QED
 Inductive case (if the step() call returns false): Assume that recursive calls to step_up() step up one step. It stepped down one step (because step() returned false), but now we step up two steps using two step_up() calls. QED


The second (tail) recursion above can be turned into an iteration, as follows:

func step_up()
{
    while not step() {
        step_up();
    }
}

