#include <iostream>
#include <cstdlib>
#include <ctime>
#include <vector>
#include <algorithm>
 
// low <= num < high
int randInt(int low, int high) {
    return (rand() % (high - low)) + low;
}
 
// shuffle an array of n elements
void shuffle(std::vector<int> &array, const int n) {
    if (n > 1) {
        for (int i = 0; i < n - 1; i++) {
            int j = randInt(i, n);
 
            int t = array[i];
            array[i] = array[j];
            array[j] = t;
        }
    }
}
 
// print an n * n array
void printSquare(const std::vector<int> &latin, const int n) {
    for (int i = 0; i < n; i++) {
        std::cout << "[";
        for (int j = 0; j < n; j++) {
            if (j > 0) {
                std::cout << ", ";
            }
            std::cout << latin[i * n + j];
        }
        std::cout << "]\n";
    }
    std::cout << "\n";
}
 
void latinSquare(const int n) {
    std::vector<int> latin;
    std::vector<int> used;
    int i, j, k;
 
    if (n <= 0) {
        std::cout << "[]\n";
        return;
    }
 
    // allocate
    latin.resize(n * n);
 
    // initialize
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            latin[i * n + j] = j;
        }
    }
 
    // first row
    shuffle(latin, n);
 
    // middle row(s)
    for (i = 1; i < n - 1; i++) {
        bool shuffled = false;
 
        while (!shuffled) {
            shuffle(&latin[i * n], n);
 
            for (k = 0; k < i; k++) {
                for (j = 0; j < n; j++) {
                    if (latin[k * n + j] == latin[i * n + j]) {
                        goto shuffling;
                    }
                }
            }
            shuffled = true;
 
        shuffling: {}
        }
    }
 
    //last row
    used.resize(n);
    for (j = 0; j < n; j++) {
        std::fill(used.begin(), used.end(), 0);
        for (i = 0; i < n - 1; i++) {
            used[latin[i * n + j]] = 1;
        }
        for (k = 0; k < n; k++) {
            if (used[k] == 0) {
                latin[(n - 1) * n + j] = k;
                break;
            }
        }
    }
 
    // print the result
    printSquare(latin, n);
}
 
int main() {
    // initialze the random number generator
    srand((unsigned int)time((time_t)0));
 
    latinSquare(5);
    latinSquare(5);
    latinSquare(10);
 
    return 0;
}

