const vector<string> names = { "Platinum", "Golden", "Silver", "Bronze", "Copper", "Nickel", "Aluminium", "Iron", "Tin", "Lead" };
 
void lucas(long b) {
    cout << "Lucas sequence for " << names[b] << " ratio, where b = " << b << ":" << endl;
    cout << "First 15 elements: ";
    long x0 = 1;
    long x1 = 1;
    cout << x0 << ", " << x1;
    for (int i = 1; i <= 13; i++) {
        long x2 = b * x1 + x0;
        cout << ", " << x2;
        x0 = x1;
        x1 = x2;
    }
    cout << endl;
}
 
void metallic(long b, int dp) {
    int64_t x0 = 1;
    int64_t x1 = 1;
    int64_t x2;
    int64_t bb = b;
    string ratio = "1";
    int iters = 0;
    string prev = ratio;
    while (true) {
        iters++;
        x2 = bb * x1 + x0;
        string thiz = to_string(x2);
        if (prev == thiz) {
            string plural = "s";
            if (iters == 1) {
                plural = "";
            }
            cout << "Value after " << iters << " iteration" << plural << ": " << thiz << endl << endl;
            return;
        }
        prev = thiz;
        x0 = x1;
        x1 = x2;
    }
}
 
int main() {
    for (long b = 0; b < 10; b++) {
        lucas(b);
        metallic(b, 32);
    }
    cout << "Golden ration, where b = 1:" << endl;
    metallic(1, 256);
}

#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
 
const char *msg = "hello socket world";
 
int main()
{
   int i, sock, len, slen;
 
   struct addrinfo hints, *addrs;  
   memset(&hints, 0, sizeof(struct addrinfo));
   hints.ai_family = AF_UNSPEC;
   hints.ai_socktype = SOCK_STREAM;
 
   if (0 == getaddrinfo("localhost", "256", &hints, &addrs))
   {
       sock = socket(addrs->ai_family, addrs->ai_socktype, addrs->ai_protocol);
       if ( sock >= 0 )
       {
           if ( connect(sock, addrs->ai_addr, addrs->ai_addrlen) >= 0 )
           {
               const char *pm = msg;
               do
               {
                  len = strlen(pm);
                  slen = send(sock, pm, len, 0);
                  pm += slen;
               } while ((0 <= slen) && (slen < len));
           }
           close(sock);
       }
       freeaddrinfo(addrs);
   }
}

#include <iostream>
#include <vector>
#include <algorithm>
 
using namespace std;
 
int* circleSort(int* array, int size)
{
    if (size > 0)
        while (circleSortR(array, 0, size - 1, 0) != 0)
            continue;
    return array;
}
 
int circleSortR(int* arr, int lo, int hi, int numSwaps)
{
    if (lo == hi)
        return numSwaps;
 
    int high = hi;
    int low = lo;
    int mid = (hi - lo) / 2;
 
    while (lo < hi)
    {
        if (arr[lo] > arr[hi])
        {
            swap(arr[lo], arr[hi]);
            numSwaps++;
        }
        lo++;
        hi--;
    }
 
    if (lo == hi && arr[lo] > arr[hi + 1])
    {
        swap(arr[lo], arr[hi + 1]);
        numSwaps++;
    }
 
    numSwaps = circleSortR(arr, low, low + mid, numSwaps);
    numSwaps = circleSortR(arr, low + mid + 1, high, numSwaps);
 
    return numSwaps;
}
 
int main()
{
    int* sortedArray = circleSort(new int[] { 6, 7, 8, 9, 2, 5, 3, 4, 1 }, 9);
    for (int i = 0; i < 9; i++)
        cout << sortedArray[i] << " ";
    cout << endl;
    int* sortedArray2 = circleSort(new int[] { 2, 14, 4, 6, 8, 1, 3, 5, 7, 11, 0, 13, 12, -1 }, 14);
    for (int i = 0; i < 14; i++)
        cout << sortedArray2[i] << " ";
    cout << endl;
    int* sortedArray3 = circleSort(new int[] { 2, 3, 3, 5, 5, 1, 1, 7, 7, 6, 6, 4, 4, 0, 0 }, 15);
    for (int i = 0; i < 15; i++)
        cout << sortedArray3[i] << " ";
    cout << endl;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
 
using namespace std;
 
struct scores {
	int score;
	string name;
};
 
bool operator<(const scores& a, const scores& b) {
	if (a.score!= b.score) {
		return a.score > b.score;
	}
	return a.name < b.name;
}
 
bool operator==(const scores& a, const scores& b) {
	return a.score == b.score;
}
 
template <typename T>
void show(const string& name, vector<T>& data, vector<float> (*fn)(vector<T>&)) {
	cout << name << " Ranking:" << endl;
	vector<float> r = fn(data);
	for (int i = 0; i < data.size(); i++) {
		cout << r[i] << " - " << data[i].score << " " << data[i].name << endl;
	}
}
 
vector<float> StandardRank(vector<scores>& data) {
	vector<float> r(data.size());
	int k = 0;
	for (int i = 0; i < data.size(); i++) {
		if (i == 0 || data[i] == data[i - 1]) {
			k = i + 1;
		}
		r[i] = k;
	}
	return r;
}
 
vector<float> ModifiedRank(vector<scores>& data) {
	vector<float> r(data.size());
	for (int i = 0; i < data.size(); i++) {
		int k = i + 1;
		for (int j = i + 1; j < data.size() && data[i] == data[j]; j++) {
			k = j + 1;
		}
		r[i] = k;
	}
	return r;
}
 
vector<float> DenseRank(vector<scores>& data) {
	vector<float> r(data.size());
	int k = 0;
	for (int i = 0; i < data.size(); i++) {
		if (i == 0 || data[i] == data[i - 1]) {
			k++;
		}
		r[i] = k;
	}
	return r;
}
 
vector<float> OrdinalRank(vector<scores>& data) {
	vector<float> r(data.size());
	for (int i = 0; i < data.size(); i++) {
		r[i] = i + 1;
	}
	return r;
}
 
vector<float> FractionalRank(vector<scores>& data) {
	vector<float> r(data.size());
	for (int i = 0; i < data.size();) {
		int j = i + 1;
		float f = i + 1;
		for (; j < data.size() && data[i] == data[j]; j++) {
			f += j + 1;
		}
		f /= j - i;
		for (; i < j; i++) {
			r[i] = f;
		}
	}
	return r;
}
 
int main() {
	vector<scores> data = {
		{44, "Solomon"},
		{42, "Jason"},
		{42, "Errol"},
		{41, "Garry"},
		{41, "Bernard"},
		{41, "Barry"},
		{39, "Stephen"},
	};
	sort(data.begin(), data.end());
	show("Standard", data, StandardRank);
	show("\nModified", data, ModifiedRank);
	show("\nDense", data, DenseRank);
	show("\nOrdinal", data, OrdinalRank);
	show("\nFractional", data, FractionalRank);
}

#include <iostream>
using namespace std;
class Point
{
protected:
  int x, y;
public:
  Point() : Point(0) {}
  Point(int x) : Point(x,0) {}
  Point(int x, int y) { this->x = x; this->y = y; }
  int getX() { return x; }
  void setX(int x) { this->x = x; }
  int getY() { return y; }
  void setY(int y) { this->y = y; }
  virtual void print() { cout << "Point" << endl; }
};
 
class Circle : public Point
{
private:
  int r;
public:
  Circle(Point p) : Circle(p,0) { }
  Circle(Point p, int r) : Point(p) { this->r = r; }
  Circle() : Circle(0) { }
  Circle(int x) : Circle(x,0) { }
  Circle(int x, int y) : Circle(x,y,0) { }
  Circle(int x, int y, int r) : Point(x,y) { this->r = r; }
  int getR() { return r; }
  void setR(int r) { this->r = r; }
  void print() { cout << "Circle" << endl; }
};
 
int main(int argc, char *argv[])
{
  Point p = Point();
  Point c = Circle();
  p.print();
  c.print();
  return 0;
}

