#include <iostream>
#include <string>
#include <algorithm>
#include <vector>
#include <map>
#include <set>
#include <cctype>
 
using namespace std;
 
string makealpha(string key = "")
{
    string alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    set<char> z;
    for (char x : key + alpha)
    {
        if (isalpha(x) && z.find(toupper(x)) == z.end())
        {
            z.insert(toupper(x));
            key += toupper(x);
        }
    }
    return key;
}
 
string correct_case(string string)
{
    string out = "";
    for (char s : string)
    {
        if (isalpha(s))
        {
            out += toupper(s);
        }
    }
    return out;
}
 
string permu(string alp, int num)
{
    string out = "";
    out += alp.substr(0, num);
    out += alp.substr(num);
    return out;
}
 
pair<string, string> rotate_wheels(string lalph, string ralph, char key)
{
    int newin = ralph.find(key);
    return make_pair(permu(lalph, newin), permu(ralph, newin));
}
 
pair<string, string> scramble_wheels(string lalph, string ralph)
{
    // LEFT = cipher wheel
    // Cycle second[1] through nadir[14] forward
    lalph = permu(lalph, 1);
    lalph = permu(lalph, 13);
    lalph = permu(lalph, 1);
 
    // RIGHT = plain wheel
    // Send the zenith[0] character to the end[25],
    // cycle third[2] through nadir[14] characters forward
    ralph = permu(ralph, 2);
    ralph = permu(ralph, 12);
    ralph = permu(ralph, 1);
    ralph = permu(ralph, 1);
    return make_pair(lalph, ralph);
}
 
string do_chao(string msg, string lalpha, string ralpha, int en = 1, int show = 0)
{
    msg = correct_case(msg);
    string out = "";
    if (show)
    {
        cout << "=========================================" << endl;
        cout << "left:" << string(21,'') << "right: " << endl;
        cout << "=========================================" << endl;
        cout << lalpha << " " << ralpha << endl;
    }
    for (char L : msg)
    {
        if (en)
        {
            auto temp = rotate_wheels(lalpha, ralpha, L);
            lalpha = temp.first;
            ralpha = temp.second;
            out += lalpha[0];
        }
        else
        {
            auto temp = rotate_wheels(ralpha, lalpha, L);
            ralpha = temp.first;
            lalpha = temp.second;
            out += ralpha[0];
        }
        auto temp = scramble_wheels(lalpha, ralpha);
        lalpha = temp.first;
        ralpha = temp.second;
        if (show)
        {
            cout << lalpha << " " << ralpha << endl;
        }
    }
    return out;
}
 
int main()
{
    // letters only! makealpha(key) helps generate lalpha/ralpha.
    string lalpha = "HXUCZVAMDSLKPEFJRIGTWOBNYQ";
    string ralpha = "PTLNBQDEOYSFAVZKGJRIHWXUMC";
    string msg = "WELLDONEISBETTERTHANWELLSAID";
 
    cout << "L: " << lalpha << endl;
    cout << "R: " << ralpha << endl;
    cout << "I: " << msg << endl;
    cout << "O: " << do_chao(msg, lalpha, ralpha, 1, 0) << endl;
    cout << endl;
    do_chao(msg, lalpha, ralpha, 1, 1);
}

#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <cstdlib>
 
using namespace std;
 
int main(int argc, char *argv[]) {
 
	map<string, float> units = {
		{"arshin",0.7112},
		{"centimeter",0.01},
		{"diuym",0.0254},
		{"fut",0.3048},
		{"kilometer",1000.0},
		{"liniya",0.00254},
		{"meter",1.0},
		{"milia",7467.6},
		{"piad",0.1778},
		{"sazhen",2.1336},
		{"tochka",0.000254},
		{"vershok",0.04445},
		{"versta",1066.8}
	};
 
	if (argc < 3) {
		cerr << "A correct use is oldrus [amount] [unit]." << endl;
		exit(1);
	};
 
	float length_float;
	try {
		length_float = stof(argv[1]);
	} catch (invalid_argument) {
		length_float = 1;
	};
 
	string unit = argv[2];
	if (units.find(unit) == units.end()) {
		vector<string> keys;
		for (auto i = units.begin(); i!= units.end(); i++) {
			keys.push_back(i->first);
		};
		cerr << "The correct units are: " << keys[0];
		for (int i = 1; i < keys.size(); i++) {
			cerr << ", " << keys[i];
		};
		cerr << "." << endl;
		exit(1);
	};
 
	cout << length_float << " " << unit << " to:" << endl;
	for (auto i = units.begin(); i!= units.end(); i++) {
		cout << "	" << i->first << ": " << length_float * units[unit] / i->second << endl;
	};
 
	return 0;
}

