#include <iostream>
#include <vector>
#include <stdexcept>
 
using namespace std;
 
struct Point
{
    int X;
    int Y;
 
    Point(int x, int y)
    {
        X = x;
        Y = y;
    }
};
 
enum Direction
{
    North, East, West, South
};
 
class Langton
{
public:
    vector<vector<bool>> IsBlack;
    Point _origin;
    Point _antPosition = Point(0, 0);
    bool OutOfBounds;
 
    // I don't see any mention of what direction the ant is supposed to start out in
    Direction _antDirection = Direction::East;
 
    vector<Direction> _leftTurn = { Direction::West, Direction::North, Direction::South, Direction::East };
    vector<Direction> _rightTurn = { Direction::East, Direction::South, Direction::North, Direction::West };
    vector<int> _xInc = { 0, 1,-1, 0};
    vector<int> _yInc = { -1, 0, 0, 1};
 
    Langton(int width, int height, Point origin)
    {
        _origin = origin;
        IsBlack = vector<vector<bool>>(width, vector<bool>(height));
        OutOfBounds = false;
    }
 
    Langton(int width, int height) : Langton(width, height, Point(width / 2, height / 2)) {}
 
    void MoveAnt()
    {
        _antPosition.X += _xInc[(int)_antDirection];
        _antPosition.Y += _yInc[(int)_antDirection];
    }
 
    Point Step()
    {
        if (OutOfBounds)
        {
            throw invalid_argument("Trying to step after ant is out of bounds");
        }
        Point ptCur = Point(_antPosition.X + _origin.X, _antPosition.Y + _origin.Y);
        bool leftTurn = IsBlack[ptCur.X][ptCur.Y];
        int iDirection = (int) _antDirection;
        _antDirection = leftTurn? _leftTurn[iDirection] : _rightTurn[iDirection];
        IsBlack[ptCur.X][ptCur.Y] =!IsBlack[ptCur.X][ptCur.Y];
        MoveAnt();
        ptCur = Point(_antPosition.X + _origin.X, _antPosition.Y + _origin.Y);
        OutOfBounds = 
            ptCur.X < 0 ||
            ptCur.X >= IsBlack.size() ||
            ptCur.Y < 0 ||
            ptCur.Y >= IsBlack[0].size();
        return _antPosition;
    }
};
 
int main()
{
    Langton ant = Langton(100, 100);
 
    while (!ant.OutOfBounds) ant.Step();
 
    for (int iRow = 0; iRow < 100; iRow++)
    {
        for (int iCol = 0; iCol < 100; iCol++)
        {
            cout << (ant.IsBlack[iCol][iRow]? "#" : " ");
        }
        cout << endl;
    }
 
    cin.get();
}

// version 1.2.31
 
#include <iostream>
#include <fstream>
#include <string>
#include <regex>
#include <map>
 
using namespace std;
 
int main(int argc, char *argv[]) {
    regex rx("\\s+");
    ifstream file("readings.txt");
    int count = 0;
    int invalid = 0;
    int allGood = 0;
    map<string, int> map;
    string line;
    while (getline(file, line)) {
        count++;
        sregex_token_iterator it(line.begin(), line.end(), rx, -1);
        sregex_token_iterator end;
        vector<string> fields(it, end);
        string date = fields[0];
        if (fields.size() == 49) {
            if (map.find(date)!= map.end())
                map[date] = map[date] + 1;
            else
                map[date] = 1;
            int good = 0;
            for (int i = 2; i < fields.size(); i += 2) {
                if (stoi(fields[i]) >= 1) {
                    good++;
                }
            }
            if (good == 24) allGood++;
        }
        else invalid++;
    }
 
    cout << "File = " << file.name() << endl;
    cout << "\nDuplicated dates:" << endl;
    for (auto it = map.begin(); it!= map.end(); it++) {
        if (it->second > 1) cout << "  " << it->first << " (" << it->second << " times)" << endl;
    }
    cout << "\nTotal number of records   : " << count << endl;
    double percent = invalid / count * 100.0;
    cout << "Number of invalid records : " << invalid << " (" << percent << "%)" << endl;
    percent = allGood / count * 100.0;
    cout << "Number which are all good : " << allGood << " (" << percent << "%)" << endl;
}

