#include <iostream>
#include <functional>
 
using namespace std;
 
typedef function<bool(double)> Set;
 
Set Union(Set a, Set b) { return [a, b](double x) { return a(x) || b(x); }; }
Set Inter(Set a, Set b) { return [a, b](double x) { return a(x) && b(x); }; }
Set Diff(Set a, Set b) { return [a, b](double x) { return a(x) &&!b(x); }; }
Set open(double a, double b) { return [a, b](double x) { return a < x && x < b; }; }
Set closed(double a, double b) { return [a, b](double x) { return a <= x && x <= b; }; }
Set opCl(double a, double b) { return [a, b](double x) { return a < x && x <= b; }; }
Set clOp(double a, double b) { return [a, b](double x) { return a <= x && x < b; }; }
 
int main() {
	Set s[4];
	s[0] = Union(opCl(0, 1), clOp(0, 2));  // (0,1] ∪ [0,2)
	s[1] = Inter(clOp(0, 2), opCl(1, 2));  // [0,2) ∩ (1,2]
	s[2] = Diff(clOp(0, 3), open(0, 1));   // [0,3) − (0,1)
	s[3] = Diff(clOp(0, 3), closed(0, 1)); // [0,3) − [0,1]
 
	for (int i = 0; i < 4; i++) {
		for (double x = 0; x < 3; x++) {
			cout << x << " ∈ s" << i << ": " << s[i](x) << endl;
		}
		cout << endl;
	}
}

#include <iostream>
#include <cstdlib>
#include <ctime>
using namespace std;
 
class BeadSort
{
public:
	BeadSort()
	{
		srand(time(0));
	}
	void display1D(int arr[], int size)
	{
		for(int i=0;i<size;i++)
			cout << arr[i] << " ";
		cout << endl;
	}
	void display1D(char arr[], int size)
	{
		for(int i=0;i<size;i++)
			cout << arr[i] << " ";
		cout << endl;
	}
	void display2D(char arr[][10], int size)
	{
		for(int i=0;i<size;i++)
			display1D(arr[i], 10);
		cout << endl;
	}
	int* beadSort(int arr[], int size)
	{
		int max=arr[0];
		for(int i=1;i<size;i++)
			if(arr[i]>max)
				max=arr[i];
 
		//Set up abacus
		char grid[size][10];
		int levelcount[10];
		for(int i=0;i<10;i++)
		{
			levelcount[i]=0;
			for(int j=0;j<size;j++)
				grid[j][i]='_';
		}
		/*
		display1D(arr, size);
		display1D(levelcount, 10);
		display2D(grid, size);
		*/
 
		//Drop the beads
		for(int i=0;i<size;i++)
		{
			int num=arr[i];
			for(int j=0;num>0;j++)
			{
				grid[levelcount[j]++][j]='*';
				num--;
			}
		}
		cout << endl;
		display2D(grid, size);
		//Count the beads
		int* sorted=new int[size];
		for(int i=0;i<size;i++)
		{
			int putt=0;
			for(int j=0;j<10&&grid[size-1-i][j]=='*';j++)
				putt++;
			sorted[i]=putt;
		}
 
		return sorted;
	}
};
 
int main()
{
	BeadSort now;
	int size=(rand()%11)+5;
	int* arr=new int[size];
	for(int i=0;i<size;i++)
		arr[i]=(rand()%10);
	cout << "Unsorted: ";
	now.display1D(arr, size);
 
