#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>
 
using namespace std;
 
template <typename T>
void pancake_sort(vector<T>& v) {
    int num_flips = 0;
    for (int end_idx = v.size()-1; end_idx > 0; --end_idx) {
        auto max_it = max_element(v.begin(), v.begin()+end_idx+1);
        int max_idx = max_it - v.begin();
        if (max_idx == end_idx) continue;
 
        if (max_idx > 0) {
            reverse(v.begin(), v.begin()+max_idx+1);
            ++num_flips;
            copy(v.begin(), v.end(), ostream_iterator<T>(cout, " "));
            cout << endl;
        }
 
        reverse(v.begin(), v.begin()+end_idx+1);
        ++num_flips;
        copy(v.begin(), v.end(), ostream_iterator<T>(cout, " "));
        cout << endl;
    }
}
 
int main() {
    vector<int> v = {1, 2, 3, 4, 5, 6, 7, 8, 9};
    random_shuffle(v.begin(), v.end());
    copy(v.begin(), v.end(), ostream_iterator<int>(cout, " "));
    cout << endl;
    pancake_sort(v);
    copy(v.begin(), v.end(), ostream_iterator<int>(cout, " "));
    cout << endl;
}

#include <iostream>
#include <vector>
#include <cmath>
 
using namespace std;
 
vector<int> eratosthenes(int n)
{
    vector<int> nums;
    nums.push_back(0);
    nums.push_back(0);
    for (int i = 2; i <= n; i++)
        nums.push_back(i);
    for (int i = 2; i <= sqrt(n); i++)
    {
        if (nums[i]!= 0)
        {
            for (int j = i*i; j <= n; j += i)
                nums[j] = 0;
        }
    }
    vector<int> result;
    for (int i = 0; i < nums.size(); i++)
    {
        if (nums[i]!= 0)
            result.push_back(nums[i]);
    }
    return result;
}
 
int main()
{
    vector<int> result = eratosthenes(100);
    for (int i = 0; i < result.size(); i++)
        cout << result[i] << " ";
    cout << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <sstream>
 
using namespace std;
 
class Crutch {
public:
    int len;
    vector<int> s;
    int i;
 
    Crutch(int len) {
        this->len = len;
        s = vector<int>(len);
        i = 0;
    }
 
    void Repeat(int count) {
        for (int j = 0; j < count; j++) {
            if (++i == len) return;
            s[i] = s[i - 1];
        }
    }
};
 
class Extension {
public:
    static int NextInCycle(vector<int> self, int index) {
        return self[index % self.size()];
    }
 
    static vector<int> Kolakoski(vector<int> self, int len) {
        Crutch c = Crutch(len);
 
        int k = 0;
        while (c.i < len) {
            c.s[c.i] = NextInCycle(self, k);
            if (c.s[k] > 1) {
                c.Repeat(c.s[k] - 1);
            }
            if (++c.i == len) return c.s;
            k++;
        }
        return c.s;
    }
 
    static bool PossibleKolakoski(vector<int> self) {
        vector<int> rle(self.size());
        int prev = self[0];
        int count = 1;
        int pos = 0;
        for (int i = 1; i < self.size(); i++) {
            if (self[i] == prev) {
                count++;
            }
            else {
                rle[pos++] = count;
                count = 1;
                prev = self[i];
            }
        }
        // no point adding final 'count' to rle as we're not going to compare it anyway
        for (int i = 0; i < pos; i++) {
            if (rle[i]!= self[i]) {
                return false;
            }
        }
        return true;
    }
 
    static string AsString(vector<int> self) {
        stringstream sb;
        sb << "[";
        int count = 0;
        for (auto item : self) {
            if (count > 0) {
                sb << ", ";
            }
            sb << item;
            count++;
        }
        sb << "]";
        return sb.str();
    }
};
 
int main() {
    vector<vector<int>> ias = {
        vector<int>{1, 2},
        vector<int>{2, 1},
        vector<int>{1, 3, 1, 2},
        vector<int>{1, 3, 2, 1}
    };
    vector<int> lens = { 20, 20, 30, 30 };
 
    for (int i = 0; i < ias.size(); i++) {
        int len = lens[i];
        vector<int> kol = Extension::Kolakoski(ias[i], len);
 
        cout << "First " << len << " members of the sequence by " << Extension::AsString(ias[i]) << ": " << endl;
        cout << Extension::AsString(kol) << endl;
        cout << "Possible Kolakoski sequence? " << Extension::PossibleKolakoski(kol) << endl;
        cout << endl;
    }
}

