using namespace boost::multiprecision;

int main()
{
  C++_bin_float_50 a = 1;
  C++_bin_float_50 g = 1 / sqrt(C++_bin_float_50(2));
  C++_bin_float_50 z = 0.25;
  C++_int n = 1;
  for(int i = 0; i < 17; ++i)
  {
    C++_bin_float_50 x[2] = { (a + g) * 0.5, sqrt(a * g) };
    C++_bin_float_50 var = x[0] - a;
    z -= var * var * n;
    n += n;
    a = x[0];
    g = x[1];
  }
