#include <iostream>
#include <vector>
#include <stdexcept>
 
using namespace std;
 
vector<vector<int>> magicSquareDoublyEven(int n) {
    if ( n < 4 || n % 4!= 0) 
        throw invalid_argument("Base must be a positive multiple of 4");
 
    // pattern of count-up vs count-down zones
    int bits = 0b1001011001101001;
    int size = n * n;
    int mult = n / 4;  // how many multiples of 4 
    vector<vector<int>> result(n, vector<int>(n));
    int i = 0;
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++) {
            int bitPos = c / mult + r / mult * 4;
            result[r][c] =  (bits & (1 << bitPos))? i + 1 : size - i;
            i++;
        }
    return result;
} 
 
int main() {
    int n = 8;
    auto result = magicSquareDoublyEven(n);
    for (auto& ia : result) { 
        for (auto i : ia) cout << setw(2) << i << "  ";
        cout << endl;
    }
    cout << "\nMagic constant " << (n * n + 1) * n / 2 << endl;
}

