#include <iostream>
 
int sumDigits(int n) {
    if (n <= 0) return 0;
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}
 
bool isHarshad(int n) {
    return (n % sumDigits(n) == 0);
}
 
int main() {
    std::cout << "The first 20 Harshad numbers are:" << std::endl;
    int count = 0;
    int i = 0;
 
    while (true) {
        if (isHarshad(++i)) {
            std::cout << i << " ";
            if (++count == 20) break;
        }
    }
 
    std::cout << "\n\nThe first Harshad number above 1000 is:" << std::endl;
    i = 1000;
 
    while (true) {
        if (isHarshad(++i)) {
            std::cout << i << std::endl;
            return 0;
        }
    }
}

#include <iostream>
 
using namespace std;
 
int main()
{
	int q = 929;
	if (!isPrime(q) ) return 0;
	int r = q;
	while( r > 0 ) 
		r <<= 1;
	int d = 2 * q + 1;
	do
	{
		int i = 1;
		for( int p=r; p!=0; p<<=1 )
		{
			i = (i*i) % d;
			if (p < 0) i *= 2;
			if (i > d) i -= d;
		}
		if (i!= 1) d += 2 * q; else break;				
	}
	while(true);
 
//	cout << "2^" << q << "-1 = 0 (mod " << d << ")" << endl; 
	return 0;
}
 
bool isPrime(int n)
{
	if ( n % 2 == 0 ) return n == 2;
	if ( n % 3 == 0 ) return n == 3;
	int d = 5;
	while( d*d <= n )
	{
		if ( n % d == 0 ) return false;
		d += 2;
		if ( n % d == 0 ) return false;
		d += 4;
	}
	return true;
}

