// jewelCount :: String -> String -> Int
int jewelCount(string j, string s) {
    vector<char> js(j.begin(), j.end());
    return accumulate(s.begin(), s.end(), 0,
        [&js](int a, char c) {
            return find(js.begin(), js.end(), c)!= js.end()? a + 1 : a;
        });
}

