#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
#include <cmath>
 
using namespace std;
 
double jaroSim(string str1, string str2) {
    if (str1.length() == 0 && str2.length() == 0) {
        return 1;
    }
    if (str1.length() == 0 || str2.length() == 0) {
        return 0;
    }
    int match_distance = str1.length();
    if (str2.length() > match_distance) {
        match_distance = str2.length();
    }
    match_distance = match_distance/2 - 1;
    vector<bool> str1_matches(str1.length());
    vector<bool> str2_matches(str2.length());
    double matches = 0.;
    double transpositions = 0.;
    for (int i = 0; i < str1.length(); i++) {
        int start = i - match_distance;
        if (start < 0) {
            start = 0;
        }
        int end = i + match_distance + 1;
        if (end > str2.length()) {
            end = str2.length();
        }
        for (int k = start; k < end; k++) {
            if (str2_matches[k]) {
                continue;
            }
            if (str1[i]!= str2[k]) {
                continue;
            }
            str1_matches[i] = true;
            str2_matches[k] = true;
            matches++;
            break;
        }
    }
    if (matches == 0) {
        return 0;
    }
    int k = 0;
    for (int i = 0; i < str1.length(); i++) {
        if (!str1_matches[i]) {
            continue;
        }
        while (!str2_matches[k]) {
            k++;
        }
        if (str1[i]!= str2[k]) {
            transpositions++;
        }
        k++;
    }
    transpositions /= 2;
    return (matches/str1.length() +
        matches/str2.length() +
        (matches-transpositions)/matches) / 3;
}
 
double jaroWinklerDist(string s, string t) {
    int ls = s.length();
    int lt = t.length();
    int lmax = lt;
    if (ls < lt) {
        lmax = ls;
    }
    if (lmax > 4) {
        lmax = 4;
    }
    int l = 0;
    for (int i = 0; i < lmax; i++) {
        if (s[i] == t[i]) {
            l++;
        }
    }
    double js = jaroSim(s, t);
    double p = 0.1;
    double ws = js + l*p*(1-js);
    return 1 - ws;
}
 
struct wd {
    string word;
    double dist;
};
 
int main() {
    vector<string> misspelt = {
        "accomodate", "definately", "goverment", "occured", "publically",
        "recieve", "seperate", "untill", "wich",
    };
    ifstream f("unixdict.txt");
    string line;
    vector<string> words;
    while (getline(f, line)) {
        words.push_back(line);
    }
    for (auto ms : misspelt) {
        vector<wd> closest;
        for (auto w : words) {
            if (w == "") {
                continue;
            }
            double jwd = jaroWinklerDist(ms, w);
            if (jwd < 0.15) {
                closest.push_back({w, jwd});
            }
        }
        cout << "Misspelt word: " << ms << ":" << endl;
        sort(closest.begin(), closest.end(), [](wd a, wd b) { return a.dist < b.dist; });
        for (int i = 0; i < closest.size(); i++) {
            cout << closest[i].dist << " " << closest[i].word << endl;
            if (i == 5) {
                break;
            }
        }
        cout << endl;
    }
}

#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>
using namespace std;
 
void main(int s, int e, int bs, int pbs) {
    bs = bs || 10;
    pbs = pbs || 10;
    cout << "start: " << toString(s) << " end: " << toString(e) << " base: " << bs << " printBase: " << pbs << endl;
    cout << "castOutNine: ";
    castOutNine();
    cout << "kaprekar: ";
    kaprekar();
    cout << endl;
 
    void castOutNine() {
        for (int n = s, k = 0, bsm1 = bs - 1; n <= e; n += 1)
            if (n % bsm1 == (n * n) % bsm1) k += 1,
                cout << toString(n) << " ";
        cout << "trying " << k << " numbers instead of " << n = e - s + 1 << " numbers saves " << (100 - k / n * 100) << "%" << endl;
    }
 
    void kaprekar() {
        for (int n = s; n <= e; n += 1)
            if (isKaprekar(n)) cout << toString(n) << " ";
 
        bool isKaprekar(int n) {
            if (n < 1) return false;
            if (n == 1) return true;
            stringstream ss;
            ss << (n * n);
            string s = ss.str();
            for (int i = 1, e = s.length(); i < e; i += 1) {
                string a = s.substr(0, i);
                string b = s.substr(i);
                if (b!= "" && stoi(a) + stoi(b) == n) return true;
            }
            return false;
        }
    }
 
    string toString(int n) {
        stringstream ss;
        ss << hex << n;
        string s = ss.str();
        return s;
    }
}
main(1, 10 * 10 - 1);
main(1, 16 * 16 - 1, 16);
main(1, 17 * 17 - 1, 17);
main(stoi("10", 0, 17), stoi("gg", 0, 17), 17, 17);

