#include <iostream>
#include <vector>
#include <algorithm>
 
using namespace std;
 
vector<int> getLis(vector<int> input) {
  if (input.size() == 0) {
    return vector<int>();
  }
 
  vector<int> lisLenPerIndex(input.size(), 1);
  pair<int, int> max = { 0, 1 };
 
  for (int i = 0; i < input.size(); i++) {
    lisLenPerIndex[i] = 1;
    for (int j = i - 1; j >= 0; j--) {
      if (input[i] > input[j] && lisLenPerIndex[j] >= lisLenPerIndex[i]) {
        int length = lisLenPerIndex[i] = lisLenPerIndex[j] + 1;
        if (length > max.second) {
          max = { i, length };
        }
      }
    }
  }
 
  vector<int> lis = { input[max.first] };
  for (int i = max.first; i >= 0 && max.second!= 0; i--) {
    if (input[max.first] > input[i] && lisLenPerIndex[i] == max.second - 1) {
      lis.insert(lis.begin(), input[i]);
      max.second--;
    }
  }
 
  return lis;
}
 
int main() {
  vector<int> input = { 0, 7, 8, 4, 12, 2, 10, 6, 14, 1, 9, 5, 13, 3, 11, 7, 15 };
  vector<int> lis = getLis(input);
  for (int i = 0; i < lis.size(); i++) {
    cout << lis[i] << " ";
  }
  cout << endl;
 
  input = { 3, 2, 6, 4, 5, 1 };
  lis = getLis(input);
  for (int i = 0; i < lis.size(); i++) {
    cout << lis[i] << " ";
  }
  cout << endl;
 
  return 0;
}

