#include <iostream>
#include <cmath>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

int factorial(int n) {
	return n <= 1? 1 : n * factorial(n - 1);
}

int M(int n) {
	return (n - (n % 2!= 0)) / 2;
}

double gaussLegendre(double (*fn)(double), double a, double b, int n) {
	vector<double> coef(M(n) + 1);
	for (int m = 0; m < coef.size(); m++) {
		coef[m] = pow(-1, m) * factorial(2 * n - 2 * m) / (pow(2, n) * factorial(m) * factorial(n - m) * factorial(n - 2 * m));
	}
	auto f = [coef](double x) {
		double sum = 0;
		for (int i = 0; i < coef.size(); i++) {
			sum += coef[i] * pow(x, n - 2 * i);
		}
		return sum;
	};
	int terms = coef.size() - (n % 2 == 0);
	vector<double> dcoef(terms);
	for (int i = 0; i < dcoef.size(); i++) {
		dcoef[i] = (n - 2 * i) * coef[i];
	}
	auto df = [dcoef](double x) {
		double sum = 0;
		for (int i = 0; i < dcoef.size(); i++) {
			sum += dcoef[i] * pow(x, n - 1 - 2 * i);
		}
		return sum;
	};
	vector<double> guess(n);
	for (int i = 0; i < guess.size(); i++) {
		guess[i] = cos(M_PI * (i + 1 - 1 / 4) / (n + 1 / 2));
	}
	vector<double> roots(n);
	for (int i = 0; i < roots.size(); i++) {
		roots[i] = guess[i];
		for (int j = 0; j < 100; j++) {
			roots[i] -= f(roots[i]) / df(roots[i]);
		}
	}
	vector<double> weights(n);
	for (int i = 0; i < weights.size(); i++) {
		weights[i] = 2 / ((1 - pow(roots[i], 2)) * pow(df(roots[i]), 2));
	}
	double sum = 0;
	for (int i = 0; i < weights.size(); i++) {
		sum += weights[i] * fn((b - a) * roots[i] / 2 + (a + b) / 2);
	}
	return (b - a) / 2 * sum;
}

int main() {
	cout << gaussLegendre([](double x) { return exp(x); }, -3, 3, 5) << endl;
	return 0;
}

