#include <iostream>
#include <cmath>
 
using namespace std;
 
int powers[10];
 
bool isMunchausen(int n) {
    if (n < 0) return false;
    long sum = 0;
    int nn = n;
    while (nn > 0) {
        sum += powers[nn % 10];
        if (sum > n) return false;
        nn /= 10;
    }
    return sum == n;  
}
 
int main() {
   // cache n ^ n for n in 0..9, defining 0 ^ 0 = 0 for this purpose
   for (int i = 1; i <= 9; i++) powers[i] = pow(i, i);
 
   // check numbers 0 to 500 million
   cout << "The Munchausen numbers between 0 and 500 million are:" << endl;
   for (int i = 0; i <= 500000000; i++) if (isMunchausen(i)) cout << i << " ";
   cout << endl;
}

#include <iostream>
