using namespace std;
 
const int FIRST_YEAR = 1900;
const int LAST_YEAR = 2100;
const vector<int> _31_MONTHS = { 1, 3, 5, 7, 8, 10, 12 };
 
int main()
{
    int totalNum = 0;
    int totalNo5Weekends = 0;
 
    for (int year = FIRST_YEAR; year <= LAST_YEAR; year++)
    {
        bool has5Weekends = false;
 
        for (int month : _31_MONTHS)
        {
            tm firstDay = { 0, 0, 0, 1, month - 1, year - 1900 };
            mktime(&firstDay);
            if (firstDay.tm_wday == 5)
            {
                totalNum++;
                has5Weekends = true;
                cout << put_time(&firstDay, "%Y - %B") << endl;
            }
        }
 
        if (!has5Weekends) totalNo5Weekends++;
    }
    cout << "Total 5-weekend months between " << FIRST_YEAR << " and " << LAST_YEAR << ": " << totalNum << endl;
    cout << "Total number of years with no 5-weekend months " << totalNo5Weekends << endl;
}

#include <iostream>
#include <string>
#include <cmath>
 
using namespace std;
 
template <typename T>
class Maybe
{
public:
    class Some
    {
    public:
        Some(T value) : value(value) {}
        T value;
    };
    class None
    {
    };
};
 
Maybe<double> MonadicSquareRoot(double x)
{
    if (x >= 0)
    {
        return Maybe<double>::Some(sqrt(x));
    }
    else
    {
        return Maybe<double>::None();
    }
}
 
int main()
{
    for (double x : { 4.0, 8.0, -15.0, 16.23, -42 })
    {
        Maybe<double> maybe = MonadicSquareRoot(x);
        if (maybe.is<Maybe<double>::Some>())
        {
            cout << "The square root of " << x << " is " << maybe.as<Maybe<double>::Some>().value << endl;
        }
        else
        {
            cout << "Square root of " << x << " is undefined." << endl;
        }
    }
}

