#include <string>
#include <vector>
#include <algorithm>
#include <iterator>
#include <cassert>
 
using namespace std;
 
map<string, set<string> > data = {
    {"des_system_lib", {"std", "synopsys", "std_cell_lib", "des_system_lib", "dw02", "dw01", "ramlib", "ieee"}},
    {"dw01", {"ieee", "dw01", "dware", "gtech"}},
    {"dw02", {"ieee", "dw02", "dware"}},
    {"dw03", {"std", "synopsys", "dware", "dw03", "dw02", "dw01", "ieee", "gtech"}},
    {"dw04", {"dw04", "ieee", "dw01", "dware", "gtech"}},
    {"dw05", {"dw05", "ieee", "dware"}},
    {"dw06", {"dw06", "ieee", "dware"}},
    {"dw07", {"ieee", "dware"}},
    {"dware", {"ieee", "dware"}},
    {"gtech", {"ieee", "gtech"}},
    {"ramlib", {"std", "ieee"}},
    {"std_cell_lib", {"ieee", "std_cell_lib"}},
    {"synopsys", {}}
};
 
vector<string> toposort2(map<string, set<string> > data) {
    for (auto& kv : data) {
        kv.second.erase(kv.first); // Ignore self dependencies
    }
    set<string> extra_items_in_deps;
    for (auto& kv : data) {
        extra_items_in_deps.insert(kv.second.begin(), kv.second.end());
    }
    extra_items_in_deps.erase(data.begin(), data.end());
    for (auto& item : extra_items_in_deps) {
        data[item] = set<string>();
    }
    vector<string> ordered;
    while (true) {
        for (auto& kv : data) {
            if (kv.second.empty()) {
                ordered.push_back(kv.first);
            }
        }
        if (ordered.empty()) {
            break;
        }
        for (auto& item : ordered) {
            data.erase(item);
        }
        for (auto& kv : data) {
            for (auto& item : ordered) {
                kv.second.erase(item);
            }
        }
    }
    assert(data.empty());
    return ordered;
}
 
int main() {
    vector<string> ordered = toposort2(data);
    copy(ordered.begin(), ordered.end(), ostream_iterator<string>(cout, " "));
    cout << endl;
}

#include <iostream>
#include <vector>
 
using namespace std;
 
int main()
{
	cout << DotProduct(vector<int> { 1, 3, -5 }, vector<int> { 4, -2, -1 }) << endl;
	cin.get();
}
 
int DotProduct(vector<int> vec1, vector<int> vec2)
{
	if (vec1.size() == 0)
		return 0;
 
	if (vec2.size() == 0)
		return 0;
 
	if (vec1.size()!= vec2.size())
		return 0;
 
	int tVal = 0;
	for (int x = 0; x < vec1.size(); x++)
	{
		tVal += vec1[x] * vec2[x];
	}
 
	return tVal;
}

