#include <iostream>
#include <string>
#include <vector>
#include <cmath>
#include <ctime>
#include <cstdlib>
#include <stdexcept>
 
using namespace std;
 
const vector<string> inputs = {"23:00:17", "23:40:20", "00:12:45", "00:17:19"};
 
int main() {
    vector<time_t> tList(inputs.size());
    const string clockFmt = "%H:%M:%S";
    struct tm tm;
    for (size_t i = 0; i < inputs.size(); i++) {
        if (strptime(inputs[i].c_str(), clockFmt.c_str(), &tm) == NULL) {
            throw runtime_error("strptime");
        }
        tList[i] = mktime(&tm);
    }
    time_t mean = meanTime(tList);
    char buf[100];
    if (strftime(buf, sizeof(buf), clockFmt.c_str(), localtime(&mean)) == 0) {
        throw runtime_error("strftime");
    }
    cout << buf << endl;
}
 
time_t meanTime(const vector<time_t>& times) {
    if (times.size() == 0) {
        throw runtime_error("meanTime: no times specified");
    }
    double ssum = 0, csum = 0;
    for (auto t : times) {
        struct tm tm;
        if (localtime_r(&t, &tm) == NULL) {
            throw runtime_error("localtime_r");
        }
        double fSec = (tm.tm_hour*60+tm.tm_min)*60+tm.tm_sec + tm.tm_nsec*1e-9;
        double sin, cos;
        sincos(fSec * M_PI / (12 * 60 * 60), &sin, &cos);
        ssum += sin;
        csum += cos;
    }
    if (ssum == 0 && csum == 0) {
        throw runtime_error("meanTime: mean undefined");
    }
    double dayFrac = 1 + atan2(ssum, csum)/(2*M_PI);
    return time_t(dayFrac * 24 * 3600);
}

#include <iostream>
#include <vector>
#include <stdexcept>
 
class FIFO {
public:
    FIFO() {}
    FIFO(std::vector<int> args) : contents(args) {}
    int pop() {
        int ret = contents.front();
        contents.erase(contents.begin());
        return ret;
    }
    void push(int item) {
        contents.push_back(item);
    }
    void extend(std::vector<int> itemlist) {
        contents.insert(contents.end(), itemlist.begin(), itemlist.end());
    }
    bool empty() {
        return contents.empty();
    }
    int operator()() {
        return pop();
    }
    int operator[](int i) {
        return contents[i];
    }
    int size() {
        return contents.size();
    }
private:
    std::vector<int> contents;
};
 
int main() {
    FIFO f;
    f.push(3);
    f.push(2);
    f.push(1);
    while (!f.empty()) {
        std::cout << f.pop() << " ";
    }
    std::cout << std::endl;
    // Another simple example gives the same results:
    f = FIFO(std::vector<int>({3,2,1}));
    while (!f.empty()) {
        std::cout << f() << " ";
    }
    std::cout << std::endl;
    // Another using the default "truth" value of the object
    // (implicitly calls on the length() of the object after
    // checking for a __nonzero__ method
    f = FIFO(std::vector<int>({3,2,1}));
    while (f) {
        std::cout << f() << " ";
    }
    std::cout << std::endl;
    // Yet another, using more Pythonic iteration:
    f = FIFO(std::vector<int>({3,2,1}));
    for (int i : f) {
        std::cout << i << " ";
    }
    std::cout << std::endl;
}

