#include <iostream>
#include <vector>
#include <limits>
#include <algorithm>
 
using namespace std;
 
void floyd_warshall(int n, vector<vector<int> > edge)
{
    vector<vector<int> > dist(n, vector<int>(n));
    vector<vector<int> > nxt(n, vector<int>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dist[i][j] = i==j? 0 : numeric_limits<int>::max();
        }
    }
    for (int i = 0; i < edge.size(); i++) {
        int u = edge[i][0] - 1;
        int v = edge[i][1] - 1;
        int w = edge[i][2];
        dist[u][v] = w;
        nxt[u][v] = v;
    }
 
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][j] > dist[i][k] + dist[k][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                    nxt[i][j] = nxt[i][k];
                }
            }
        }
    }
 
    cout << "pair     dist    path" << endl;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int u = i;
            vector<int> path;
            path.push_back(u);
            while (u!= j) {
                u = nxt[u][j];
                path.push_back(u);
            }
            cout << i+1 << " -> " << j+1 << "  " << dist[i][j] << "     ";
            for (int k = 0; k < path.size(); k++) {
                cout << path[k]+1;
                if (k+1 < path.size()) cout << " -> ";
            }
            cout << endl;
        }
    }
}
 
int main()
{
    int n = 4;
    vector<vector<int> > edge = {
        {1, 3, -2},
        {2, 1, 4},
        {2, 3, 3},
        {3, 4, 2},
        {4, 2, -1}
    };
    floyd_warshall(n, edge);
}

