std::string split(std::string str)
{
  std::cout << " input string: " << str << std::endl;
  std::vector<std::string> v;
  std::string s;
  std::string::iterator it = str.begin();
  while (it!= str.end())
  {
    s = *it;
    ++it;
    while (it!= str.end() && *it == *s.begin())
    {
      s += *it;
      ++it;
    }
    v.push_back(s);
  }
  std::string result = std::accumulate(v.begin(), v.end(), std::string(), [](std::string a, std::string b) { return a + ", " + b; });
  std::cout << "output string: " << result << std::endl;
  return result;
}
 
