#include <iostream>
#include <vector>
#include <functional>
 
using namespace std;
 
void comb(int n, int m, function<void(vector<int>)> emit) {
    vector<int> s(m);
    int last = m - 1;
    function<void(int, int)> rc;
    rc = [&](int i, int next) {
        for (int j = next; j < n; j++) {
            s[i] = j;
            if (i == last) {
                emit(s);
            } else {
                rc(i + 1, j + 1);
            }
        }
        return;
    };
    rc(0, 0);
}
 
int main() {
    comb(5, 3, [](vector<int> c) {
        for (int i = 0; i < c.size(); i++) {
            cout << c[i] << " ";
        }
        cout << endl;
    });
}

