bool factorion(int n, int base) {
  vector<int> digits;
  while (n > 0) {
    digits.push_back(n % base);
    n /= base;
  }
  int sum = accumulate(digits.begin(), digits.end(), 0, [](int a, int b) {
    return a + tgamma(b + 1);
  });
  return sum == n;
}
 
int main() {
  for (int base = 9; base <= 12; base++) {
    cout << "Base " << base << " factorions: ";
    for (int n = 1; n <= 1500000; n++) {
      if (factorion(n, base)) {
        cout << n << " ";
      }
    }
    cout << endl;
  }
}

