#include <iostream>
#include <string>
#include <vector>
#include <regex>
#include <stdexcept>
 
using namespace std;
 
class RangeExpander {
private:
    static const regex TOKEN_PATTERN;
 
    vector<string> tokens;
    vector<string>::iterator tokensIterator;
 
    bool inRange;
    int upperRangeEndpoint;
    int nextRangeValue;
 
    bool hasNextRangeValue() {
        return this->inRange && this->nextRangeValue <= this->upperRangeEndpoint;
    }
 
public:
    RangeExpander(string range) {
        this->tokens = vector<string>();
        this->tokensIterator = this->tokens.begin();
 
        string token;
        stringstream rangeStream(range);
        while (getline(rangeStream, token, ',')) {
            this->tokens.push_back(token);
        }
 
        this->tokensIterator = this->tokens.begin();
    }
 
    bool hasNext() {
        return this->hasNextRangeValue() || this->tokensIterator!= this->tokens.end();
    }
 
    int next() {
        if (!this->hasNext()) {
            throw out_of_range("No more elements");
        }
 
        if (this->hasNextRangeValue()) {
            return this->nextRangeValue++;
        }
 
        string token = *this->tokensIterator;
        this->tokensIterator++;
 
        smatch matcher;
        if (regex_search(token, matcher, TOKEN_PATTERN)) {
            this->inRange = true;
            this->upperRangeEndpoint = stoi(matcher[2]);
            this->nextRangeValue = stoi(matcher[1]);
            return this->nextRangeValue++;
        }
 
        this->inRange = false;
        return stoi(token);
    }
 
    RangeExpander* iterator() {
        return this;
    }
 
};
 
const regex RangeExpander::TOKEN_PATTERN("([+-]?\\d+)-([+-]?\\d+)");
 
int main() {
    RangeExpander re("-6,-3--1,3-5,7-11,14,15,17-20");
    for (int i : re) {
        cout << i << " ";
    }
 
    return 0;
}

#include <iostream>
#include <cmath>
#include <vector>
#include <chrono>
 
using namespace std;
 
uint L(uint n)
{
    n -= n & 1; n--;
    for (uint d, d1 = 100; ; n -= 2)
    {
        while (n % 3 == 0 || n % 5 == 0 || n % 7 == 0) n -= 2;
        if ((d = n % 10) == 3 || d == 7)
        {
            while (d1 < n && d < (d = n % d1) && isP(d)) d1 *= 10;
            if (d1 > n && isP(n)) return n; d1 = 100;
        }
    }
}
 
uint R(uint m)
{
    vector<uint> p = { 2, 3, 5, 7 }; uint n = 20, np;
    for (int i = 1; i < p.size(); n = 10 * p[i++])
    {
        if ((np = n + 1) >= m) break; if (isP(np)) p.push_back(np);
        if ((np = n + 3) >= m) break; if (isP(np)) p.push_back(np);
        if ((np = n + 7) >= m) break; if (isP(np)) p.push_back(np);
        if ((np = n + 9) >= m) break; if (isP(np)) p.push_back(np);
    }
    return p[p.size() - 1];
}
 
bool isP(uint n)
{
    if (n < 7) return n == 2 || n == 3 || n == 5;
    if ((n & 1) == 0 || n % 3 == 0 || n % 5 == 0) return false;
    for (uint r = (uint)sqrt(n), d = 7; d <= r; d += 30)
        if (n % (d + 00) == 0 || n % (d + 04) == 0 ||
            n % (d + 06) == 0 || n % (d + 10) == 0 ||
            n % (d + 12) == 0 || n % (d + 16) == 0 ||
            n % (d + 22) == 0 || n % (d + 24) == 0) return false;
    return true;
}
 
int main()
{
    uint m = 1000000;
    cout << "L " << L(m) << " R " << R(m) << "  ";
    auto start = chrono::high_resolution_clock::now();
    for (int i = 1000; i > 0; i--) { L(m); R(m); }
    auto end = chrono::high_resolution_clock::now();
    cout << chrono::duration_cast<chrono::milliseconds>(end - start).count() << "ms";
    cin.get();
}

#include <iostream>
#include <vector>
#include <numeric>
 
std::vector<int> EquilibriumIndices(std::vector<int> sequence)
{
    std::vector<int> result;
    int left = 0;
    int right = std::accumulate(sequence.begin(), sequence.end(), 0);
    int index = 0;
    for (auto element : sequence)
    {
        right -= element;
        if (left == right)
        {
            result.push_back(index);
        }
        left += element;
        index++;
    }
    return result;
}
 
int main()
{
    for (auto index : EquilibriumIndices({ -7, 1, 5, 2, -4, 3, 0 }))
    {
        std::cout << index << std::endl;
    }
}

