#include <iostream>
#include <cmath>
 
#define R 6371
#define TO_RAD (3.1415926536 / 180)
double dist(double th1, double ph1, double th2, double ph2)
{
	double dx, dy, dz;
	ph1 -= ph2;
	ph1 *= TO_RAD, th1 *= TO_RAD, th2 *= TO_RAD;
 
	dz = sin(th1) - sin(th2);
	dx = cos(ph1) * cos(th1) - cos(th2);
	dy = sin(ph1) * cos(th1);
	return asin(sqrt(dx * dx + dy * dy + dz * dz) / 2) * 2 * R;
}
 
int main()
{
	double d = dist(36.12, -86.67, 33.94, -118.4);
	/* Americans don't know kilometers */
	std::cout << "dist: " << d << " km (" << d / 1.609344 << " mi.)\n";
 
	return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
 
using namespace std;
 
typedef unsigned long long ham;
 
vector<ham> q;
 
void qpush(ham h)
{
	int i, j;
	if (q.size() <= q.size()) {
		q.resize(q.size() * 2);
	}
 
	for (i = q.size(); (j = i/2) && q[j] > h; q[i] = q[j], i = j);
	q[i] = h;
}
 
ham qpop()
{
	int i, j;
	ham r, t;
	/* outer loop for skipping duplicates */
	for (r = q[1]; q.size() > 1 && r == q[1]; q[i] = t) {
		/* inner loop is the normal down heap routine */
		for (i = 1, t = q[--q.size()]; (j = i * 2) < q.size();) {
			if (j + 1 < q.size() && q[j] > q[j+1]) j++;
			if (t <= q[j]) break;
			q[i] = q[j], i = j;
		}
	}
 
	return r;
}
 
int main()
{
	int i;
	ham h;
 
	for (qpush(i = 1); i <= 1691; i++) {
		/* takes smallest value, and queue its multiples */
		h = qpop();
		qpush(h * 2);
		qpush(h * 3);
		qpush(h * 5);
 
		if (i <= 20 || i == 1691)
			cout << i << ": " << h << endl;
	}
 
	return 0;
}

