#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <iterator>
#include <numeric>
#include <cmath>
 
using namespace std;
 
class Integer
{
public:
    Integer(int n) : n(n) {}
    int popcount() const
    {
        return count(digits(2).begin(), digits(2).end(), '1');
    }
    bool evil() const
    {
        return n >= 0 && popcount() % 2 == 0;
    }
private:
    int n;
    string digits(int base) const
    {
        string result;
        int n = this->n;
        while (n > 0)
        {
            result.push_back('0' + n % base);
            n /= base;
        }
        reverse(result.begin(), result.end());
        return result;
    }
};
 
int main()
{
    vector<int> powers_of_3;
    transform(begin(powers_of_3), end(powers_of_3), ostream_iterator<int>(cout, " "),
              [](int n) { return pow(3, n); });
    cout << endl;
 
    vector<int> evil;
    copy_if(begin(evil), end(evil), ostream_iterator<int>(cout, " "),
            [](int n) { return Integer(n).evil(); });
    cout << endl;
 
    vector<int> odious;
    copy_if(begin(odious), end(odious), ostream_iterator<int>(cout, " "),
            [](int n) { return!Integer(n).evil(); });
    cout << endl;
}

#include <stdint.h> /* intptr_t */
#include <stdio.h>
#include <stdlib.h> /* bsearch */
#include <string.h>
#include <search.h> /* lfind */
 
#define LEN(x) (sizeof(x) / sizeof(x[0]))
 
struct cd {
    char *name;
    double population;
};
 
/* Return -1 if name could not be found */
int search_get_index_by_name(const char *name, const struct cd *data, const size_t data_length,
        int (*cmp_func)(const void *, const void *))
{
    struct cd key = { (char *) name, 0 };
    struct cd *match = bsearch(&key, data, data_length,
            sizeof(struct cd), cmp_func);
 
    if (match == NULL)
        return -1;
    else
        return ((intptr_t) match - (intptr_t) data) / sizeof(struct cd);
}
 
/* Return -1 if no matching record can be found */
double search_get_pop_by_name(const char *name, const struct cd *data, size_t data_length,
        int (*cmp_func)(const void *, const void *))
{
    struct cd key = { (char *) name, 0 };
    struct cd *match = lfind(&key, data, &data_length,
            sizeof(struct cd), cmp_func);
 
    if (match == NULL)
        return -1;
    else
        return match->population;
}
 
/* Return NULL if no value satisfies threshold */
char* search_get_pop_threshold(double pop_threshold, const struct cd *data, size_t data_length,
        int (*cmp_func)(const void *, const void *))
{
    struct cd key = { NULL, pop_threshold };
    struct cd *match = lfind(&key, data, &data_length,
            sizeof(struct cd), cmp_func);
 
    if (match == NULL)
        return NULL;
    else
        return match->name;
}
 
int cd_nameChar_cmp(const void *a, const void *b)
{
    struct cd *aa = (struct cd *) a;
    struct cd *bb = (struct cd *) b;
 
	int i,len = strlen(aa->name);
 
	for(i=0;i<len;i++)
		if(bb->name[i]!=aa->name[i])
			return -1;
	return 0;
}
 
int cd_name_cmp(const void *a, const void *b)
{
    struct cd *aa = (struct cd *) a;
    struct cd *bb = (struct cd *) b;
    return strcmp(bb->name, aa->name);
}
 
int cd_pop_cmp(const void *a, const void *b)
{
    struct cd *aa = (struct cd *) a;
    struct cd *bb = (struct cd *) b;
    return bb->population >= aa->population;
}
 
int main(void)
{
    const struct cd citydata[] = {
        { "Lagos", 21 },
        { "Cairo", 15.2 },
        { "Kinshasa-Brazzaville", 11.3 },
        { "Greater Johannesburg", 7.55 },
        { "Mogadishu", 5.85 },
        { "Khartoum-Omdurman", 4.98 },
        { "Dar Es Salaam", 4.7 },
        { "Alexandria", 4.58 },
        { "Abidjan", 4.4 },
        { "Casablanca", 3.98 }
    };
 
    const size_t citydata_length = LEN(citydata);
 
    printf("%d\n", search_get_index_by_name("Dar Es Salaam", citydata, citydata_length, cd_name_cmp));
    printf("%s\n", search_get_pop_threshold(5, citydata, citydata_length, cd_pop_cmp));
    printf("%lf\n", search_get_pop_by_name("A", citydata, citydata_length, cd_nameChar_cmp));
 
    return 0;
}

#include <iostream>
#include <gmpxx.h>
 
using namespace std;
 
struct Pair {
    mpz_class v1;
    mpz_class v2;
};
 
Pair make_pair(mpz_class a, mpz_class b) {
    Pair p;
    p.v1 = a;
    p.v2 = b;
    return p;
}
 
Pair solve_pell(unsigned long n) {
    mpz_class x;
    mpz_sqrt(x.get_mpz_t(), mpz_class(n).get_mpz_t());
    if (x * x == n) {
        return make_pair(1, 0);
    } else {
        mpz_class y = x;
        mpz_class z = 1;
        mpz_class r = (z + z) * x;
        Pair e = make_pair(1, 0);
        Pair f = make_pair(0, 1);
        mpz_class a = 0;
        mpz_class b = 0;
        while (a * a - n * b * b!= 1) {
            y = r * z - y;
            z = (n - y * y) / z;
            r = (x + y) / z;
 
            e = make_pair(e.v2, r * e.v2 + e.v1);
            f = make_pair(f.v2, r * f.v2 + f.v1);
            a = e.v2 + x * f.v2;
            b = f.v2;
        }
        return make_pair(a, b);
    }
}
 
int main() {
    test(61);
    test(109);
    test(181);
    test(277);
}
 
void test(unsigned long n) {
    Pair r = solve_pell(n);
    cout << "x^2 - " << n << " * y^2 = 1 for x = " << r.v1 << " and y = " << r.v2 << endl;
}

#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <sstream>
 
using namespace std;
 
vector<int> Compress(string uncompressed)
{
    // build the dictionary
    map<string, int> dictionary;
    for (int i = 0; i < 256; i++)
        dictionary[string(1, i)] = i;
 
    string w = "";
    vector<int> compressed;
 
    for (char c : uncompressed)
    {
        string wc = w + c;
        if (dictionary.find(wc)!= dictionary.end())
        {
            w = wc;
        }
        else
        {
            // write w to output
            compressed.push_back(dictionary[w]);
            // wc is a new sequence; add it to the dictionary
            dictionary[wc] = dictionary.size();
            w = string(1, c);
        }
    }
 
    // write remaining output if necessary
    if (!w.empty())
        compressed.push_back(dictionary[w]);
 
    return compressed;
}
 
string Decompress(vector<int> compressed)
{
    // build the dictionary
    map<int, string> dictionary;
    for (int i = 0; i < 256; i++)
        dictionary[i] = string(1, i);
 
    string w = dictionary[compressed[0]];
    compressed.erase(compressed.begin());
    stringstream decompressed;
    decompressed << w;
 
    for (int k : compressed)
    {
        string entry;
        if (dictionary.find(k)!= dictionary.end())
            entry = dictionary[k];
        else if (k == dictionary.size())
            entry = w + w[0];
 
        decompressed << entry;
 
        // new sequence; add it to the dictionary
        dictionary[dictionary.size()] = w + entry[0];
 
        w = entry;
    }
 
    return decompressed.str();
}
 
int main()
{
    vector<int> compressed = Compress("TOBEORNOTTOBEORTOBEORNOT");
    for (int i : compressed)
        cout << i << ", ";
    cout << endl;
    string decompressed = Decompress(compressed);
    cout << decompressed << endl;
}

