#include<iostream>
 
using namespace std;
 
class Vector{
	public:
		double x,y,z;
 
		Vector(double x,double y,double z){
			this->x = x;
			this->y = y;
			this->z = z;
		}
 
		Vector addVectors(Vector a,Vector b){
			return Vector(a.x+b.x,a.y+b.y,a.z+b.z);
		}
 
		Vector subVectors(Vector a,Vector b){
			return Vector(a.x-b.x,a.y-b.y,a.z-b.z);
		}
 
		double dotProduct(Vector a,Vector b){
			return a.x*b.x + a.y*b.y + a.z*b.z;
		}
 
		Vector scaleVector(double l,Vector a){
			return Vector(l*a.x,l*a.y,l*a.z);
		}
 
		Vector intersectionPoint(Vector lineVector, Vector linePoint, Vector planeNormal, Vector planePoint){
			Vector diff = subVectors(linePoint,planePoint);
 
			return addVectors(addVectors(diff,planePoint),scaleVector(-dotProduct(diff,planeNormal)/dotProduct(lineVector,planeNormal),lineVector));
		}
};
 
int main(int argC,char* argV[])
{
	Vector lV,lP,pN,pP,iP;
 
	if(argC!=5)
		cout<<"Usage : "<<argV[0]<<" <line direction, point on line, normal to plane and point on plane given as (x,y,z) tuples separated by space>";
	else{
		sscanf(argV[1],"(%lf,%lf,%lf)",&lV.x,&lV.y,&lV.z);
		sscanf(argV[3],"(%lf,%lf,%lf)",&pN.x,&pN.y,&pN.z);
 
		if(lV.dotProduct(lV,pN)==0)
			cout<<"Line and Plane do not intersect, either parallel or line is on the plane";
		else{
			sscanf(argV[2],"(%lf,%lf,%lf)",&lP.x,&lP.y,&lP.z);
			sscanf(argV[4],"(%lf,%lf,%lf)",&pP.x,&pP.y,&pP.z);
 
			iP = lV.intersectionPoint(lV,lP,pN,pP);
 
			cout<<"Intersection point is ("<<iP.x<<","<<iP.y<<","<<iP.z<<")";
		}
	}
 
	return 0;
}

#include <iostream>
#include <vector>
 
using namespace std;
 
int main() {
    vector<int> a = {170, 45, 75, -90, -802, 24, 2, 66};
    cout << "before: ";
    for (int i = 0; i < a.size(); i++) {
        cout << a[i] << " ";
    }
    cout << endl;
    int last = a.size() - 1;
    for (int i = 0; i < last; i++) {
        int aMin = a[i];
        int iMin = i;
        for (int j = i + 1; j < a.size(); j++) {
            if (a[j] < aMin) {
                aMin = a[j];
                iMin = j;
            }
        }
        int temp = a[i];
        a[i] = a[iMin];
        a[iMin] = temp;
    }
    cout << "after: ";
    for (int i = 0; i < a.size(); i++) {
        cout << a[i] << " ";
    }
    cout << endl;
}

#include <iostream>
#include <string>
 
class IOperable
{
public:
    virtual std::string Operate() = 0;
};
 
class Inoperable
{
};
 
class Operable : public IOperable
{
public:
    std::string Operate()
    {
        return "Delegate implementation.";
    }
};
 
class Delegator : public IOperable
{
private:
    IOperable* Delegate;
 
public:
    std::string Operate()
    {
        if (Delegate!= nullptr)
        {
            return Delegate->Operate();
        }
        else
        {
            return "Default implementation.";
        }
    }
 
    static void Main()
    {
        Delegator delegator;
        for (auto @delegate : { nullptr, new Inoperable(), new Operable() })
        {
            delegator.Delegate = @delegate;
            std::cout << delegator.Operate() << std::endl;
        }
    }
};
 
int main()
{
    Delegator::Main();
}

