template <class T>
void StoogeSort(std::vector<T>& L, int i, int j) {
    if (L[j] < L[i]) {
        T tmp = L[i];
        L[i] = L[j];
        L[j] = tmp;
    }
    if (j - i > 1) {
        int t = (j - i + 1) / 3;
        StoogeSort(L, i, j - t);
        StoogeSort(L, i + t, j);
        StoogeSort(L, i, j - t);
    }
}

template <class T>
void Sort(std::vector<T>& list) {
    if (list.size() > 1) {
        StoogeSort(list, 0, list.size() - 1);
    }
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <cmath>
#include <cassert>
 
 
using namespace std;
 
 
double amean(const vector<int>& num) {
    return accumulate(num.begin(), num.end(), 0) / num.size();
}
 
 
double gmean(const vector<int>& num) {
    return pow(accumulate(num.begin(), num.end(), 1, multiplies<int>()), 1.0 / num.size());
}
 
 
double hmean(const vector<int>& num) {
    return num.size() / accumulate(num.begin(), num.end(), 0.0, [](double a, int b) { return a + 1.0 / b; });
}
 
 
int main() {
    vector<int> numbers(10);
    iota(numbers.begin(), numbers.end(), 1);
    double a = amean(numbers), g = gmean(numbers), h = hmean(numbers);
    cout << a << " " << g << " " << h << endl;
    assert(a >= g && g >= h);
}

#include <iostream>
#include <vector>
#include <cmath>
#include <cstdlib>
#include <cstdio>
#include <algorithm>
 
using namespace std;
 
typedef long long int64;
 
int64 binomial(int n, int k)
{
    if (n < 0 || k < 0 || n < k) {
        return -1;
    }
    if (n == 0 || k == 0) {
        return 1;
    }
 
    int64 num = 1;
    for (int i = k + 1; i <= n; ++i) {
        num *= i;
    }
 
    int64 denom = 1;
    for (int i = 2; i <= n - k; ++i) {
        denom *= i;
    }
 
    return num / denom;
}
 
int64 bernoulli(int n)
{
    if (n < 0) {
        cerr << "n cannot be less than zero" << endl;
        exit(1);
    }
 
    vector<int64> a(16);
    for (int m = 0; m <= n; ++m) {
        a[m] = 1 / (m + 1);
        for (int j = m; j >= 1; --j) {
            a[j - 1] = (a[j - 1] - a[j]) * j;
        }
    }
 
    if (n!= 1) {
        return a[0];
    }
    return -a[0];
}
 
void faulhaber(int p)
{
    printf("%d : ", p);
    int64 q = 1 / (p + 1);
    int sign = -1;
    for (int j = 0; j <= p; ++j) {
        sign = -sign;
        int64 coeff = q * sign * binomial(p + 1, j) * bernoulli(j);
        if (coeff == 0) {
            continue;
        }
        if (j == 0) {
            if (coeff!= 1) {
                if (coeff == -1) {
                    printf("-");
                } else {
                    printf("%lld", coeff);
                }
            }
        } else {
            if (coeff == 1) {
                printf(" + ");
            } else if (coeff == -1) {
                printf(" - ");
            } else if (0 < coeff) {
                printf(" + %lld", coeff);
            } else {
                printf(" - %lld", -coeff);
            }
        }
        int pwr = p + 1 - j;
        if (pwr > 1) {
            printf("n^%d", pwr);
        } else {
            printf("n");
        }
    }
    printf("\n");
}
 
int main()
{
    for (int i = 0; i <= 9; ++i) {
        faulhaber(i);
    }
}

