#include <iostream>
#include <string>
#include <vector>
#include <sstream>

using namespace std;

string quibble(vector<string> words) {
  stringstream ss;
  ss << "{";
  for (int i = 0; i < words.size(); i++) {
    if (i > 0) {
      ss << ",";
    }
    ss << words[i];
  }
  if (words.size() > 1) {
    ss << " and ";
  }
  ss << words[words.size()-1];
  ss << "}";
  return ss.str();
}

int main() {
