  vector<string> s1;
  s1.push_back("ABC");
  vector<string> s2;
  s2.push_back("ABC");
  s2.push_back("DEF");
  vector<string> s3;
  s3.push_back("ABC");
  s3.push_back("DEF");
  s3.push_back("G");
  s3.push_back("H");
  cout << quibble(s0) << endl;
  cout << quibble(s1) << endl;
  cout << quibble(s2) << endl;
  cout << quibble(s3) << endl;
}

#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
 
using namespace std;
 
int main() {
    // read file into memory as one big block
    ifstream f("unixdict.txt");
    string data;
    f.seekg(0, ios::end);
    data.reserve(f.tellg());
    f.seekg(0, ios::beg);
    data.assign((istreambuf_iterator<char>(f)), istreambuf_iterator<char>());
    // copy the block, split it up into words
    vector<string> words;
    string::size_type start = 0;
    string::size_type end = 0;
    while (end!= string::npos) {
        end = data.find("\n", start);
        words.push_back(data.substr(start, end - start));
        start = end + 1;
    }
    // optional, free the first block for garbage collection
    data.clear();
    // put words in a map, also determine length of longest word
    map<string, bool> m;
    int longest = 0;
    for (auto w : words) {
        m[w] = true;
        if (w.size() > longest) {
            longest = w.size();
        }
    }
    // allocate a buffer for reversing words
    vector<char> r(longest);
    // iterate over word list
    int sem = 0;
    vector<string> five;
    for (auto w : words) {
        // first, delete from map.  this prevents a palindrome from matching
        // itself, and also prevents it's reversal from matching later.
        m.erase(w);
        // use buffer to reverse word
        int last = w.size() - 1;
        for (int i = 0; i < w.size(); i++) {
            r[i] = w[last - i];
        }
        string rs(r.begin(), r.begin() + w.size());
        // see if reversed word is in map, accumulate results
        if (m[rs]) {
            sem++;
            if (five.size() < 5) {
                five.push_back(w + "/" + rs);
            }
        }
    }
    // print results
    cout << sem << " pairs" << endl;
    cout << "examples:" << endl;
    for (auto e : five) {
        cout << "  " << e << endl;
    }
}

#include <iostream>
#include <iomanip>
#include <cmath>
#include <vector>
