using namespace std;
 
vector<string> generateFibonacci(int n) {
    vector<string> fib(n);
    fib[0] = "1";
    fib[1] = "1";
    for (int i = 2; i < fib.size(); i++) {
        fib[i] = to_string(stoll(fib[i - 2]) + stoll(fib[i - 1]));
    }
    return fib;
}
 
int main() {
    vector<string> numbers = generateFibonacci(1000);
 
    vector<int> firstDigits(10);
    for (string number : numbers) {
        firstDigits[stoi(number.substr(0, 1))]++;
    }
 
    for (int i = 1; i < firstDigits.size(); i++) {
        cout << i << " " << fixed << setprecision(6) << (double) firstDigits[i] / numbers.size() << " " << fixed << setprecision(6) << log10(1.0 + 1.0 / i) << endl;
    }
}

