#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

using namespace std;

bool luhn(long long n) {
	vector<int> r;
	while (n) {
		r.push_back(n % 10);
		n /= 10;
	}
	reverse(r.begin(), r.end());
	int sum = accumulate(r.begin(), r.end(), 0, [](int sum, int d) {
		return sum + (d % 2? d : (d < 5? d * 2 : d * 2 - 9));
	});
	return sum % 10 == 0;
}

int main() {
	for (long long n : {49927398716, 49927398717, 1234567812345678, 1234567812345670}) {
		cout << n << " " << luhn(n) << endl;
	}
}

// Version 1.3.21
 
#include <iostream>
#include <cmath>
 
using namespace std;
 
const int MAX = 120;
 
bool isPrime(int n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    if (n % 3 == 0) return n == 3;
    int d = 5;
    while (d * d <= n) {
        if (n % d == 0) return false;
        d += 2;
        if (n % d == 0) return false;
        d += 4;
    }
    return true;
}
 
int countPrimeFactors(int n) {
    if (n == 1) return 0;
    if (isPrime(n)) return 1;
    int nn = n;
    int count = 0;
    int f = 2;
    while (true) {
        if (nn % f == 0) {
            count++;
            nn /= f;
            if (nn == 1) break;
            if (isPrime(nn)) f = nn;
        } else if (f >= 3) {
            f += 2;
        } else {
            f = 3;
        }
    }
    return count;
}
 
int main() {
    cout << "The attractive numbers up to and including " << MAX << " are:" << endl;
    int count = 0;
    for (int i = 1; i <= MAX; i++) {
        int n = countPrimeFactors(i);
        if (isPrime(n)) {
            cout << " " << i;
            if (++count % 20 == 0) cout << endl;
        }
    }
    cout << endl;
}

