#include <QPaintEvent>
#include <QPainter>
 
class ColourPinstripeDisplay : public QFrame {
public:
    ColourPinstripeDisplay(QWidget *parent = nullptr) : QFrame(parent) {
        setFixedSize(900, 600);
    }
 
protected:
    void paintEvent(QPaintEvent *event) override {
        QPainter painter(this);
        const int bands = 4;
        const int h = height() / bands;
        for (int b = 1; b <= bands; b++) {
            int colIndex = 0;
            for (int x = 0; x < width(); x += b) {
                painter.fillRect(x, (b - 1) * h, b, h, colIndex % 2 == 0? Qt::white : Qt::black);
                colIndex++;
            }
        }
    }
};
 
int main(int argc, char *argv[]) {
    QApplication app(argc, argv);
    ColourPinstripeDisplay display;
    display.show();
    return app.exec();
}

