string commonpath(vector<string> paths) {
    if (paths.size() == 0) {
        return "";
    }
    string common = paths[0];
    for (int i = 1; i < paths.size(); i++) {
        int j = 0;
        while (j < common.size() && j < paths[i].size() && common[j] == paths[i][j]) {
            j++;
        }
        common = common.substr(0, j);
    }
    return common;
}

