#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
 
using namespace std;
 
void main() {
    int len = 4;
    playBullsAndCows(len);
}
 
void playBullsAndCows(int len) {
    vector<int> num = pickNum(len);
    // print('The secret number is:\n '+ num.join('\n  '));
    showInstructions(len);
    int nGuesses = 0;
    while (true) {
        nGuesses++;
        vector<int> guess = getGuess(nGuesses, len);
        Census census = countBovine(num, guess);
        showScore(census.bulls, census.cows);
        if (census.bulls == len) {
            showFinalResult(nGuesses);
            return;
        }
    }
}
 
void showScore(int nBulls, int nCows) {
    cout << "    Bulls: " << nBulls << ", cows: " << nCows << endl;
}
 
void showFinalResult(int guesses) {
    cout << "You win!!! Guesses needed: " << guesses << endl;
}
 
Census countBovine(vector<int> num, vector<int> guess) {
    Census count = {0, 0};
    string g = vectorToString(guess);
    for (int i = 0; i < num.size(); i++) {
        bool digPresent = g.find(num[i])!= string::npos;
        if (num[i] == guess[i]) count.bulls++;
        else if (digPresent) count.cows++;
    }
    return count;
}
 
vector<int> getGuess(int nGuesses, int len) {
    while (true) {
        cout << "Your guess #" << nGuesses << ": ";
        string guess;
        cin >> guess;
        vector<int> guessVector = stringToVector(guess);
        if (guessVector.size()!= len) {
            cout << "  You must enter a " << len << " digit number." << endl;
            continue;
        }
        if (hasDups(guessVector)) {
            cout << "  No digits can be duplicated." << endl;
            continue;
        }    
        return guessVector;
    }
}
 
bool hasDups(vector<int> ary) {
    vector<int> t = ary;
    sort(t.begin(), t.end());
    for (int i = 1; i < t.size(); i++) {
        if (t[i] == t[i-1]) return true;
    }
    return false;
}
 
void showInstructions(int len) {
    cout << endl;
    cout << "Bulls and Cows Game" << endl;
    cout << "-------------------" << endl;
    cout << "  You must guess the " << len << " digit number I am thinking of." << endl;
    cout << "  The number is composed of the digits 1-9." << endl;
    cout << "  No digit appears more than once." << endl;
    cout << "  After each of your guesses, I will tell you:" << endl;
    cout << "    The number of bulls (digits in right place)" << endl;
    cout << "    The number of cows (correct digits, but in the wrong place)" << endl;
    cout << endl;
}
 
vector<int> pickNum(int len) {
    vector<int> nums = {1, 2, 3, 4, 5, 6, 7, 8, 9};
    random_shuffle(nums.begin(), nums.end());
    return vector<int>(nums.begin(), nums.begin() + len);
}
 
string vectorToString(vector<int> v) {
    stringstream ss;
    for (int i = 0; i < v.size(); i++) {
        ss << v[i];
    }
    return ss.str();
}
 
vector<int> stringToVector(string s) {
    vector<int> v;
    for (int i = 0; i < s.size(); i++) {
        v.push_back(s[i] - '0');
    }
    return v;
}
 
struct Census {
    int bulls;
    int cows;
};
 
int main() {
    main();
    return 0;
}

task_description:
Implement some operations on variable-length quantities, at least including conversions from a normal number in the language to the binary representation of the variable-length quantity for that number, and vice versa. Any variants are acceptable.



Task

With above operations,

convert these two numbers 0x200000 (2097152 in decimal) and 0x1fffff (2097151 in decimal) into sequences of octets (an eight-bit byte); 
display these sequences of octets;
convert these sequences of octets back to numbers, and check that they are equal to original numbers.

code:
#include <iostream>
#include <vector>
#include <cassert>
 
const int RADIX = 7;
const int MASK = (1 << RADIX) - 1;
 
std::vector<int> octetify(int n) {
	if (n >= 2147483648) {
		throw std::range_error("Variable Length Quantity not supported for numbers >= 2147483648");
	}
	std::vector<int> octets;
	for (int i = n; i!= 0; i >>= RADIX) {
		octets.push_back(((i & MASK) + (octets.empty()? 0 : (MASK + 1))));
	}
	std::reverse(octets.begin(), octets.end());
	return octets;
}
 
int deoctetify(std::vector<int> octets) {
	int n = 0;
	for (int octet : octets) {
		n = (n << RADIX) + (octet & MASK);
	}
	return n;
}
 
int main() {
	std::vector<int> testNumbers = { 0x200000, 0x1fffff, 1, 127, 128, 2147483647 /*, 589723405834*/ };
	for (int number : testNumbers) {
		std::vector<int> octets = octetify(number);
		std::cout << octets << std::endl;
		int got_back_number = deoctetify(octets);
		assert(got_back_number == number);
	}
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
 
using namespace std;
 
const int numPlays = 100000;
 
vector<int> setupSecrets() {
 
	vector<int> secrets;
 
	for (int i = 0; i < 100; i++) {
		secrets.push_back(i);
	}
 
	random_shuffle(secrets.begin(), secrets.end());
 
	return secrets;
}
 
bool playOptimal() {
 
	vector<int> secrets = setupSecrets();
 
	for (int p = 0; p < 100; p++) {
 
		bool success = false;
 
		int choice = p;
 
		for (int i = 0; i < 50; i++) {
 
			if (secrets[choice] == p) {
				success = true;
				break;
			}
 
			choice = secrets[choice];
 
		}
 
		if (!success) return false;
 
	}
 
	return true;
}
 
bool playRandom() {
 
	vector<int> secrets = setupSecrets();
 
	for (int p = 0; p < 100; p++) {
 
		vector<int> choices = setupSecrets();
 
		bool success = false;
 
		for (int i = 0; i < 50; i++) {
 
			if (choices[i] == p) {
				success = true;
				break;
			}
		}
 
		if (!success) return false;
	}
 
	return true;
}
 
double execOptimal() {
 
	int success = 0;
 
	for (int i = 0; i < numPlays; i++) {
 
		if (playOptimal()) success++;
 
	}
 
	return 100.0 * success / 100000;
}
 
double execRandom() {
 
	int success = 0;
 
	for (int i = 0; i < numPlays; i++) {
 
		if (playRandom()) success++;
 
	}
 
	return 100.0 * success / 100000;
}
 
int main() {
 
	cout << "# of executions: " << numPlays << endl;
	cout << "Optimal Play Success Rate: " << execOptimal() << endl;
	cout << "Random Play Success Rate: " << execRandom() << endl;
 
	return 0;
}

#include <iostream>
#include <vector>
 
using namespace std;
 
typedef vector<vector<float>> matrix;
 
void print(matrix m) {
    for (auto r : m) {
        for (auto e : r) {
            cout << e << " ";
        }
        cout << endl;
    }
    cout << endl;
}
 
void rref(matrix &m) {
    int lead = 0;
    int rowCount = m.size();
    int columnCount = m[0].size();
    for (int r = 0; r < rowCount; r++) {
        if (lead >= columnCount) {
            return;
        }
        int i = r;
        while (m[i][lead] == 0) {
            i++;
            if (rowCount == i) {
                i = r;
                lead++;
                if (columnCount == lead) {
                    return;
                }
            }
        }
        swap(m[i], m[r]);
        float f = 1 / m[r][lead];
        for (int j = 0; j < columnCount; j++) {
            m[r][j] *= f;
        }
        for (int i = 0; i < rowCount; i++) {
            if (i!= r) {
                f = m[i][lead];
                for (int j = 0; j < columnCount; j++) {
                    m[i][j] -= m[r][j] * f;
                }
            }
        }
        lead++;
    }
}
 
int main() {
    matrix m = {
        { 1, 2, -1,  -4},
        { 2, 3, -1, -11},
        {-2, 0, -3,  22},
    };
    print(m);
    rref(m);
    print(m);
}

