using namespace std;
 
double MonteCarloPi(int n) {
    int inside = 0;
    random_device rd;
    mt19937 gen(rd());
    uniform_real_distribution<> dis(0, 1);
 
    for (int i = 0; i < n; i++) {
        if (pow(dis(gen), 2) + pow(dis(gen), 2) <= 1) {
            inside++;
        }
    }
 
    return 4.0 * inside / n;
}
 
int main() {
    int value = 1000;
    for (int n = 0; n < 5; n++) {
        value *= 10;
        stringstream ss;
        ss << value;
        string s = ss.str();
        cout << setw(11) << left << s << MonteCarloPi(value) << endl;
    }
}

#include <iostream>
