using namespace std;
 
template <typename T>
class Powers {
public:
    Powers(int m) : m(m), n(0) {}
    T operator()() { return n++ * m; }
private:
    int m, n;
};
 
template <typename T>
class Filtered {
public:
    Filtered(T s1, T s2) : s1(s1), s2(s2), v(s1()), f(s2()) {}
    T operator()() {
        while (v > f) {
            f = s2();
        }
        if (v < f) {
            T tmp = v;
            v = s1();
            return tmp;
        }
        v = s1();
        return f;
    }
private:
    T s1, s2;
    T v, f;
};
 
int main() {
    Powers<int> squares(2), cubes(3);
    Filtered<int> f(squares, cubes);
    vector<int> v;
    for (int i = 0; i < 10; i++) {
        v.push_back(f());
    }
    copy(v.begin(), v.end(), ostream_iterator<int>(cout, " "));
    cout << endl;
}

#include <iostream>
#include <map>
#include <string>
 
using namespace std;
 
bool isHumble(int i) {
    if (i <= 1) return true;
    if (i % 2 == 0) return isHumble(i / 2);
    if (i % 3 == 0) return isHumble(i / 3);
    if (i % 5 == 0) return isHumble(i / 5);
    if (i % 7 == 0) return isHumble(i / 7);
    return false;
}
 
int main() {
    int limit = 32767;
    map<int, int> humble;
    int count = 0;
    int num = 1;
 
    while (count < limit) {
        if (isHumble(num)) {
            string str = to_string(num);
            int len = str.length();
            humble[len] += 1;
 
            if (count < 50) cout << num << " ";
            count++;
        }
        num++;
    }
    cout << endl;
 
    cout << "Of the first " << count << " humble numbers:" << endl;
    num = 1;
    while (num < humble.size() - 1) {
        if (humble.count(num)) {
            int c = humble[num];
            cout << " " << c << " have " << num << " digits" << endl;
            num++;
        } else {
            break;
        }
    }
}

