using namespace std;
 
int main()
{
    while (true) {
        string bexp;
        cout << "\nBoolean expression: ";
        getline(cin, bexp);
        if (bexp.empty()) {
            cout << "\nThank you" << endl;
            break;
        }
        vector<string> names;
        size_t pos = 0;
        while (true) {
            pos = bexp.find(' ', pos);
            if (pos == string::npos)
                break;
            names.push_back(bexp.substr(0, pos));
            bexp.erase(0, pos + 1);
        }
        names.push_back(bexp);
        cout << "\n" << names[0];
        for (size_t i = 1; i < names.size(); ++i)
            cout <<'' << names[i];
        cout << " : " << bexp << endl;
        for (size_t i = 0; i < (1 << names.size()); ++i) {
            vector<int> values;
            for (size_t j = 0; j < names.size(); ++j)
                values.push_back(i & (1 << j)? 1 : 0);
            cout << values[0];
            for (size_t j = 1; j < names.size(); ++j)
                cout <<'' << values[j];
            cout << " : ";
            for (size_t j = 0; j < names.size(); ++j)
                cout << names[j] << '=' << values[j] <<'';
            cout << "= " << (i & 1? "True" : "False") << endl;
        }
    }
}

