#include <algorithm>
#include <cctype>
#include <fstream>
#include <iostream>
#include <iterator>
#include <set>
#include <string>
#include <vector>
 
// ------------------- WORD WHEEL --------------------
 
// gridWords :: [String] -> [String] -> [String]
auto gridWords(const std::vector<std::string>& grid) {
    return [grid](const std::vector<std::string>& lexemes) {
        std::string wheel = grid[0] + grid[1] + grid[2];
        std::sort(wheel.begin(), wheel.end());
        std::set<char> wSet(wheel.begin(), wheel.end());
        char mid = wheel[4];
 
        std::vector<std::string> result;
        for (const auto& w : lexemes) {
            if (w.size() < 3) {
                continue;
            }
            std::string cs = w;
            std::sort(cs.begin(), cs.end());
            if (std::all_of(cs.begin(), cs.end(), [&wSet](char c) {
                    return wSet.find(c)!= wSet.end();
                }) &&
                std::any_of(cs.begin(), cs.end(), [&mid](char c) {
                    return mid == c;
                }) &&
                wheelFit(wheel, cs)) {
                result.push_back(w);
            }
        }
        return result;
    };
}
 
// wheelFit :: [Char] -> [Char] -> Bool
bool wheelFit(const std::string& wheel, const std::string& word) {
    auto go = [&wheel](const std::string& ws, const std::string& cs) {
        if (cs.empty()) {
            return true;
        }
        if (ws.empty()) {
            return false;
        }
        if (ws[0] == cs[0]) {
            return go(ws.substr(1), cs.substr(1));
        }
        return go(ws.substr(1), cs);
    };
 
    return go(wheel, word);
}
 
// ---------------------- TEST -----------------------
// main :: IO ()
int main() {
    std::ifstream file("unixdict.txt");
    std::vector<std::string> lexemes(
        std::istream_iterator<std::string>(file),
        std::istream_iterator<std::string>());
    std::vector<std::string> grid = {"NDE", "OKG", "ELW"};
    for (const auto& w : gridWords(grid)(lexemes)) {
        std::cout << w << std::endl;
    }
}

