#include <iostream>
#include <vector>
#include <string>
#include <iomanip>
 
using namespace std;
 
const int WIDTH = 6;
 
class SqMat {
public:
    vector<vector<int>> data;
 
    SqMat(vector<vector<int>> data) {
        this->data = data;
    }
 
    SqMat operator^(unsigned int n) {
        vector<vector<int>> aux = this->data;
        SqMat ans(vector<vector<int>>(aux.size(), vector<int>(aux.size(), 0)));
        for (int i = 0; i < aux.size(); i++) {
            ans.data[i][i] = 1;
        }
        unsigned int b = n;
        while (b > 0) {
            if (b & 1 > 0) {
                // ans = ans * aux
                vector<vector<int>> tmp(aux.size(), vector<int>(aux.size(), 0));
                for (int i = 0; i < aux.size(); i++) {
                    for (int j = 0; j < aux.size(); j++) {
                        for (int k = 0; k < aux.size(); k++) {
                            tmp[i][j] += ans.data[i][k] * aux[k][j];
                        }
                    }
                }
                ans.data = tmp;
            }
            b >>= 1;
            if (b > 0) {
                // aux = aux * aux
                vector<vector<int>> tmp(aux.size(), vector<int>(aux.size(), 0));
                for (int i = 0; i < aux.size(); i++) {
                    for (int j = 0; j < aux.size(); j++) {
                        for (int k = 0; k < aux.size(); k++) {
                            tmp[i][j] += aux[i][k] * aux[k][j];
                        }
                    }
                }
                aux = tmp;
            }
        }
        return ans;
    }
 
    friend ostream& operator<<(ostream& os, const SqMat& sm) {
        string row = "";
        for (int i = 0; i < sm.data.size(); i++) {
            for (int j = 0; j < sm.data.size(); j++) {
                row += to_string(sm.data[i][j]) + string(WIDTH - to_string(sm.data[i][j]).length(),'');
            }
            row += "\n";
        }
        os << row;
        return os;
    }
};
 
int main() {
    SqMat sm(vector<vector<int>>{{1, 2, 0}, {0, 3, 1}, {1, 0, 0}});
    for (int i = 0; i < 11; i++) {
        cout << "Power of " << i << ":\n" << sm ^ i << endl;
    }
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>
#include <ctime>
 
using namespace std;
 
void game_of_life(string name, int size, int generations, vector<vector<int> > initial_life=vector<vector<int> >())
{
  vector<vector<int> > board = new_board(size);
  seed(board, size, initial_life);
  print_board(board, name, 0);
  int reason = 0;
  for (int gen = 0; gen < generations; gen++)
  {
    vector<vector<int> > new_board = evolve(board, size);
    print_board(new_board, name, gen+1);
    if (barren(new_board, size))
    {
      reason = 1;
      break;
    }
    if (board == new_board)
    {
      reason = 2;
      break;
    }
    board = new_board;
  }
  if (reason == 1)
    cout << "no more life." << endl;
  else if (reason == 2)
    cout << "no movement" << endl;
  else
    cout << "specified lifetime ended" << endl;
  cout << endl;
}
 
vector<vector<int> > new_board(int n)
{
  vector<vector<int> > board(n, vector<int>(n, 0));
  return board;
}
 
void seed(vector<vector<int> > &board, int n, vector<vector<int> > points=vector<vector<int> >())
{
  if (points.empty())
  {
    // randomly seed board
    vector<vector<int> > indices;
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++)
        indices.push_back(vector<int>(2));
    random_shuffle(indices.begin(), indices.end());
    for (int i = 0; i < 10; i++)
      board[indices[i][1]][indices[i][0]] = 1;
  }
  else
  {
    for (int i = 0; i < points.size(); i++)
      board[points[i][1]][points[i][0]] = 1;
  }
}
 
vector<vector<int> > evolve(vector<vector<int> > board, int n)
{
  vector<vector<int> > new_board = new_board(n);
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      new_board[i][j] = fate(board, i, j, n);
  return new_board;
}
 
int fate(vector<vector<int> > board, int i, int j, int n)
{
  int i1 = max(0, i-1);
  int i2 = min(i+1, n-1);
  int j1 = max(0, j-1);
  int j2 = min(j+1, n-1);
  int sum = 0;
  for (int ii = i1; ii <= i2; ii++)
    for (int jj = j1; jj <= j2; jj++)
      if (not (ii == i and jj == j))
        sum += board[ii][jj];
  return (sum == 3 or (sum == 2 and board[i][j] == 1)) ? 1 : 0;
}
 
bool barren(vector<vector<int> > board, int n)
{
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      if (board[i][j] == 1)
        return false;
  return true;
}
 
void print_board(vector<vector<int> > board, string name, int generation)
{
  cout << name << ": generation " << generation << endl;
  for (int i = 0; i < board.size(); i++)
  {
    for (int j = 0; j < board[i].size(); j++)
      cout << (board[i][j] == 1 ? '#' : '.') << " ";
    cout << endl;
  }
}
 
int main()
{
  srand(time(NULL));
  game_of_life("blinker", 3, 2, vector<vector<int> >(3, vector<int>(2)));
  game_of_life("glider", 4, 4, vector<vector<int> >(5, vector<int>(2)));
  game_of_life("random", 5, 10);
}

#include <iostream>
