#include <map>
#include <algorithm>
using namespace std;

vector<int> countingSort(vector<int> array, int mn, int mx) {
	map<int, int> count;
	for (int i = 0; i < array.size(); i++) {
		count[array[i]]++;
	}
	vector<int> result;
	for (int j = mn; j <= mx; j++) {
		for (int k = 0; k < count[j]; k++) {
			result.push_back(j);
		}
	}
	return result;
}

