using namespace std;
 
int totient(int n) {
    int tot = n;
    int nn = n;
    int i = 2;
    while (i * i <= nn) {
        if (nn % i == 0) {
            while (nn % i == 0) nn /= i;
            tot -= tot / i;
        }
        if (i == 2) i = 1;
        i += 2;
    }
    if (nn > 1) tot -= tot / nn;
    return tot;
}
 
int main() {
    vector<int> perfect;
    int n = 1;
    while (perfect.size() < 20) {
        int tot = n;
        int sum = 0;
        while (tot!= 1) {
            tot = totient(tot);
            sum += tot;
        }
        if (sum == n) perfect.push_back(n);
        n += 2;
    }
    cout << "The first 20 perfect totient numbers are:" << endl;
    for (int i = 0; i < perfect.size(); i++) {
        cout << perfect[i] << " ";
    }
    cout << endl;
}

