bool validISBN13(string str)
{
    string cleaned = str;
    cleaned.erase(remove_if(cleaned.begin(), cleaned.end(), [](char c) { return!isdigit(c); }), cleaned.end());
    if (cleaned.size()!= 13) return false;
    vector<int> digits;
    for (int i = 0; i < cleaned.size(); i += 2)
    {
        digits.push_back(cleaned[i] - '0');
        digits.push_back(3 * (cleaned[i + 1] - '0'));
    }
    return accumulate(digits.begin(), digits.end(), 0) % 10 == 0;
}
 
