#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
 
using namespace std;
 
int levenshtein_distance(const string& a, const string& b)
{
    int a_len = a.size();
    int b_len = b.size();
    vector<int> costs(b_len + 1);
    for (int j = 0; j < costs.size(); j++)
        costs[j] = j;
    for (int i = 1; i <= a_len; i++)
    {
        costs[0] = i;
        int nw = i - 1;
        for (int j = 1; j <= b_len; j++)
        {
            int cost = a[i - 1] == b[j - 1]? 0 : 1;
            int del = costs[j] + 1;
            int ins = costs[j - 1] + 1;
            int sub = nw + cost;
            nw = costs[j];
            costs[j] = min(del, min(ins, sub));
        }
    }
    return costs[b_len];
}
 
int main()
{
    string a[] = { "kitten", "sitting", "saturday", "sunday", "rosettacode", "raisethysword" };
    for (int i = 0; i < 6; i += 2)
        cout << "distance(" << a[i] << ", " << a[i + 1] << ") = " << levenshtein_distance(a[i], a[i + 1]) << endl;
}

