#include <cmath>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
 
const double SQRT3_2 = 0.86602540378444;
 
struct Cursor {
    double x;
    double y;
    int angle;
};
 
void turn(Cursor& cursor, int angle) {
    cursor.angle = (cursor.angle + angle) % 360;
}
 
void draw_line(Cursor& cursor, std::vector<std::string>& data, double length) {
    double theta = cursor.angle * M_PI / 180.0;
    cursor.x += length * std::cos(theta);
    cursor.y += length * std::sin(theta);
    data.push_back("L " + std::to_string(cursor.x) + " " + std::to_string(cursor.y));
}
 
void curve(std::vector<std::string>& data, int order, double length, Cursor& cursor, int angle) {
    if (order == 0) {
        draw_line(cursor, data, length);
        return;
    }
    curve(data, order - 1, length / 2.0, cursor, -angle);
    turn(cursor, angle);
    curve(data, order - 1, length / 2.0, cursor, angle);
    turn(cursor, angle);
    curve(data, order - 1, length / 2.0, cursor, -angle);
}
 
void write_sierpinski_arrowhead(const std::string& file, int size, int order) {
    std::ofstream out(file);
    if (!out) {
        std::cerr << "Error opening file " << file << std::endl;
        return;
    }
    double margin = 20.0;
    double side = size - 2.0 * margin;
    double y = 0.5 * size + 0.5 * SQRT3_2 * side;
    double x = margin;
    Cursor cursor = {x, y, 0};
    if (order & 1) {
        turn(cursor, -60);
    }
    std::vector<std::string> data;
    data.push_back("M " + std::to_string(x) + " " + std::to_string(y));
    curve(data, order, side, cursor, 60);
    out << "<svg width=\"" << size << "\" height=\"" << size << "\" xmlns=\"http://www.w3.org/2000/svg\">\n";
    out << "<rect width=\"100%\" height=\"100%\" fill=\"white\"/>\n";
    out << "<path fill=\"none\" stroke=\"black\" stroke-width=\"1\" d=\"";
    for (const auto& s : data) {
        out << s;
    }
    out << "\"/>\n";
    out << "</svg>\n";
}
 
int main() {
    write_sierpinski_arrowhead("sierpinski_arrowhead.svg", 600, 8);
}

