#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <cstdio>
#include <cassert>
 
using namespace std;
 
vector<uint32_t> primes;
bool foundCombo = false;
 
vector<uint32_t> sieve(uint32_t limit) {
    vector<uint32_t> primes = {2};
    vector<bool> c(limit + 1); // composite = true
    // no need to process even numbers > 2
    uint32_t p = 3;
    while (true) {
        uint32_t p2 = p * p;
        if (p2 > limit) {
            break;
        }
        for (uint32_t i = p2; i <= limit; i += 2 * p) {
            c[i] = true;
        }
        while (true) {
            p += 2;
            if (!c[p]) {
                break;
            }
        }
    }
    for (uint32_t i = 3; i <= limit; i += 2) {
        if (!c[i]) {
            primes.push_back(i);
        }
    }
    return primes;
}
 
void findCombo(uint32_t k, uint32_t x, uint32_t m, uint32_t n, vector<uint32_t> &combo) {
    if (k >= m) {
        uint32_t sum = 0;
        for (uint32_t c : combo) {
            sum += primes[c];
        }
        if (sum == x) {
            string s = "s";
            if (m == 1) {
                s = " ";
            }
            printf("Partitioned %5d with %2d prime%s: ", x, m, s.c_str());
            for (uint32_t i = 0; i < m; i++) {
                printf("%d", primes[combo[i]]);
                if (i < m - 1) {
                    printf("+");
                } else {
                    printf("\n");
                }
            }
            foundCombo = true;
        }
    } else {
        for (uint32_t j = 0; j < n; j++) {
            if (k == 0 || j > combo[k - 1]) {
                combo[k] = j;
                if (!foundCombo) {
                    findCombo(k + 1, x, m, n, combo);
                }
            }
        }
    }
}
 
void partition(uint32_t x, uint32_t m) {
    if (!(x >= 2 && m >= 1 && m < x)) {
        printf("x must be at least 2 and m in [1, x)\n");
        return;
    }
    uint32_t n = 0;
    for (uint32_t prime : primes) {
        if (prime <= x) {
            n++;
        }
    }
    if (n < m) {
        printf("not enough primes\n");
        return;
    }
    vector<uint32_t> combo(m);
    foundCombo = false;
    findCombo(0, x, m, n, combo);
    if (!foundCombo) {
        string s = "s";
        if (m == 1) {
            s = " ";
        }
        printf("Partitioned %5d with %2d prime%s: (impossible)\n", x, m, s.c_str());
    }
}
 
int main() {
    vector<pair<uint32_t, uint32_t>> a = {
        {99809, 1}, {18, 2}, {19, 3}, {20, 4}, {2017, 24},
        {22699, 1}, {22699, 2}, {22699, 3}, {22699, 4}, {40355, 3},
    };
    primes = sieve(100000);
    for (auto p : a) {
        partition(p.first, p.second);
    }
}

