using namespace std;

class RepString {
public:
    static const string input[];
    static string repString(string s);
};

const string RepString::input[] = {"1001110011", "1110111011", "0010010010",
        "1010101010", "1111111111", "0100101101", "0100100", "101", "11",
        "00", "1", "0100101"};

string RepString::repString(string s) {
    int len = s.length();
    outer:
    for (int part = len / 2; part > 0; part--) {
        int tail = len % part;
        if (tail > 0 &&!s.substr(0, tail).compare(s.substr(len - tail)))
            continue;
        for (int j = 0; j < len / part - 1; j++) {
            int a = j * part;
            int b = (j + 1) * part;
            int c = (j + 2) * part;
            if (!s.substr(a, b).compare(s.substr(b, c)))
                continue outer;
        }
        return s.substr(0, part);
    }
    return "none";
}

int main() {
    for (int i = 0; i < 12; i++)
        cout << RepString::input[i] << " : " << RepString::repString(RepString::input[i]) << endl;
    return 0;
}

