#include <iostream>
 
#define TRUE 1
#define FALSE 0
 
int a,b,c,d,e,f,g;
int lo,hi,unique,show;
int solutions;
 
void
bf()
{
    for (f = lo;f <= hi; f++)
        if ((!unique) ||
           ((f!= a) && (f!= c) && (f!= d) && (f!= g) && (f!= e)))
            {
            b = e + f - c;
            if ((b >= lo) && (b <= hi) &&
                   ((!unique) || ((b!= a) && (b!= c) &&
                   (b!= d) && (b!= g) && (b!= e) && (b!= f))))
                {
                solutions++;
                if (show)
                    std::cout << a << " " << b << " " << c << " " << d << " " << e << " " << f << " " << g << std::endl;
                }
            }
}
 
 
void
ge()
{
    for (e = lo;e <= hi; e++)
        if ((!unique) || ((e!= a) && (e!= c) && (e!= d)))
            {
            g = d + e;
            if ((g >= lo) && (g <= hi) &&
                   ((!unique) || ((g!= a) && (g!= c) &&
                   (g!= d) && (g!= e))))
                bf();
            }
}
 
void
acd()
{
    for (c = lo;c <= hi; c++)
        for (d = lo;d <= hi; d++)
            if ((!unique) || (c!= d))
                {
                a = c + d;
                if ((a >= lo) && (a <= hi) &&
                   ((!unique) || ((c!= 0) && (d!= 0))))
                    ge();
                }
}
 
 
void
foursquares(int plo,int phi, int punique,int pshow)
{
    lo = plo;
    hi = phi;
    unique = punique;
    show = pshow;
    solutions = 0;
 
    std::cout << std::endl;
 
    acd();
 
    if (unique)
        std::cout << std::endl << solutions << " unique solutions in " << lo << " to " << hi << std::endl;
    else
        std::cout << std::endl << solutions << " non-unique solutions in " << lo << " to " << hi << std::endl;
}
 
int main()
{
    foursquares(1,7,TRUE,TRUE);
    foursquares(3,9,TRUE,TRUE);
    foursquares(0,9,FALSE,FALSE);
}

#include <cmath>
#include <functional>
#include <iostream>
#include <vector>
 
using namespace std;
 
void runge(function<double(double, double)> yp_func, vector<double> &t,
        vector<double> &y, double dt) {
 
    for (int n = 0; n < t.size() - 1; n++) {
        double dy1 = dt * yp_func(t[n], y[n]);
        double dy2 = dt * yp_func(t[n] + dt / 2.0, y[n] + dy1 / 2.0);
        double dy3 = dt * yp_func(t[n] + dt / 2.0, y[n] + dy2 / 2.0);
        double dy4 = dt * yp_func(t[n] + dt, y[n] + dy3);
        t[n + 1] = t[n] + dt;
        y[n + 1] = y[n] + (dy1 + 2.0 * (dy2 + dy3) + dy4) / 6.0;
    }
}
 
double calc_err(double t, double calc) {
    double actual = pow(pow(t, 2.0) + 4.0, 2) / 16.0;
    return abs(actual - calc);
}
 
int main() {
    double dt = 0.10;
    vector<double> t_arr(101);
    vector<double> y_arr(101);
    y_arr[0] = 1.0;
 
    runge([](double t, double y) { return t * sqrt(y); }, t_arr, y_arr, dt);
 
    for (int i = 0; i < t_arr.size(); i++)
        if (i % 10 == 0)
