#include <iostream>
#include <cmath>
 
using namespace std;
 
bool inCarpet(int x, int y) {
    int xx = x;
    int yy = y;
    while (xx!= 0 && yy!= 0) {
        if (xx % 3 == 1 && yy % 3 == 1) return false;
        xx /= 3;
        yy /= 3;
    }
    return true;
}
 
void carpet(int n) {
    int power = pow(3, n);
    for(int i = 0; i < power; i++) {
        for(int j = 0; j < power; j++) cout << (inCarpet(i, j)? "*" : " ");
        cout << endl;
    }
}
 
int main() {
    carpet(3);
    return 0;
}

