#include <iostream>
#include <string>
#include <vector>
#include <map>
 
using namespace std;
 
vector<string> tests = {
    "3 4 2 * 1 5 - 2 3 ^ ^ / +",
    "1 2 + 3 4 + ^ 5 6 + ^",
};
 
map<string, struct {
    int prec;
    bool rAssoc;
}> opa = {
    {"^", {4, true}},
    {"*", {3, false}},
    {"/", {3, false}},
    {"+", {2, false}},
    {"-", {2, false}},
};
 
const int nPrec = 9;
 
int main() {
    for (auto t : tests) {
        parseRPN(t);
    }
}
 
void parseRPN(string e) {
    cout << "\npostfix: " << e << endl;
    struct sf {
        int prec;
        string expr;
    };
    vector<sf> stack;
    for (auto tok : e) {
        cout << "token: " << tok << endl;
        if (opa.count(tok)) {
            auto op = opa[tok];
            auto rhs = &stack[stack.size() - 1];
            stack.pop_back();
            auto lhs = &stack[stack.size() - 1];
            if (lhs->prec < op.prec || (lhs->prec == op.prec && op.rAssoc)) {
                lhs->expr = "(" + lhs->expr + ")";
            }
            lhs->expr += " " + tok + " ";
            if (rhs->prec < op.prec || (rhs->prec == op.prec &&!op.rAssoc)) {
                lhs->expr += "(" + rhs->expr + ")";
            } else {
                lhs->expr += rhs->expr;
            }
            lhs->prec = op.prec;
        } else {
            stack.push_back({nPrec, tok});
        }
        for (auto f : stack) {
            cout << "    " << f.prec << " " << f.expr << endl;
        }
    }
    cout << "infix: " << stack[0].expr << endl;
}

#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <cassert>
 
using namespace std;
 
class BinaryHeap {
public:
    BinaryHeap(bool (*cmp)(int, int)) {
        this->cmp = cmp;
    }
 
    void push(int val) {
        this->data.push_back(val);
        this->bubble_up(this->data.size() - 1);
    }
 
    int pop() {
        int val = this->data[0];
        this->data[0] = this->data[this->data.size() - 1];
        this->data.pop_back();
        this->bubble_down(0);
        return val;
    }
 
    int size() {
        return this->data.size();
    }
 
private:
    vector<int> data;
    bool (*cmp)(int, int);
 
    void bubble_up(int pos) {
        if (pos == 0) return;
        int parent = (pos - 1) / 2;
        if (this->cmp(this->data[pos], this->data[parent])) {
            swap(this->data[pos], this->data[parent]);
            this->bubble_up(parent);
        }
    }
 
    void bubble_down(int pos) {
        int left = 2 * pos + 1;
        int right = 2 * pos + 2;
        if (left >= this->data.size()) return;
        if (right >= this->data.size()) {
            if (this->cmp(this->data[left], this->data[pos])) {
                swap(this->data[left], this->data[pos]);
            }
            return;
        }
        if (this->cmp(this->data[left], this->data[right])) {
            if (this->cmp(this->data[left], this->data[pos])) {
                swap(this->data[left], this->data[pos]);
                this->bubble_down(left);
            }
        }
        else {
            if (this->cmp(this->data[right], this->data[pos])) {
                swap(this->data[right], this->data[pos]);
                this->bubble_down(right);
            }
        }
    }
};
 
class HuffmanEncoding {
public:
    HuffmanEncoding(string str) {
        this->str = str;
 
        map<char, int> count_chars;
        for (int i = 0; i < str.length(); i++) {
            if (count_chars.find(str[i])!= count_chars.end()) {
                count_chars[str[i]]++;
            }
            else {
                count_chars[str[i]] = 1;
            }
        }
 
        BinaryHeap pq(cmp);
        for (map<char, int>::iterator it = count_chars.begin(); it!= count_chars.end(); it++) {
            pq.push(make_pair(it->second, it->first));
        }
 
        while (pq.size() > 1) {
            pair<int, char> pair1 = pq.pop();
            pair<int, char> pair2 = pq.pop();
            pq.push(make_pair(pair1.first + pair2.first, make_pair(pair1.second, pair2.second)));
        }
 
        pair<int, char> tree = pq.pop();
        this->generate_encoding(tree.second, "");
 
        this->encoded_string = "";
        for (int i = 0; i < this->str.length(); i++) {
            this->encoded_string += this->encoding[str[i]];
        }
    }
 
    void inspect_encoding() {
        for (map<char, string>::iterator it = this->encoding.begin(); it!= this->encoding.end(); it++) {
            cout << "'" << it->first << "': " << it->second << endl;
        }
    }
 
    string decode(string encoded) {
        map<string, char> rev_enc;
        for (map<char, string>::iterator it = this->encoding.begin(); it!= this->encoding.end(); it++) {
            rev_enc[it->second] = it->first;
        }
 
        string decoded = "";
        int pos = 0;
        while (pos < encoded.length()) {
            string key = "";
            while (rev_enc.find(key) == rev_enc.end()) {
                key += encoded[pos];
                pos++;
            }
            decoded += rev_enc[key];
        }
        return decoded;
    }
 
private:
    string str;
    map<char, string> encoding;
    string encoded_string;
 
    static bool cmp(pair<int, char> a, pair<int, char> b) {
        return a.first < b.first;
    }
 
    void generate_encoding(char ary, string prefix) {
        if (ary instanceof Array) {
            this->generate_encoding(ary[0], prefix + "0");
            this->generate_encoding(ary[1], prefix + "1");
        }
        else {
            this->encoding[ary] = prefix;
        }
    }
};
 
int main() {
    HuffmanEncoding h("hello world");
    h.inspect_encoding();
    assert(h.decode(h.encoded_string) == "hello world");
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
 
using namespace std;
 
typedef unsigned long long ull;
 
ull factorial(ull n) {
    if (n == 0) return 1;
    if (n == 1) return 1;
    ull prod = 1;
    for (ull i = 2; i <= n; i++) {
        prod *= i;
    }
    return prod;
}
 
ull lah(ull n, ull k) {
    if (k == 1) return factorial(n);
    if (k == n) return 1;
    if (k > n) return 0;
    if (k < 1 || n < 1) return 0;
    return (factorial(n) * factorial(n - 1)) / (factorial(k) * factorial(k - 1)) / factorial(n - k);
}
 
int main() {
    cout << "Unsigned Lah numbers: L(n, k):\n";
    cout << "n/k ";
    for (int i = 0; i <= 12; i++) {
        cout << " " << i;
    }
    cout << "\n";
    for (int row = 0; row <= 12; row++) {
        cout << row << "  ";
        for (int i = 0; i <= row; i++) {
            ull l = lah(row, i);
            cout << " " << l;
        }
        cout << "\n";
    }
    cout << "\nMaximum value from the L(100, *) row:\n";
    vector<ull> v;
    for (int i = 0; i <= 100; i++) {
        v.push_back(lah(100, i));
    }
    cout << *max_element(v.begin(), v.end()) << "\n";
}

