// choseLineRandomly implements the method described in the task.
// input is a an io.Reader, which could be an os.File, for example.
// Or, to implement a simulation, it could be anything else that implements
// io.Reader.  The method as described suggests saving and returning
// lines, but the rest of the task requires line numbers.  This function
// thus returns both.
std::pair<std::string, int> choseLineRandomly(std::istream& is) {
    std::string s;
    std::getline(is, s);
    if (is.eof()) {
        return std::make_pair(s, 0);
    }
    int ln = 1;
    double lnLast = 1.;
    std::string sLast;
    while (std::getline(is, sLast)) {
        lnLast++;
        if (rand() < RAND_MAX / lnLast) {
            s = sLast;
            ln = lnLast;
        }
    }
    return std::make_pair(s, ln);
}
 
// oneOfN function required for task item 1.  Specified to take a number
// n, the number of lines in a file, but the method (above) specified to
// to be used does not need n, but rather the file itself.  This function
// thus takes both, ignoring n and passing the file to choseLineRandomly.
int oneOfN(int n, std::istream& is) {
    return choseLineRandomly(is).second;
}
 
// simulated file reader for task item 2
class simReader {
    int n;
public:
    simReader(int n) : n(n) {}
    std::istream& operator>>(std::string& s) {
        if (n <= 0) {
            throw std::ios_base::failure("EOF");
        }
        s = "\n";
        n--;
        return std::cin;
    }
};
 
int main() {
    // task item 2 simulation consists of accumulating frequency statistic
    // on 1,000,000 calls of oneOfN on simulated file.
    int n = 10;
    std::vector<int> freq(n);
    std::mt19937_64 rng(std::chrono::steady_clock::now().time_since_epoch().count());
    for (int times = 0; times < 1e6; times++) {
        simReader sr(n);
        freq[oneOfN(n, sr) - 1]++;
    }
 
    // task item 3.  show frequencies.
    for (int i = 0; i < n; i++) {
        std::cout << freq[i] << " ";
    }
    std::cout << std::endl;
}

#include <iostream>
#include <vector>
#include <string>
#include <sstream>
 
using namespace std;
 
vector<bool> sieve(unsigned long long limit) {
    limit++;
    // True denotes composite, false denotes prime.
    vector<bool> c(limit, false); // all false by default
    c[0] = true;
    c[1] = true;
    // no need to bother with even numbers over 2 for this task
    unsigned long long p = 3; // Start from 3.
    while (true) {
        unsigned long long p2 = p * p;
        if (p2 >= limit) {
            break;
        }
        for (unsigned long long i = p2; i < limit; i += 2 * p) {
            c[i] = true;
        }
        do {
            p += 2;
        } while (c[p]);
    }
    return c;
}
 
string commatize(int n) {
    ostringstream s;
    s << n;
    string str = s.str();
    if (n < 0) {
        str = str.substr(1);
    }
    int le = str.length();
    for (int i = le - 3; i >= 1; i -= 3) {
        str.insert(i, ",");
    }
    if (n >= 0) {
        return str;
    }
    return "-" + str;
}
 
int main() {
    vector<bool> c = sieve(1e10 - 1);
    int limit = 10;
    int start = 3;
    int twins = 0;
    for (int i = 1; i < 11; i++) {
        for (int i = start; i < limit; i += 2) {
            if (!c[i] &&!c[i-2]) {
                twins++;
            }
        }
        cout << "Under " << commatize(limit) << " there are " << commatize(twins) << " pairs of twin primes." << endl;
        start = limit + 1;
        limit *= 10;
    }
}

