#include <iostream>
#include <set>
#include <vector>
 
template <typename T>
std::set<std::set<T>> powerset(std::set<T> set) {
    if (set.empty()) {
        std::set<std::set<T>> powerset;
        powerset.insert(set);
        return powerset;
    }
    T entry = *set.begin();
    set.erase(set.begin());
    std::set<std::set<T>> powerset = powerset(set);
    for (auto& set : powerset) {
        set.insert(entry);
        powerset.insert(set);
    }
    return powerset;
}
 
int main() {
    std::set<int> set = {1, 2, 3, 4};
    std::set<std::set<int>> powerset = powerset(set);
    for (auto& set : powerset) {
        for (auto& entry : set) {
            std::cout << entry << " ";
        }
        std::cout << std::endl;
    }
 
    std::set<std::string> set2 = {"a", "b", "c", "d"};
    std::set<std::set<std::string>> powerset2 = powerset(set2);
    for (auto& set : powerset2) {
        for (auto& entry : set) {
            std::cout << entry << " ";
        }
        std::cout << std::endl;
    }
}

#include <iostream>
using namespace std;

bool almostPrime(int n, int k) {
    int divisor = 2, count = 0;
    while(count < k + 1 && n!= 1) {
        if (n % divisor == 0) {
            n = n / divisor;
            count = count + 1;
        } else {
            divisor++;
        }
    }
    return count == k;
}

int main() {
    for (int k = 1; k <= 5; k++) {
        cout << "k=" << k << ": ";
        int count = 0, n = 0;
        while (count <= 10) {
            n++;
            if (almostPrime(n, k)) {
                cout << n << " ";
                count++;
            }
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
 
using namespace std;
 
void magic(unsigned long long num);
string number_name(unsigned long long num);
 
const vector<string> LOW = {
    "zero", "one", "two", "three", "four", "five",
    "six", "seven", "eight","nine", "ten",
    "eleven", "twelve", "thirteen", "fourteen", "fifteen",
    "sixteen", "seventeen", "eighteen", "nineteen"
};
const vector<string> MED = {
    "twenty", "thirty", "forty", "fifty",
    "sixy", "seventy", "eighty", "ninety"
};
const vector<string> HIGH = {
    "thousand", "million", "billion",
    "trillion", "quadrillion", "quintillion"
};
 
int main() {
    magic(4);
    magic(2340);
    magic(765000);
    magic(27000001);
    magic(999123090);
    magic(239579832723441);
    magic(std::numeric_limits<unsigned long long>::max());
}
 
void magic(unsigned long long num) {
    if (num == 4) {
        cout << "four is magic!" << endl;
        cout << endl;
        return;
    }
    string name = number_name(num);
    unsigned long long len = name.length();
    cout << name << " is " << number_name(len) << ", ";
    magic(len);
}
 
string number_name(unsigned long long num) {
    if (num < 20) {
        return LOW[num];
    }
    if (num < 100) {
        unsigned long long index = (num / 10) - 2;
        string tens = MED[index];
        unsigned long long remainder = num % 10;
        if (remainder > 0) {
            return tens + "-" + number_name(remainder);
        }
        return tens;
    }
    if (num < 1000) {
        string hundreds = LOW[num / 100];
        unsigned long long remainder = num % 100;
        if (remainder > 0) {
            return hundreds + " hundred " + number_name(remainder);
        }
        return hundreds + " hundred";
    }
 
    unsigned long long remainder = num % 1000;
    string cur = (remainder > 0)? number_name(remainder) : "";
    unsigned long long n = num / 1000;
 
    for (auto noun : HIGH) {
        if (n > 0) {
            remainder = n % 1000;
            if (remainder > 0) {
                // this condition resolves double space issues
                cur = (cur.length() > 0)? number_name(remainder) + " " + noun + " " + cur : number_name(remainder) + " " + noun;
            }
            n /= 1000;
        }
    }
    return cur;
}

