#include <iostream>
#include <cmath>
#include <cstdlib>
#include <cstdint>
#include <cassert>
#include <tuple>

using namespace std;

tuple<int,int> digitalRootBase(int x, int b) {
   if (x < b)
      return make_tuple(0,x);
 
   int fauxroot = 0;
   while (b <= x) {
      x = (x / b) | 0;
      fauxroot += x % b;
   }
 
   auto rootobj = digitalRootBase(fauxroot,b);
   get<0>(rootobj) += 1;
   return rootobj;
}

int main() {
   auto rootobj = digitalRootBase(123456789,10);
   cout << "addpers = " << get<0>(rootobj) << endl;
   cout << "digrt = " << get<1>(rootobj) << endl;
   return 0;
}

#include<graphics.h>
#include<stdlib.h>
#include<stdio.h>
 
typedef struct{
    int row, col;
}cell;
 
int ROW,COL,SUM=0;
 
unsigned long raiseTo(int base,int power){
    if(power==0)
        return 1;
    else
        return base*raiseTo(base,power-1);
}
 
cell* kroneckerProduct(char* inputFile,int power){
    FILE* fp = fopen(inputFile,"r");
 
    int i,j,k,l;
    unsigned long prod;
    int** matrix;
    cell *coreList,*tempList,*resultList;
 
    fscanf(fp,"%d%d",&ROW,&COL);
 
    matrix = (int**)malloc(ROW*sizeof(int*));
 
    for(i=0;i<ROW;i++){
        matrix[i] = (int*)malloc(COL*sizeof(int));
        for(j=0;j<COL;j++){
            fscanf(fp,"%d",&matrix[i][j]);
            if(matrix[i][j]==1)
                SUM++;
        }
    }
 
    coreList = (cell*)malloc(SUM*sizeof(cell));
    resultList = (cell*)malloc(SUM*sizeof(cell));
 
    k = 0;
 
    for(i=0;i<ROW;i++){
        for(j=0;j<COL;j++){
            if(matrix[i][j]==1){
                coreList[k].row = i+1;
                coreList[k].col = j+1;
                resultList[k].row = i+1;
                resultList[k].col = j+1;
                k++;
            }
        }
    }
 
    prod = k;
 
    for(i=2;i<=power;i++){
        tempList = (cell*)malloc(prod*k*sizeof(cell));
 
        l = 0;
 
        for(j=0;j<prod;j++){
            for(k=0;k<SUM;k++){
                tempList[l].row = (resultList[j].row-1)*ROW + coreList[k].row;
                tempList[l].col = (resultList[j].col-1)*COL + coreList[k].col;
                l++;
            }
        }
 
        free(resultList);
 
        prod *= k;
 
        resultList = (cell*)malloc(prod*sizeof(cell));
 
        for(j=0;j<prod;j++){
            resultList[j].row = tempList[j].row;
            resultList[j].col = tempList[j].col;
        }
        free(tempList);
    }
 
    return resultList;
}
 
int main(){
    char fileName[100];
    int power,i,length;
 
    cell* resultList;
 
    printf("Enter input file name : ");
    scanf("%s",fileName);
 
    printf("Enter power : ");
    scanf("%d",&power);
 
    resultList = kroneckerProduct(fileName,power);
 
    initwindow(raiseTo(ROW,power),raiseTo(COL,power),"Kronecker Product Fractal");
 
    length = raiseTo(SUM,power);
 
    for(i=0;i<length;i++){
        putpixel(resultList[i].row,resultList[i].col,15);
    }
 
    getch();
 
    closegraph();
 
    return 0;
}

void shell(int a[]) {
	int increment = a.length / 2;
	while (increment > 0) {
		for (int i = increment; i < a.length; i++) {
			int j = i;
			int temp = a[i];
			while (j >= increment && a[j - increment] > temp) {
				a[j] = a[j - increment];
				j = j - increment;
			}
			a[j] = temp;
		}
		if (increment == 2) {
			increment = 1;
		} else {
			increment *= (5.0 / 11);
		}
	}
}

#include <iostream>
#include <string>
 
bool square_free(unsigned long long n) {
    if (n % 4 == 0) {
        return false;
    }
    unsigned long long p = 3;
    while (p * p <= n) {
        int count = 0;
        while (n % p == 0) {
            count++;
            if (count > 1) {
                return false;
            }
            n /= p;
        }
        p += 2;
    }
    return true;
}
 
void print_square_free_numbers(unsigned long long from, unsigned long long to) {
    std::cout << "Square-free numbers between " << from << " and " << to << ":\n";
    std::string line;
    for (unsigned long long i = from; i <= to; i++) {
        if (square_free(i)) {
            if (!line.empty()) {
                line +='';
            }
            line += std::to_string(i);
            if (line.size() >= 80) {
                std::cout << line << '\n';
                line.clear();
            }
        }
    }
    if (!line.empty()) {
        std::cout << line << '\n';
    }
}
 
void print_square_free_count(unsigned long long from, unsigned long long to) {
    int count = 0;
    for (unsigned long long i = from; i <= to; i++) {
        if (square_free(i)) {
            count++;
        }
    }
    std::cout << "Number of square-free numbers between " << from << " and " << to << ": " << count << '\n';
}
 
int main() {
    print_square_free_numbers(1, 145);
    print_square_free_numbers(1000000000000, 1000000000145);
    unsigned long long n = 100;
    while (n <= 1000000) {
        print_square_free_count(1, n);
        n *= 10;
    }
}

#include <iostream>
