#include <algorithm>
#include <random>
#include <chrono>
 
using namespace std;
 
double statistic(const vector<int>& ab, const vector<int>& a)
{
    double sumab = accumulate(ab.begin(), ab.end(), 0);
    double suma = accumulate(a.begin(), a.end(), 0);
    return ( suma / a.size() -
             (sumab -suma) / (ab.size() - a.size()) );
}
 
double permutationTest(const vector<int>& a, const vector<int>& b)
{
    vector<int> ab(a.size() + b.size());
    copy(a.begin(), a.end(), ab.begin());
    copy(b.begin(), b.end(), ab.begin() + a.size());
    double Tobs = statistic(ab, a);
    int under = 0;
    int count = 0;
    do {
        if (statistic(ab, a) <= Tobs)
            under++;
        count++;
    } while (next_permutation(ab.begin(), ab.end()));
    return under * 100. / count;
}
 
int main()
{
    vector<int> treatmentGroup = {85, 88, 75, 66, 25, 29, 83, 39, 97};
    vector<int> controlGroup   = {68, 41, 10, 49, 16, 65, 32, 92, 28, 98};
    double under = permutationTest(treatmentGroup, controlGroup);
    cout << "under=" << under << "%, over=" << 100. - under << "%" << endl;
}

