#include <iostream>
#include <vector>
#include <algorithm>
 
using namespace std;
 
bool is_prime(int n) {
    if (n > 1) {
        for (int x = 2; x <= (n / 2) + 1; x++) {
            if (n % x == 0) {
                return false;
            }
        }
        return true;
    } else {
        return false;
    }
}
 
// The modulo operator actually calculates the remainder.
int modulo(int n, int m) {
    return ((n % m) + m) % m;
}
 
vector<tuple<int, int, int>> carmichael(int p1) {
    vector<tuple<int, int, int>> results;
    if (!is_prime(p1)) {
        return results;
    }
 
    for (int h3 = 2; h3 < p1; h3++) {
        for (int d = 1; d < (h3 + p1); d++) {
            if ((h3 + p1) * (p1 - 1) % d!= 0 || modulo(-p1 * p1, h3)!= d % h3) {
                continue;
            }
 
            int p2 = 1 + ((p1 - 1) * (h3 + p1) / d);
            if (!is_prime(p2)) {
                continue;
            }
 
            int p3 = 1 + (p1 * p2 / h3);
            if (!is_prime(p3) || ((p2 * p3) % (p1 - 1)!= 1)) {
                continue;
            }
 
            results.push_back(make_tuple(p1, p2, p3));
        }
    }
 
    return results;
}
 
int main() {
    for (int x = 1; x < 62; x++) {
        if (is_prime(x)) {
            vector<tuple<int, int, int>> results = carmichael(x);
            if (!results.empty()) {
                for (auto result : results) {
                    cout << "(" << get<0>(result) << ", " << get<1>(result) << ", " << get<2>(result) << ")" << endl;
                }
            }
        }
    }
}

