#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
 
using namespace std;
 
int chinese_remainder(vector<int> mods, vector<int> remainders)
{
  int max = accumulate(mods.begin(), mods.end(), 1, multiplies<int>());
  vector<vector<int>> series;
  for (int i = 0; i < remainders.size(); i++)
  {
    vector<int> temp;
    for (int j = remainders[i]; j < max; j += mods[i])
    {
      temp.push_back(j);
    }
    series.push_back(temp);
  }
  vector<int> result;
  set_intersection(series[0].begin(), series[0].end(), series[1].begin(), series[1].end(), back_inserter(result));
  set_intersection(result.begin(), result.end(), series[2].begin(), series[2].end(), back_inserter(result));
  if (result.size() == 0)
  {
    return 0;
  }
  else
  {
    return result[0];
  }
}
 
int main()
{
  vector<int> mods = {3, 5, 7};
  vector<int> remainders = {2, 3, 2};
  cout << chinese_remainder(mods, remainders) << endl;
  return 0;
}

#include <iostream>
#include <cmath>
 
using namespace std;
 
int main()
{
    int i, j, n;
    unsigned long long x;
    unsigned long long f[16];
    unsigned long long bigs[4] = { 16758243290880ULL, 24959017348650ULL, 14593825548650ULL, 0 };
    unsigned long long tens[20];
    tens[0] = 1;
    for (i = 1; i < 20; i++)
        tens[i] = tens[i - 1] * 10;
 
    for (x = 1, n = 0; n < 25; x++)
    {
        if ((j = fangs(x, f, tens)) == 0) continue;
        cout << ++n << ": ";
        show_fangs(x, f, j);
    }
 
    cout << endl;
    for (i = 0; bigs[i] > 0 ; i++)
    {
        if ((j = fangs(bigs[i], f, tens)) > 0)
            show_fangs(bigs[i], f, j);
        else
            cout << bigs[i] << " is not vampiric." << endl;
    }
    return 0;
}
 
void show_fangs(unsigned long long x, unsigned long long f[], int cnt)
{
    cout << x; 
    int i;
    for (i = 0; i < cnt; i++)
        cout << " = " << f[i] << " * " << (x / f[i]);
    cout << endl;
}
 
int fangs(unsigned long long x, unsigned long long f[], unsigned long long tens[])
{
    int n = 0;
    int nd = ndigits(x);
    if ((nd & 1) > 0) return 0;
    nd /= 2;
 
    unsigned long long lo, hi;
    lo = max(tens[nd - 1], (x + tens[nd] - 2) / (tens[nd] - 1));
    hi = min(x / lo, (unsigned long long) sqrt(x));
 
    unsigned long long a, b, t = dtally(x);
    for (a = lo; a <= hi; a++)
    {
        b = x / a;
        if (a * b == x && ((a % 10) > 0 || (b % 10) > 0) && t == dtally(a) + dtally(b))
            f[n++] = a;
    }
 
    return n;
}
 
unsigned long long dtally(unsigned long long x)
{
    unsigned long long t = 0;
    while (x > 0)
    {
        t += 1ULL << (int)((x % 10) * 6);
        x /= 10;
    }
 
    return t;
}
 
int ndigits(unsigned long long x)
{
    int n = 0;
    while (x > 0)
    {
        n++;
        x /= 10;
    }
    return n;
}

#include <iostream>
 
using namespace std;
 
int max (int *a, int n, int i, int j, int k) {
    int m = i;
    if (j < n && a[j] > a[m]) {
        m = j;
    }
    if (k < n && a[k] > a[m]) {
        m = k;
    }
    return m;
}
 
void downheap (int *a, int n, int i) {
    while (1) {
        int j = max(a, n, i, 2 * i + 1, 2 * i + 2);
        if (j == i) {
            break;
        }
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
        i = j;
    }
}
 
void heapsort (int *a, int n) {
    int i;
    for (i = (n - 2) / 2; i >= 0; i--) {
        downheap(a, n, i);
    }
    for (i = 0; i < n; i++) {
        int t = a[n - i - 1];
        a[n - i - 1] = a[0];
        a[0] = t;
        downheap(a, n - i - 1, 0);
    }
}
 
int main () {
    int a[] = {4, 65, 2, -31, 0, 99, 2, 83, 782, 1};
    int n = sizeof a / sizeof a[0];
    int i;
    for (i = 0; i < n; i++)
        cout << a[i] << (i == n - 1? "\n" : " ");
    heapsort(a, n);
    for (i = 0; i < n; i++)
        cout << a[i] << (i == n - 1? "\n" : " ");
    return 0;
}

