}

#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <cstdlib>
#include <cctype>
 
using namespace std;
 
class Sexpr {
public:
	Sexpr() {}
	Sexpr(const string& s) { parse(s); }
	Sexpr(const char* s) { parse(s); }
	Sexpr(const Sexpr& s) { *this = s; }
	Sexpr& operator=(const Sexpr& s) {
		data = s.data;
		for (int i=0, e=s.size(); i<e; i++)
			data.push_back(new Sexpr(*s[i]));
		return *this;
	}
	~Sexpr() { clear(); }
	void clear() {
		for (int i=0, e=size(); i<e; i++)
			delete data[i];
		data.clear();
	}
	void parse(const string& s) {
		clear();
		istringstream iss(s);
		parse(iss);
	}
	void parse(istream& is) {
		clear();
		string token;
		while (is >> token) {
			if (token == "(") {
				Sexpr* s = new Sexpr();
				s->parse(is);
				data.push_back(s);
			} else if (token == ")") {
				return;
			} else if (token == "\"") {
				string s;
				getline(is, s, '"');
				data.push_back(new Sexpr(s));
			} else {
				if (token[0] == '\'')
					data.push_back(new Sexpr(token.substr(1)));
				else {
					char* end;
					double d = strtod(token.c_str(), &end);
					if (end == token.c_str() + token.size())
						data.push_back(new Sexpr(d));
					else
						data.push_back(new Sexpr(token));
				}
			}
		}
	}
	int size() const { return data.size(); }
	Sexpr& operator[](int i) { return *data[i]; }
	const Sexpr& operator[](int i) const { return *data[i]; }
	string toString() const {
		string s;
		for (int i=0, e=size(); i<e; i++)
			s += (i? " " : "") + data[i]->toString();
		return "(" + s + ")";
	}
	string toPretty(string s = "") const {
		if (s.empty()) s = "";
		string r = s + "(\n";
		string s2 = s + string(6,'');
		for (int i=0, e=size(); i<e; i++) {
			const Sexpr& ai = *data[i];
			r += ai.size()? ai.toPretty(s2) : s2 + ai.toString() + "\n";
		}
		return r + s + ")\n";
	}
private:
	vector<Sexpr*> data;
};
 
int main() {
	string str = "((data \"quoted data\" 123 4.5)\n (data (!@# (4.5) \"(more\" \"data)\")))";
	cout << "text:\n" << str << "\n\n";
	Sexpr sexpr(str);
	cout << "s-expr:\n" << sexpr.toString() << "\n\n";
	cout << "pretty print:\n" << sexpr.toPretty() << "\n";
	return 0;
}

