#include <iostream>
#include <vector>
#include <cmath>
#include <cstdlib>
 
using namespace std;
 
class HofstadterConway10000
{
public:
    HofstadterConway10000()
    {
        sequence.push_back(0);
        sequence.push_back(1);
        sequence.push_back(1);
    }
 
    int operator[](int n)
    {
        if (n < 1)
        {
            cerr << "n must be >= 1" << endl;
            exit(1);
        }
        int a = sequence.size();
        for (int i = a; i <= n; i++)
        {
            sequence.push_back(sequence[sequence[i-1]] + sequence[i-sequence[i-1]]);
        }
        return sequence[n];
    }
 
private:
    vector<int> sequence;
};
 
int main()
{
    HofstadterConway10000 hc;
    int mallows = 0;
    for (int i = 1; i < 20; i++)
    {
        int j = i + 1;
        int max_n = -1;
        double max_v = -1;
        for (int n = pow(2, i); n < pow(2, j); n++)
        {
            double v = (double)hc[n] / n;
            if (v > max_v)
            {
                max_n = n;
                max_v = v;
            }
            if (v >= 0.55)
            {
                mallows = n;
            }
        }
        cout << "maximum between 2^" << i << " and 2^" << j << " occurs at" << max_n << ": " << max_v << endl;
    }
    cout << "the mallows number is " << mallows << endl;
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
#include <sstream>
#include <vector>
#include <cstdlib>
#include <cstdio>
#include <cstring>
 
using namespace std;
 
static int badHrs, maxBadHrs;
 
static double hrsTot = 0.0;
static int rdgsTot = 0;
string bhEndDate;
 
int mungeLine( string line, int lno, ofstream &fout )
{
    string date, tkn;
    int   dHrs, flag, hrs2, hrs;
    double hrsSum;
    int   hrsCnt = 0;
    double avg;
 
    stringstream ss(line);
    ss >> date >> hrs2;
    if (ss.fail()) {
        cout << "badly formated line - " << lno << " " << line << endl;
        return 0;
    }
    hrsSum = 0.0;
    while( ss >> dHrs >> flag >> hrs) {
        if (ss.fail()) {
            cout << "bad file syntax line " << lno << ": " << line << endl;
            return 0;
        }
        if (flag > 0) {
            hrsSum += 1.0*hrs2 +.001*dHrs;
            hrsCnt += 1;
            if (maxBadHrs < badHrs) {
                maxBadHrs = badHrs;
                bhEndDate = date;
            }
            badHrs = 0;
        }
        else {
            badHrs += 1;
        }
        hrs2 = hrs;
    }
    avg = (hrsCnt > 0)? hrsSum/hrsCnt : 0.0;
    fout << date << "  Reject: " << 24-hrsCnt << "  Accept: " << hrsCnt << "  Average: " << hrsSum/hrsCnt << endl;
    hrsTot += hrsSum;
    rdgsTot += hrsCnt;
    return 1;
}
 
int main()
{
    ifstream infile;
    ofstream outfile;
    int lineNo = 0;
    string line;
    const char *ifilename = "readings.txt";
    outfile.open("V0.txt");
 
    infile.open(ifilename);
    if (!infile) {
        cout << "Can't open " << ifilename << endl;
        exit(1);
    }
    while (getline(infile, line)) {
        lineNo += 1;
        if (0 == mungeLine(line, lineNo, outfile))
            cout << "Bad line at " << lineNo << endl;
    }
    infile.close();
 
    outfile << "File:     " << ifilename << endl;
    outfile << "Total:    " << hrsTot << endl;
    outfile << "Readings: " << rdgsTot << endl;
    outfile << "Average:  " << hrsTot/rdgsTot << endl;
    outfile << "\nMaximum number of consecutive bad readings is " << maxBadHrs << endl;
    outfile << "Ends on date " << bhEndDate << endl;
    outfile.close();
    return 0;
}

