using namespace std;
 
int main()
{
  // string creation
  string x = "hello world";
  
  // string destruction
  x = "";
  
  // string assignment with a null byte
  x = "a\0b";
  cout << x.length() << endl;
  
  // string comparison
  if (x == "hello")
    cout << "equal" << endl;
  else
    cout << "not equal" << endl;
  string y = "bc";
  if (x < y)
    cout << x << " is lexicographically less than " << y << endl;
  
  // string cloning 
  string xx = x;
  if (x == xx)
    cout << "equal" << endl;
  else
    cout << "not equal" << endl;
  if (x.compare(xx) == 0)
    cout << "equal" << endl;
  else
    cout << "not equal" << endl;
  
  // check if empty
  if (x.empty())
    cout << "is empty" << endl;
  
  // append a byte
  x += "\07";
  cout << x << endl;
  
  // substring
  xx = x.substr(0, x.length() - 2);
  cout << xx << endl;
  x.replace(1, 2, "XYZ");
  cout << x << endl;
  
  // replace bytes
  y = "hello world";
  y.replace(y.find("l"), 1, "L");
  cout << y << endl;
  
  // join strings
  string a = "hel";
  string b = "lo w";
  string c = "orld";
  string d = a + b + c;
  cout << d << endl;
}

#include <iostream>
#include <string>
#include <vector>
#include <cstdlib>
#include <cmath>
 
struct Coefficient {
    size_t i;
    double c;
};
 
std::ostream& operator<<(std::ostream& os, const Coefficient& c) {
    if (c.c == 0.) {
        return os;
    }
 
    os << (c.c < 0.? "-" : (os.flags() & std::ios::showpos)? " " : "+")
       << (std::abs(c.c - 1.) < std::numeric_limits<double>::epsilon()? "" : std::abs(c.c))
       << "*e(" << c.i + 1 << ")";
 
    return os;
}
 
void usage() {
    std::cout << "Usage: display-linear-combination a1 [a2 a3...]" << std::endl;
}
 
std::string linear_combination(const std::vector<double>& coefficients) {
    std::string string;
 
    auto iter = coefficients.cbegin();
 
    // find first nonzero argument
    while (iter!= coefficients.cend()) {
        if (*iter == 0.) {
            ++iter;
            continue;
        }
 
        string += std::to_string(Coefficient{iter - coefficients.cbegin(), *iter});
        break;
    }
 
    // print subsequent arguments
    for (; iter!= coefficients.cend(); ++iter) {
        string += std::to_string(Coefficient{iter - coefficients.cbegin(), *iter});
    }
 
    return string;
}
 
int main(int argc, char** argv) {
    std::vector<double> coefficients;
 
    // parse arguments into floats
    for (int i = 1; i < argc; ++i) {
        char* end;
        double c = std::strtod(argv[i], &end);
        if (*end!= '\0') {
            std::cerr << "Failed to parse argument \"" << argv[i] << "\"" << std::endl;
            return -1;
        }
        coefficients.push_back(c);
    }
 
    // no arguments, print usage and exit
    if (coefficients.empty()) {
        usage();
        return 0;
    }
 
    std::cout << linear_combination(coefficients) << std::endl;
}

