#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
 
using namespace std;
 
int main() {
    ifstream file("days_of_week.txt");
    string line;
    int i = 0;
 
    while (getline(file, line)) {
        i++;
        if (line.length() > 0) {
            vector<string> days;
            string day;
            stringstream ss(line);
            while (ss >> day) {
                days.push_back(day);
            }
            if (days.size()!= 7) {
                throw runtime_error("There aren't 7 days in line " + to_string(i));
            }
 
            map<string, int> temp;
            for (auto day : days) {
                if (temp.find(day)!= temp.end()) {
                    cout << " ∞  " << line << endl;
                    continue;
                }
                temp[day] = 1;
            }
 
            int len = 1;
            while (true) {
                temp.clear();
                for (auto day : days) {
                    string key;
                    if (len < day.length()) {
                        key = day.substr(0, len);
                    } else {
                        key = day;
                    }
                    if (temp.find(key)!= temp.end()) {
                        break;
                    }
                    temp[key] = 1;
                }
                if (temp.size() == 7) {
                    cout << setw(2) << len << "  " << line << endl;
                    break;
                }
                len++;
            }
        }
    }
}

#include <vector>
#include <algorithm>
#include <iostream>

template<typename T>
std::vector<std::vector<T>> Permutations(std::vector<T> values)
{
    if (values.size() == 1)
        return { values };
    std::vector<std::vector<T>> result;
    for (auto v : values)
    {
        auto p = Permutations(std::vector<T>(values.begin(), values.end()));
        p.erase(std::remove(p.begin(), p.end(), v), p.end());
        for (auto& x : p)
        {
            x.insert(x.begin(), v);
            result.push_back(x);
        }
    }
    return result;
}

int main()
{
    std::vector<int> values = { 1, 2, 3 };
    auto result = Permutations(values);
    for (auto& x : result)
    {
        for (auto& y : x)
        {
            std::cout << y << " ";
        }
        std::cout << std::endl;
    }
}

bool jortSort( vector<int> array ) {
 
  // sort the array
  vector<int> originalArray = array;
  sort( array.begin(), array.end() );
 
  // compare to see if it was originally sorted
  for (int i = 0; i < originalArray.size(); ++i) {
    if (originalArray[i]!= array[i]) return false;
  }
 
  return true;
};

#include <iostream>
#include <vector>
#include <stdexcept>
 
using namespace std;
 
class Deck {
public:
	vector<int> Cards;
	int length;
	Deck(int deckSize) {
		if (deckSize % 2!= 0) {
			throw invalid_argument("Deck size must be even");
		}
		length = deckSize;
		Cards.resize(deckSize);
		for (int i = 0; i < deckSize; i++) {
			Cards[i] = i;
		}
	}
	void shuffleDeck() {
		vector<int> tmp(length);
		for (int i = 0; i < length / 2; i++) {
			tmp[i * 2] = Cards[i];
			tmp[i * 2 + 1] = Cards[length / 2 + i];
		}
		Cards = tmp;
	}
	bool isEqualTo(Deck c) {
		if (length!= c.length) {
			throw invalid_argument("Decks aren't equally sized");
		}
		bool res = true;
		for (int i = 0; i < length; i++) {
			if (Cards[i]!= c.Cards[i]) {
				res = false;
			}
		}
		return res;
	}
};
 
int ShufflesRequired(int deckSize) {
	Deck deck(deckSize);
	Deck Ref = deck;
	deck.shuffleDeck();
	int res = 1;
	while (!deck.isEqualTo(Ref)) {
		deck.shuffleDeck();
		res++;
	}
	return res;
}
 
int main() {
	for (int v : { 8,24,52,100,1020,1024,10000 }) {
		cout << "Cards count: " << v << ", shuffles required: " << ShufflesRequired(v) << endl;
	}
}

#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <cassert>
#include <algorithm>
#include <iterator>
#include <cstdlib>
 
using namespace std;
 
const string head = "H";
const string tail = "t";
const string conductor = ".";
const string empty = " ";
const vector<string> allstates = {head, tail, conductor, empty};
 
struct WW {
    vector<vector<string>> world;
    int w, h;
};
 
WW readfile(istream& f) {
    vector<string> world;
    string row;
    while (getline(f, row)) {
        world.push_back(row);
    }
    int height = world.size();
    int width = max_element(world.begin(), world.end(),
                            [](const string& a, const string& b) {
                                return a.size() < b.size();
                            })->size();
    // fill right and frame in empty cells
    string nonrow(width,'');
    world.insert(world.begin(), nonrow);
    world.push_back(nonrow);
    for (auto& row : world) {
        row.insert(row.begin(),'');
        row.append(width - row.size() + 1,'');
    }
    return WW{world, width, height};
}
 
string newcell(const vector<vector<string>>& currentworld, int x, int y) {
    string istate = currentworld[y][x];
    assert(find(allstates.begin(), allstates.end(), istate)!= allstates.end());
    string ostate;
    if (istate == head) {
        ostate = tail;
    } else if (istate == tail) {
        ostate = conductor;
    } else if (istate == empty) {
        ostate = empty;
    } else { // istate == conductor
        int n = 0;
        for (int dx = -1; dx <= 1; ++dx) {
            for (int dy = -1; dy <= 1; ++dy) {
                if (currentworld[y+dy][x+dx] == head) {
                    ++n;
                }
            }
        }
        ostate = (1 <= n && n <= 2)? head : conductor;
    }
    return ostate;
}
 
WW nextgen(const WW& ww) {
    vector<vector<string>> newworld = ww.world;
    for (int x = 1; x <= ww.w; ++x) {
        for (int y = 1; y <= ww.h; ++y) {
            newworld[y][x] = newcell(ww.world, x, y);
        }
    }
    return WW{newworld, ww.w, ww.h};
}
 
string world2string(const WW& ww) {
    ostringstream oss;
    for (int y = 1; y <= ww.h; ++y) {
        copy(ww.world[y].begin()+1, ww.world[y].end()-1,
             ostream_iterator<string>(oss));
        oss << endl;
    }
    return oss.str();
}
 
int main() {
    stringstream infile(R"(
tH.........
.  .
  ...
.  .
Ht........\
)");
    WW ww = readfile(infile);
    for (int gen = 0; gen < 10; ++gen) {
        cout << "\n" << gen << " " << string(ww.w-4, '=') << "\n";
        cout << world2string(ww);
        ww = nextgen(ww);
    }
}

