#include <iostream>
#include <vector>
#include <boost/multiprecision/C++_int.hpp>
 
using namespace boost::multiprecision;
 
class Bernoulli {
public:
    Bernoulli(int n) {
        A.resize(n + 1);
        for (int m = 0; m <= n; ++m)
            A[m] = BigFraction(1, m + 1);
        for (int m = 0; m <= n; ++m)
            for (int j = m; j >= 1; --j)
                A[j - 1] = A[j - 1] - A[j] * j;
    }
 
    BigFraction operator[](int n) const {
        return A[n];
    }
 
private:
    std::vector<BigFraction> A;
};
 
int main() {
    for (int n = 0; n <= 60; ++n)
        if (n % 2 == 0 || n == 1)
            std::cout << "B(" << n << ") = " << Bernoulli(n)[0] << std::endl;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
 
const char *ca = "/*", *cb = "*/";
int al = 2, bl = 2;
 
char *loadfile(const char *fn) {
    FILE *f = fopen(fn, "rb");
    int l;
    char *s;
 
    if (f!= NULL) {
	fseek(f, 0, SEEK_END);
	l = ftell(f);
	s = malloc(l+1);
	rewind(f);
	if (s)
	    fread(s, 1, l, f);
	fclose(f);
    }
    return s;
}
 
void stripcomments(char *s) {
    char *a, *b;
    int len = strlen(s) + 1;
 
    while ((a = strstr(s, ca))!= NULL) {
	b = strstr(a+al, cb);
	if (b == NULL)
	    break;
	b += bl;
	memmove(a, b, len-(b-a));
    }
}
 
int main(int argc, char **argv) {
    const char *fn = "input.txt";
    char *s;
 
    if (argc >= 2)
	fn = argv[1];
    s = loadfile(fn);
    if (argc == 4) {
	al = strlen(ca = argv[2]);
	bl = strlen(cb = argv[3]);
    }
    stripcomments(s);
    puts(s);
    free(s);
    return 0;
}

#include <iostream>
#include <cmath>
 
using namespace std;
 
int verbose = 0;
#define COND(a, b) int a(int *s) { return (b); }
typedef int(*condition)(int *);
 
/* BEGIN problem specific setup */
#define N_FLOORS 5
#define TOP (N_FLOORS - 1)
int solution[N_FLOORS] = { 0 };
int occupied[N_FLOORS] = { 0 };
 
enum tenants {
	baker = 0,
	cooper,
	fletcher,
	miller,
	smith,
	phantom_of_the_opera,
};
 
const char *names[] = {
	"baker",
	"cooper",
	"fletcher",
	"miller",
	"smith",
};
 
COND(c0, s[baker]!= TOP);
COND(c1, s[cooper]!= 0);
COND(c2, s[fletcher]!= 0 && s[fletcher]!= TOP);
COND(c3, s[miller] > s[cooper]);
COND(c4, abs(s[smith] - s[fletcher])!= 1);
COND(c5, abs(s[cooper] - s[fletcher])!= 1);
#define N_CONDITIONS 6
 
condition cond[] = { c0, c1, c2, c3, c4, c5 };
 
/* END of problem specific setup */
 
int solve(int person)
{
	int i, j;
	if (person == phantom_of_the_opera) {
		/* check condition */
		for (i = 0; i < N_CONDITIONS; i++) {
			if (cond[i](solution)) continue;
 
			if (verbose) {
				for (j = 0; j < N_FLOORS; j++)
					cout << solution[j] << " " << names[j] << endl;
				cout << "cond " << i << " bad" << endl << endl;
			}
			return 0;
		}
 
		cout << "Found arrangement:" << endl;
		for (i = 0; i < N_FLOORS; i++)
			cout << solution[i] << " " << names[i] << endl;
		return 1;
	}
 
	for (i = 0; i < N_FLOORS; i++) {
		if (occupied[i]) continue;
		solution[person] = i;
		occupied[i] = 1;
		if (solve(person + 1)) return 1;
		occupied[i] = 0;
	}
	return 0;
}
 
int main()
{
	verbose = 0;
	if (!solve(0)) cout << "Nobody lives anywhere" << endl;
	return 0;
}

