#include <iostream>
#include <vector>
#include <string>
#include <map>
 
using namespace std;
 
const int EVEN_ROOT = 0;
const int ODD_ROOT = 1;
 
class Node {
public:
    Node(int length) {
        this->length = length;
        this->edges = map<char, int>();
    }
 
    Node(int length, map<char, int> edges, int suffix) {
        this->length = length;
        this->edges = edges;
        this->suffix = suffix;
    }
 
    int length;
    map<char, int> edges;
    int suffix;
};
 
vector<Node> Eertree(string s) {
    vector<Node> tree = {
        Node(-1, map<char, int>(), ODD_ROOT),
        Node(0, map<char, int>(), ODD_ROOT)
    };
    int suffix = ODD_ROOT;
    int n, k;
    for (int i = 0; i < s.length(); i++) {
        char c = s[i];
        for (n = suffix; ; n = tree[n].suffix) {
            k = tree[n].length;
            int b = i - k - 1;
            if (b >= 0 && s[b] == c) {
                break;
            }
        }
        if (tree[n].edges.count(c)) {
            suffix = tree[n].edges[c];
            continue;
        }
        suffix = tree.size();
        tree.push_back(Node(k + 2));
        tree[n].edges[c] = suffix;
        if (tree[suffix].length == 1) {
            tree[suffix].suffix = 0;
            continue;
        }
        while (true) {
            n = tree[n].suffix;
            int b = i - tree[n].length - 1;
            if (b >= 0 && s[b] == c) {
                break;
            }
        }
        tree[suffix].suffix = tree[n].edges[c];
    }
    return tree;
}
 
vector<string> SubPalindromes(vector<Node> tree) {
    vector<string> s;
    SubPalindromes_children(0, "", tree, s);
    for (auto c : tree[1].edges) {
        int m = tree[1].edges[c.first];
        string ct = string(1, c.first);
        s.push_back(ct);
        SubPalindromes_children(m, ct, tree, s);
    }
    return s;
}
 
void SubPalindromes_children(int n, string p, vector<Node> tree, vector<string> &s) {
    for (auto c : tree[n].edges) {
        int m = tree[n].edges[c.first];
        string p1 = string(1, c.first) + p + string(1, c.first);
        s.push_back(p1);
        SubPalindromes_children(m, p1, tree, s);
    }
}
 
int main() {
    vector<Node> tree = Eertree("eertree");
    vector<string> result = SubPalindromes(tree);
    string listStr = "";
    for (int i = 0; i < result.size(); i++) {
        listStr += result[i];
        if (i < result.size() - 1) {
            listStr += ", ";
        }
    }
    cout << "[" << listStr << "]" << endl;
}

#include <iostream>
#include <string>
#include <gmpxx.h>
 
using namespace std;
 
mpz_class factorial(mpz_class n){
	mpz_class ans = 1;
	for(mpz_class x = 1; x <= n; x++){
		ans *= x;
	}
	return ans;
}
 
mpz_class leftFact(mpz_class n){
	mpz_class ans = 0;
	for(mpz_class k = 0; k <= n - 1; k++){
		ans += factorial(k);
	}
	return ans;
}
 
int main(){
	for(int i = 0; i <= 10; i++){
		cout << "!" << i << " = " << leftFact(i) << endl;
	}
 
	for(int i = 20; i <= 110; i += 10){
		cout << "!" << i << " = " << leftFact(i) << endl;
	}
 
	for(int i = 1000; i <= 10000; i += 1000){
		cout << "!" << i << " has " << leftFact(i).get_str().length() << " digits" << endl;
	}
}

