#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
 
using namespace std;
 
vector<int> divisors(int n) {
    vector<int> divs = {1};
    vector<int> divs2;
 
    int i = 2;
    while (i * i <= n) {
        if (n % i == 0) {
            int j = n / i;
            divs.push_back(i);
            if (i!= j) {
                divs2.push_back(j);
            }
        }
        i++;
    }
 
    copy(divs2.rbegin(), divs2.rend(), back_inserter(divs));
 
    return divs;
}
 
int abundantOdd(int searchFrom, int countFrom, int countTo, bool printOne) {
    int count = countFrom;
    int n = searchFrom;
 
    while (count < countTo) {
        vector<int> divs = divisors(n);
        int tot = accumulate(divs.begin(), divs.end(), 0);
        if (tot > n) {
            count++;
            if (!printOne || count >= countTo) {
                string s = accumulate(divs.begin(), divs.end(), string(), [](string s, int i) { return s + (s.empty()? "" : " + ") + to_string(i); });
                if (printOne) {
                    cout << n << " < " << s << " = " << tot << endl;
                } else {
                    cout << count << ". " << n << " < " << s << " = " << tot << endl;
                }
            }
        }
 
        n += 2;
    }
 
    return n;
}
 
int main() {
    int max = 25;
    cout << "The first " << max << " abundant odd numbers are:" << endl;
    int n = abundantOdd(1, 0, 25, false);
 
    cout << "\nThe one thousandth abundant odd number is:" << endl;
    abundantOdd(n, 25, 1000, true);
 
    cout << "\nThe first abundant odd number above one billion is:" << endl;
    abundantOdd((1e9 + 1), 0, 1, true);
}

#include <cmath>
#include <vector>
#include <algorithm>
#include <iostream>
 
using namespace std;
 
int isqrt(int n) {
    return (int)sqrt(n);
}
 
bool is_semiprime(int n) {
    int root = isqrt(n) + 1;
    vector<int> primes1;
    for (int i = 2; i < root; i++) {
        if (n % i == 0) {
            primes1.push_back(i);
        }
    }
    int count = 0;
 
    for (int i = 0; i < primes1.size(); i++) {
        while (n % primes1[i] == 0) {
            n /= primes1[i];
            count++;
        }
        if (n == 1) {
            break;
        }
    }
 
    if (n!= 1) {
        count++;
    }
    return count == 2;
}
 
int main() {
    int count = 0;
    for (int i = 2; i < 10; i++) {
        if (is_semiprime(i)) {
            count++;
        }
    }
    cout << count << endl;
}

