#include <iostream>
#include <vector>
#include <map>
#include <algorithm>
using namespace std;

vector<int> mode(vector<int> ary) {
    map<int, int> counter;
    vector<int> mode;
    int max = 0;
    for (int i = 0; i < ary.size(); i++) {
        if (counter.find(ary[i]) == counter.end())
            counter[ary[i]] = 0;
        counter[ary[i]]++;

        if (counter[ary[i]] == max)
            mode.push_back(ary[i]);
        else if (counter[ary[i]] > max) {
            max = counter[ary[i]];
            mode.clear();
            mode.push_back(ary[i]);
        }
    }
    return mode;
}

int main() {
    vector<int> ary;
    ary.push_back(1);
    ary.push_back(3);
    ary.push_back(6);
    ary.push_back(6);
    ary.push_back(6);
    ary.push_back(6);
    ary.push_back(7);
    ary.push_back(7);
    ary.push_back(12);
    ary.push_back(12);
    ary.push_back(17);
    vector<int> mode_ary = mode(ary);
    for (int i = 0; i < mode_ary.size(); i++)
        cout << mode_ary[i] << " ";
    cout << endl;
    return 0;
}

#include <iostream>
#include <string>
 
using namespace std;
 
void match(string first, string second) {
    cout << "1. " << first << " starts with " << second << ": " << first.find(second) == 0 << endl;
    int i = first.find(second);
    cout << "2. " << first << " contains " << second << ": " << i >= 0 << endl;
    if (i >= 0) {
        cout << "2.1. at location " << i << endl;
        for (int start = i+1;; ) {
            if ((i = first.find(second, start)) < 0) {
                break;
            }
            cout << "2.2. at location " << i << endl;
            start = i+1;
        }
        cout << "2.2. and that's all" << endl;
    }
    cout << "3. " << first << " ends with " << second << ": " << first.rfind(second) == first.length() - second.length() << endl;
}
 
int main() {
    match("abracadabra", "abr");
}

#include <iostream>
#include <gsl/gsl_matrix.h>
#include <gsl/gsl_math.h>
#include <gsl/gsl_multifit.h>
 
double w[] = {	52.21, 53.12, 54.48, 55.84, 57.20,
		58.57, 59.93, 61.29, 63.11, 64.47,
		66.28, 68.10, 69.92, 72.19, 74.46 };
double h[] = {	1.47, 1.50, 1.52, 1.55, 1.57,
		1.60, 1.63, 1.65, 1.68, 1.70,
		1.73, 1.75, 1.78, 1.80, 1.83	};
 
int main()
{
	int n = sizeof(h)/sizeof(double);
	gsl_matrix *X = gsl_matrix_calloc(n, 3);
	gsl_vector *Y = gsl_vector_alloc(n);
	gsl_vector *beta = gsl_vector_alloc(3);
 
	for (int i = 0; i < n; i++) {
		gsl_vector_set(Y, i, w[i]);
 
		gsl_matrix_set(X, i, 0, 1);
		gsl_matrix_set(X, i, 1, h[i]);
		gsl_matrix_set(X, i, 2, h[i] * h[i]);
	}
 
	double chisq;
	gsl_matrix *cov = gsl_matrix_alloc(3, 3);
	gsl_multifit_linear_workspace * wspc = gsl_multifit_linear_alloc(n, 3);
	gsl_multifit_linear(X, Y, beta, cov, &chisq, wspc);
 
	std::cout << "Beta:";
	for (int i = 0; i < 3; i++)
		std::cout << "  " << gsl_vector_get(beta, i);
	std::cout << std::endl;
 
	gsl_matrix_free(X);
	gsl_matrix_free(cov);
	gsl_vector_free(Y);
	gsl_vector_free(beta);
	gsl_multifit_linear_free(wspc);
 
}

