#include <iostream>
#include <cmath>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
 
using namespace std;
 
void printAverageAngle(vector<double> sample);
double getMeanAngle(vector<double> anglesDeg);
 
int main() {
    printAverageAngle({350.0, 10.0});
    printAverageAngle({90.0, 180.0, 270.0, 360.0});
    printAverageAngle({10.0, 20.0, 30.0});
    printAverageAngle({370.0});
    printAverageAngle({180.0});
}
 
void printAverageAngle(vector<double> sample) {
    double meanAngle = getMeanAngle(sample);
    stringstream ss;
    ss << "The mean angle of ";
    for (int i = 0; i < sample.size(); i++) {
        ss << sample[i];
        if (i < sample.size() - 1) {
            ss << ", ";
        }
    }
    ss << " is " << meanAngle;
    cout << ss.str() << endl;
}
 
double getMeanAngle(vector<double> anglesDeg) {
    double x = 0.0;
    double y = 0.0;
 
    for (double angleD : anglesDeg) {
        double angleR = angleD * M_PI / 180.0;
        x += cos(angleR);
        y += sin(angleR);
    }
    double avgR = atan2(y / anglesDeg.size(), x / anglesDeg.size());
    return avgR * 180.0 / M_PI;
}

std::string MakeList(std::string separator)
{
    int counter = 1;
 
    auto makeItem = [&counter, separator](std::string item)
    {
        return std::to_string(counter++) + separator + item + "\n";
    };
 
    return makeItem("first") + makeItem("second") + makeItem("third");
}
 
std::cout << MakeList(". ");

