std::string strip_characters(const std::string& original, const std::string& to_strip) {
    std::string result;
    std::remove_copy_if(original.begin(), original.end(), std::back_inserter(result), [&to_strip](char c) {
        return to_strip.find(c)!= std::string::npos;
    });
    return result;
}

