#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
 
using namespace std;
 
const vector<string> months = {
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
};
 
class Birthday {
public:
    int month;
    int day;
 
    Birthday(int month, int day) {
        this->month = month;
        this->day = day;
    }
 
    string toString() {
        return months[month - 1] + " " + to_string(day);
    }
 
    bool monthUniqueIn(vector<Birthday> bds) {
        return count_if(bds.begin(), bds.end(), [this](Birthday bd) { return this->month == bd.month; }) == 1;
    }
 
    bool dayUniqueIn(vector<Birthday> bds) {
        return count_if(bds.begin(), bds.end(), [this](Birthday bd) { return this->day == bd.day; }) == 1;
    }
 
    bool monthWithUniqueDayIn(vector<Birthday> bds) {
        return any_of(bds.begin(), bds.end(), [this](Birthday bd) { return (this->month == bd.month) && bd.dayUniqueIn(bds); });
    }
};
 
int main() {
    vector<Birthday> choices = {
        Birthday(5, 15), Birthday(5, 16), Birthday(5, 19), Birthday(6, 17), 
        Birthday(6, 18), Birthday(7, 14), Birthday(7, 16), Birthday(8, 14),
        Birthday(8, 15), Birthday(8, 17)
    };
 
    // Albert knows the month but doesn't know the day.
    // So the month can't be unique within the choices.
    vector<Birthday> filtered = choices;
    filtered.erase(remove_if(filtered.begin(), filtered.end(), [](Birthday bd) { return bd.monthUniqueIn(choices); }), filtered.end());
 
    // Albert also knows that Bernard doesn't know the answer.
    // So the month can't have a unique day.
    filtered.erase(remove_if(filtered.begin(), filtered.end(), [](Birthday bd) { return bd.monthWithUniqueDayIn(filtered); }), filtered.end());
 
    // Bernard now knows the answer.
    // So the day must be unique within the remaining choices.
    filtered.erase(remove_if(filtered.begin(), filtered.end(), [](Birthday bd) { return!bd.dayUniqueIn(filtered); }), filtered.end());
 
    // Albert now knows the answer too.
    // So the month must be unique within the remaining choices.
    filtered.erase(remove_if(filtered.begin(), filtered.end(), [](Birthday bd) { return!bd.monthUniqueIn(filtered); }), filtered.end());
 
    if (filtered.size() == 1)
        cout << "Cheryl's birthday is " << filtered[0].toString() << endl;
    else
        cout << "Something went wrong!" << endl;
 
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

const vector<string> FACES = {"2", "3", "4", "5", "6", "7", "8", "9", "10", "j", "q", "k", "a"};
const vector<string> SUITS = {"♥", "♦", "♣", "♠"};

string analyzeHand(string hand){
	vector<string> cards;
	int jokers = 0;
	for(int i = 0; i < hand.length(); i++){
		if(hand[i] =='')
			continue;
		if(hand[i] == 'j'){
			jokers++;
			continue;
		}
		string card = "";
		while(hand[i]!=''){
			card += hand[i];
			i++;
		}
		cards.push_back(card);
	}
	vector<int> faces;
	vector<int> suits;
	for(int i = 0; i < cards.size(); i++){
		string card = cards[i];
		string face = card.substr(0, card.length() - 1);
		string suit = card.substr(card.length() - 1);
		int f = -1;
		int s = -1;
		for(int j = 0; j < FACES.size(); j++){
			if(face == FACES[j]){
				f = j;
				break;
			}
		}
		for(int j = 0; j < SUITS.size(); j++){
			if(suit == SUITS[j]){
				s = j;
				break;
			}
		}
		if(f == -1 || s == -1)
			return "invalid";
		faces.push_back(f);
		suits.push_back(s);
	}
	bool flush = true;
	for(int i = 1; i < suits.size(); i++){
		if(suits[i]!= suits[0]){
			flush = false;
			break;
		}
	}
	vector<int> groups(13, 0);
	for(int i = 0; i < faces.size(); i++){
		groups[faces[i]]++;
	}
	sort(groups.begin(), groups.end());
	vector<int> shifted;
	for(int i = 0; i < faces.size(); i++){
		shifted.push_back((faces[i] + 1) % 13);
	}
	int distance = min(max(faces[faces.size() - 1] - faces[0], shifted[shifted.size() - 1] - shifted[0]), 13);
	bool straight = groups[0] == 1 && distance < 5;
	groups[0] += jokers;
	if(groups[0] == 5)
		return "five-of-a-kind";
	else if(straight && flush)
		return "straight-flush";
	else if(groups[0] == 4)
		return "four-of-a-kind";
	else if(groups[0] == 3 && groups[1] == 2)
		return "full-house";
	else if(flush)
		return "flush";
	else if(straight)
		return "straight";
	else if(groups[0] == 3)
		return "three-of-a-kind";
	else if(groups[0] == 2 && groups[1] == 2)
		return "two-pair";
	else if(groups[0] == 2)
		return "one-pair";
	else
		return "high-card";
}

int main(){
	string hand = "2♥ 3♥ 4♥ 5♥ 6♥";
	cout << analyzeHand(hand) << endl;
	return 0;
}

#include <iostream>
#include <fstream>
#include <string>
#include <ctime>
#include <vector>
#include <cstdlib>
#include <cerrno>
#include <cstring>
 
using namespace std;
 
const string fn = "NOTES.TXT";
 
void addNote(const string& note) {
	ofstream f(fn, ios::out | ios::app | ios::binary);
	if (!f) {
		cerr << "Error opening file: " << strerror(errno) << endl;
		exit(1);
	}
	time_t t = time(0);
	char* dt = ctime(&t);
	f << dt << "\t" << note << endl;
	f.close();
}
 
void showNotes() {
	ifstream f(fn, ios::in | ios::binary);
	if (!f) {
		if (errno == ENOENT) {
			return;
		}
		cerr << "Error opening file: " << strerror(errno) << endl;
		exit(1);
	}
	string line;
	while (getline(f, line)) {
		cout << line << endl;
	}
	f.close();
}
 
int main(int argc, char* argv[]) {
	if (argc > 1) {
		vector<string> args;
		for (int i = 1; i < argc; i++) {
			args.push_back(argv[i]);
		}
		addNote(args);
	} else {
		showNotes();
	}
	return 0;
}

#include <iostream>
#include <cmath>
using namespace std;

bool is_perfect(int n)
{
 int sum = 1, i, sqrt=floor(sqrt(n));
 for (i = sqrt-1; i>1; i--)
 {
  if (n % i == 0) {
   sum += i + n/i;
  }
 }
 if(n % sqrt == 0)
  sum += sqrt + (sqrt*sqrt == n? 0 : n/sqrt);
 return sum == n;
}

int main()
{
 int i;
 for (i = 1; i < 10000; i++)
 {
  if (is_perfect(i))
   cout << i << endl;
 }
 return 0;
}

#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <cmath>
 
using namespace std;
 
int main() {
    string fileName = "src/EntropyNarcissist.java";
    cout << "Entropy of file \"" << fileName << "\" = " << getEntropy(fileName) << endl;
}
 
double getEntropy(string fileName) {
    map<char,int> characterCount;
    int length = 0;
 
    ifstream reader(fileName);
    if (!reader.is_open() ) {
        throw runtime_error("Could not open file " + fileName);
    }
 
    char c;
    while ( reader.get(c) ) {
        characterCount[c]++;
        length++;
    }
 
    double entropy = 0;
    for ( auto it = characterCount.begin(); it!= characterCount.end(); it++ ) {
        double fraction = (double) it->second / length;
        entropy -= fraction * log(fraction);
    }
 
    return entropy / log(2);
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
 
using namespace std;
 
class PlayfairCipher {
private:
    static char charTable[5][5];
    static vector<vector<int>> positions;
 
    static string prompt(string promptText, int minLen) {
        string s;
        do {
            cout << promptText;
            getline(cin, s);
        } while (s.length() < minLen);
        return s;
    }
 
    static string prepareText(string s, bool changeJtoI) {
        transform(s.begin(), s.end(), s.begin(), ::toupper);
        s.erase(remove_if(s.begin(), s.end(), [](char c) { return!isalpha(c); }), s.end());
        return changeJtoI? s.replace(s.find('J'), 1, "I") : s.replace(s.find('Q'), 1, "");
    }
 
    static void createTable(string key, bool changeJtoI) {
        string s = prepareText(key + "ABCDEFGHIJKLMNOPQRSTUVWXYZ", changeJtoI);
 
        int len = s.length();
        for (int i = 0, k = 0; i < len; i++) {
            char c = s[i];
            if (positions[c - 'A'].empty()) {
                charTable[k / 5][k % 5] = c;
                positions[c - 'A'] = { k % 5, k / 5 };
                k++;
            }
        }
    }
 
    static string encode(string s) {
        stringstream ss(s);
        string text;
        while (ss >> text) {
            for (int i = 0; i < text.length(); i += 2) {
                if (i == text.length() - 1)
                    text.append(text.length() % 2 == 1? 'X' : "");
                else if (text[i] == text[i + 1])
                    text.insert(i + 1, "X");
            }
            text = codec(text, 1);
        }
        return text;
    }
 
    static string decode(string s) {
        return codec(s, 4);
    }
 
    static string codec(string text, int direction) {
        for (int i = 0; i < text.length(); i += 2) {
            char a = text[i];
            char b = text[i + 1];
 
            int row1 = positions[a - 'A'][1];
            int row2 = positions[b - 'A'][1];
            int col1 = positions[a - 'A'][0];
            int col2 = positions[b - 'A'][0];
 
            if (row1 == row2) {
                col1 = (col1 + direction) % 5;
                col2 = (col2 + direction) % 5;
            }
            else if (col1 == col2) {
                row1 = (row1 + direction) % 5;
                row2 = (row2 + direction) % 5;
            }
            else {
                int tmp = col1;
                col1 = col2;
                col2 = tmp;
            }
 
            text[i] = charTable[row1][col1];
            text[i + 1] = charTable[row2][col2];
        }
        return text;
    }
 
public:
    static void main() {
        string key = prompt("Enter an encryption key (min length 6): ", 6);
        string txt = prompt("Enter the message: ", 1);
        string jti = prompt("Replace J with I? y/n: ", 1);
 
        bool changeJtoI = jti == "y" || jti == "Y";
 
        createTable(key, changeJtoI);
 
        string enc = encode(prepareText(txt, changeJtoI));
 
        cout << "\nEncoded message: " << enc << endl;
        cout << "\nDecoded message: " << decode(enc) << endl;
    }
};
 
char PlayfairCipher::charTable[5][5];
vector<vector<int>> PlayfairCipher::positions(26);
 
int main() {
    PlayfairCipher::main();
}

// version 1.0.6
 
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
 
using namespace std;
 
bool isDeranged(string s1, string s2) {
    for (int i = 0; i < s1.length(); i++) {
        if (s1[i] == s2[i]) {
            return false;
        }
    }
    return true;
}
 
int main() {
    ifstream file("unixdict.txt");
    map<string, vector<string>> anagrams;
    int count = 0;
    string word;
    while (getline(file, word)) {
        string key = word;
        sort(key.begin(), key.end());
        if (anagrams.find(key) == anagrams.end()) {
            vector<string> words;
            words.push_back(word);
            anagrams.insert(pair<string, vector<string>>(key, words));
        }
        else {
            vector<string> words = anagrams[key];
            bool deranged = false;
            for (int i = 0; i < words.size(); i++) {
                if (isDeranged(words[i], word)) {
                    deranged = true;
                    break;
                }
            }
            if (deranged) {
                words.push_back(word);
                anagrams[key] = words;
                count = max(count, (int)word.length());
            }
        }
    }
    file.close();
    for (map<string, vector<string>>::iterator it = anagrams.begin(); it!= anagrams.end(); it++) {
        vector<string> words = it->second;
        if (words.size() > 1 && words[0].length() == count) {
            for (int i = 0; i < words.size(); i++) {
                cout << words[i] << " ";
            }
            cout << endl;
        }
    }
    return 0;
}

