#include <cmath>
#include <string>
#include <utility>
 
using namespace std;
 
class Point {
public:
    Point(double x, double y) : x(x), y(y) {}
    double distanceFrom(const Point& other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        return sqrt(dx * dx + dy * dy);
    }
    bool operator==(const Point& other) const {
        return (x == other.x && y == other.y);
    }
    string toString() const {
        return "(" + to_string(x) + ", " + to_string(y) + ")";
    }
private:
    double x, y;
};
 
class IllegalArgumentException : public exception {
public:
    IllegalArgumentException(const string& message) : message(message) {}
    const char* what() const noexcept {
        return message.c_str();
    }
private:
    string message;
};
 
pair<Point, Point> findCircles(const Point& p1, const Point& p2, double r) {
    if (r < 0.0) throw IllegalArgumentException("the radius can't be negative");
    if (r == 0.0 && p1!= p2) throw IllegalArgumentException("no circles can ever be drawn");
    if (r == 0.0) return make_pair(p1, p1);
    if (p1 == p2) throw IllegalArgumentException("an infinite number of circles can be drawn");
    double distance = p1.distanceFrom(p2);
    double diameter = 2.0 * r;
    if (distance > diameter) throw IllegalArgumentException("the points are too far apart to draw a circle");
    Point center((p1.x + p2.x) / 2.0, (p1.y + p2.y) / 2.0);
    if (distance == diameter) return make_pair(center, center);
    double mirrorDistance = sqrt(r * r - distance * distance / 4.0);
    double dx =  (p2.x - p1.x) * mirrorDistance / distance;
    double dy =  (p2.y - p1.y) * mirrorDistance / distance;
    return make_pair(Point(center.x - dy, center.y + dx),
                     Point(center.x + dy, center.y - dx));
}
 
int main() {
    Point p[] = {
        Point(0.1234, 0.9876),
        Point(0.8765, 0.2345),
        Point(0.0000, 2.0000),
        Point(0.0000, 0.0000)
    };
    pair<Point, Point> points[] = {
        make_pair(p[0], p[1]), make_pair(p[2], p[3]), make_pair(p[0], p[0]),
        make_pair(p[0], p[1]), make_pair(p[0], p[0])
    };
    double radii[] = {2.0, 1.0, 2.0, 0.5, 0.0};
    for (int i = 0; i < 5; i++) {
        try {
            const Point& p1 = points[i].first;
            const Point& p2 = points[i].second;
            double r  = radii[i];
            cout << "For points " << p1.toString() << " and " << p2.toString() << " with radius " << r << endl;
            pair<Point, Point> circles = findCircles(p1, p2, r);
            if (circles.first == circles.second)
                cout << "there is just one circle with center at " << circles.first.toString() << endl;
            else
                cout << "there are two circles with centers at " << circles.first.toString() << " and " << circles.second.toString() << endl;
        }
        catch(const IllegalArgumentException& ex) {
            cout << ex.what() << endl;
        }
        cout << endl;
    }
}

