#include <iostream>
#include <vector>
 
using namespace std;
 
vector<int> r, s;
 
int ffr(int n) {
    while (r.size() <= n) {
        int nrk = r.size() - 1;
        int rNxt = r[nrk] + s[nrk];
        r.push_back(rNxt);
        for (int sn = r[nrk] + 2; sn < rNxt; sn++) {
            s.push_back(sn);
        }
        s.push_back(rNxt + 1);
    }
    return r[n];
}
 
int ffs(int n) {
    while (s.size() <= n) {
        ffr(r.size());
    }
    return s[n];
}
 
int main() {
    // task 3
    for (int n = 1; n <= 10; n++) {
        cout << "r(" << n << "): " << ffr(n) << endl;
    }
    // task 4
    vector<int> found(1001);
    for (int n = 1; n <= 40; n++) {
        found[ffr(n)]++;
    }
    for (int n = 1; n <= 960; n++) {
        found[ffs(n)]++;
    }
    for (int i = 1; i <= 1000; i++) {
        if (found[i]!= 1) {
            cout << "task 4: FAIL" << endl;
            return 0;
        }
    }
    cout << "task 4: PASS" << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
 
using namespace std;
 
class Rational {
public:
    Rational(int n, int d) : num(n), den(d) {
        if (den == 0) {
            throw invalid_argument("Denominator cannot be zero");
        }
        if (den < 0) {
            num = -num;
            den = -den;
        }
        int g = gcd(num, den);
        num /= g;
        den /= g;
    }
    Rational(int n) : num(n), den(1) {}
    Rational() : num(0), den(1) {}
    int numerator() const { return num; }
    int denominator() const { return den; }
    Rational operator+(const Rational& rhs) const {
        return Rational(num * rhs.den + den * rhs.num, den * rhs.den);
    }
    Rational operator-(const Rational& rhs) const {
        return Rational(num * rhs.den - den * rhs.num, den * rhs.den);
    }
    Rational operator*(const Rational& rhs) const {
        return Rational(num * rhs.num, den * rhs.den);
    }
    Rational operator/(const Rational& rhs) const {
        return Rational(num * rhs.den, den * rhs.num);
    }
    Rational operator-() const {
        return Rational(-num, den);
    }
    Rational& operator+=(const Rational& rhs) {
        *this = *this + rhs;
        return *this;
    }
    Rational& operator-=(const Rational& rhs) {
        *this = *this - rhs;
        return *this;
    }
    Rational& operator*=(const Rational& rhs) {
        *this = *this * rhs;
        return *this;
    }
    Rational& operator/=(const Rational& rhs) {
        *this = *this / rhs;
        return *this;
    }
    Rational& operator++() {
        *this += 1;
        return *this;
    }
    Rational operator++(int) {
        Rational tmp(*this);
        ++*this;
        return tmp;
    }
    Rational& operator--() {
        *this -= 1;
        return *this;
    }
    Rational operator--(int) {
        Rational tmp(*this);
        --*this;
        return tmp;
    }
    bool operator==(const Rational& rhs) const {
        return num * rhs.den == den * rhs.num;
    }
    bool operator!=(const Rational& rhs) const {
        return!(*this == rhs);
    }
    bool operator<(const Rational& rhs) const {
        return num * rhs.den < den * rhs.num;
    }
    bool operator>(const Rational& rhs) const {
        return rhs < *this;
    }
    bool operator<=(const Rational& rhs) const {
        return!(*this > rhs);
    }
    bool operator>=(const Rational& rhs) const {
        return!(*this < rhs);
    }
    friend ostream& operator<<(ostream& os, const Rational& r) {
        os << r.numerator() << "/" << r.denominator();
        return os;
    }
private:
    int num, den;
};
 
Rational calkin_wilf_next(const Rational& term) {
    return Rational(1) / (Rational(2) * term.floor() + 1 - term);
}
 
vector<int> continued_fraction(const Rational& r) {
    int a = r.numerator();
    int b = r.denominator();
    vector<int> result;
    while (b!= 1) {
        int q = a / b;
        result.push_back(q);
        tie(a, b) = make_pair(b, a - q * b);
    }
    int len = result.size();
    if (len!= 0 && len % 2 == 0) {
        result[len - 1] -= 1;
        result.push_back(1);
    }
    return result;
}
 
int term_number(const Rational& r) {
    int result = 0;
    int d = 1;
    int p = 0;
    for (int n : continued_fraction(r)) {
        for (int i = 0; i < n; ++i) {
            result |= d << p;
            ++p;
        }
        d ^= 1;
    }
    return result;
}
 
int main() {
    cout << "First 20 terms of the Calkin-Wilf sequence are:" << endl;
    Rational term(1);
    for (int i = 1; i <= 20; ++i) {
        cout << i << ": " << term << endl;
        term = calkin_wilf_next(term);
    }
    Rational r(83116, 51639);
    cout << r << " is the " << term_number(r) << "th term of the sequence." << endl;
}

#include <iostream>
#include <fstream>
#include <string>
#include <sstream>
#include <stdexcept>
 
int main() {
    std::ifstream file("data.txt");
    std::string line;
 
    while (std::getline(file, line)) {
        std::istringstream line_stream(line);
        std::string token;
 
        for (int i = 0; i < 2; i++) {
            if (!std::getline(line_stream, token,'')) {
                throw std::runtime_error("Could not parse scale: " + line);
            }
        }
 
        float magnitude;
        if (!(line_stream >> magnitude)) {
            throw std::runtime_error("Could not parse scale: " + line);
        }
 
        if (magnitude > 6.0) {
            std::cout << line << std::endl;
        }
    }
 
    return 0;
}

