#include <iostream>
#include <cmath>
 
using namespace std;
 
void print2dArray(int** array, int dimension) {
  for (int i = 0; i < dimension; i++) {
    for (int j = 0; j < dimension; j++) {
      cout << array[i][j] << " ";
    }
    cout << endl;
  }
}
 
int** getSpiralArray(int dimension) {
  int** spiralArray = new int*[dimension];
  for (int i = 0; i < dimension; i++) {
    spiralArray[i] = new int[dimension];
  }
 
  int numConcentricSquares = (int) ceil((double) dimension / 2.0);
 
  int j;
  int sideLen = dimension;
  int currNum = 0;
 
  for (int i = 0; i < numConcentricSquares; i++) {
    // do top side
    for (j = 0; j < sideLen; j++) {
      spiralArray[i][i + j] = currNum++;
    }
 
    // do right side
    for (j = 1; j < sideLen; j++) {
      spiralArray[i + j][dimension - 1 - i] = currNum++;
    }
 
    // do bottom side
    for (j = sideLen - 2; j > -1; j--) {
      spiralArray[dimension - 1 - i][i + j] = currNum++;
    }
 
    // do left side
    for (j = sideLen - 2; j > 0; j--) {
      spiralArray[i + j][i] = currNum++;
    }
 
    sideLen -= 2;
  }
 
  return spiralArray;
}
 
int main() {
  print2dArray(getSpiralArray(5), 5);
}

