task_description:
Task

Write a program that prints the integers from   1   to   100   (inclusive).



But:

   for multiples of three,   print   Fizz     (instead of the number)
   for multiples of five,   print   Buzz     (instead of the number)
   for multiples of both three and five,   print   FizzBuzz     (instead of the number) 


The   FizzBuzz   problem was presented as the lowest level of comprehension required to illustrate adequacy.



Also see

   (a blog)   dont-overthink-fizzbuzz
   (a blog)   fizzbuzz-the-programmers-stairway-to-heaven

code:
void fizzBuzz() {
    for (int number = 1; number <= 100; number++) {
        if (number % 15 == 0) {
            std::cout << "FizzBuzz" << std::endl;
        } else if (number % 3 == 0) {
            std::cout << "Fizz" << std::endl;
        } else if (number % 5 == 0) {
            std::cout << "Buzz" << std::endl;
        } else {
            std::cout << number << std::endl;
        }
    }
}

#include <iostream>
#include <cstdlib>
#include <map>
#include <vector>
#include <algorithm>
#include <cmath>
 
using namespace std;
 
int factorial(int n)
{
    return n == 0? 1 : n * factorial(n-1);
}
 
int rand_until_rep(int n)
{
    map<int, bool> rands;
    while (true) {
        int r = rand() % n + 1;
        if (rands[r])
            return rands.size();
        rands[r] = true;
    }
}
 
int main()
{
    const int runs = 1000000;
    cout << " N    average    exp.        diff   " << endl
         << "===  ========  ========  ===========" << endl;
    for (int n = 1; n <= 20; ++n) {
        double sum_of_runs = 0;
        for (int i = 0; i < runs; ++i)
            sum_of_runs += rand_until_rep(n);
        double avg = sum_of_runs / runs;
        double analytical = 0;
        for (int i = 1; i <= n; ++i)
            analytical += factorial(n) / pow(n, i) / factorial(n-i);
        cout << " " << n << "  " << avg << "  " << analytical << "  ("
             << (avg/analytical - 1)*100 << "%)" << endl;
    }
}

