#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
 
using namespace std;
 
vector<int> pascal() {
  vector<int> a;
  return [&a]() {
    if (a.size() == 0) {
      a = {1};
    } else {
      vector<int> b;
      for (int i = 0; i < a.size() - 1; i++) {
        b.push_back(a[i] + a[i + 1]);
      }
      a = {1};
      a.insert(a.end(), b.begin(), b.end());
      a.push_back(1);
    }
    return a;
  };
}
 
string show(vector<int> a) {
  int degree = a.size() - 1;
  stringstream str;
  str << "(x - 1)^" << degree << " =";
  int sgn = 1;
  for (int i = 0; i < a.size(); i++) {
    str <<'' << (sgn > 0? "+" : "-") <<'' << a[i];
    if (degree - i == 1) {
      str << "x";
    } else if (degree - i > 1) {
      str << "x^" << degree - i;
    }
    sgn = -sgn;
  }
  return str.str();
}
 
bool primerow(vector<int> row) {
  int degree = row.size() - 1;
  return all_of(row.begin() + 1, row.end() - 1, [degree](int x) { return x % degree == 0; });
}
 
int main() {
  auto p = pascal();
  for (int i = 0; i <= 7; i++) {
    cout << show(p()) << endl;
  }
  p();
  p();
  vector<int> primes;
  for (int i = 0; i < 49; i++) {
    if (primerow(p())) {
      primes.push_back(i + 1);
    }
  }
  cout << endl;
  cout << "The primes upto 50 are: ";
  for (int i = 0; i < primes.size(); i++) {
    cout << primes[i] << " ";
  }
  cout << endl;
}

