    string account;
    string password;
    int uid;
    int gid;
    vector<string> gecos;
    string directory;
    string shell;
 
    Record(string account, string password, int uid, int gid, vector<string> gecos, string directory, string shell) {
        this->account = account;
        this->password = ;
        this->uid = uid;
        this->gid = gid;
        this->gecos = gecos;
        this->directory = directory;
        this->shell = shell;
    }
 
    string toString() {
        stringstream ss;
        ss << account << ':' << password << ':' << uid << ':' << gid << ':';
        copy(gecos.begin(), gecos.end(), ostream_iterator<string>(ss, ","));
        ss << ':' << directory << ':' << shell;
        return ss.str();
    }
 
    static Record parse(string text) {
        stringstream ss(text);
        string token;
        vector<string> tokens;
        while (getline(ss, token, ':')) {
            tokens.push_back(token);
        }
        assert(tokens.size() == 7);
        return Record(tokens[0], tokens[1], atoi(tokens[2].c_str()), atoi(tokens[3].c_str()),
                      vector<string>(tokens[4].begin(), tokens[4].end()), tokens[5], tokens[6]);
    }
};
 
int main() {
    vector<string> rawData = {
            "jsmith:x:1001:1000:,Room 1007,(234)555-8917,(234)555-0077,[email protected]:/home/jsmith:/bin/bash",
            "jdoe:x:1002:1000:,Room 1004,(234)555-8914,(234)555-0044,[email protected]:/home/jdoe:/bin/bash",
            "xyz:x:1003:1000:X Yz,Room 1003,(234)555-8913,(234)555-0033,[email protected]:/home/xyz:/bin/bash"
    };
 
    vector<Record> records;
    transform(rawData.begin(), rawData.end(), back_inserter(records), Record::parse);
 
    ofstream tmp("_rosetta/.passwd");
    copy(records.begin(), records.begin() + 2, ostream_iterator<Record>(tmp, "\n"));
    tmp << records[2];
 
    ifstream in("_rosetta/.passwd");
    istream_iterator<Record> begin(in), end;
    vector<Record> records2(begin, end);
    copy(records2.begin(), records2.end(), ostream_iterator<Record>(cout, "\n"));
 
    return 0;
}

