#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
 
using namespace std;
 
class PrimeGenerator {
private:
    int limit;
    int size;
    vector<int> primes;
    vector<bool> isComposite;
 
    void sieve() {
        isComposite.resize(limit + 1, false);
        for (int i = 2; i <= limit; ++i) {
            if (!isComposite[i])
                primes.push_back(i);
            for (int j = 0; j < primes.size() && i * primes[j] <= limit; ++j) {
                isComposite[i * primes[j]] = true;
                if (i % primes[j] == 0)
                    break;
            }
        }
        size = primes.size();
    }
 
public:
    PrimeGenerator(int limit) {
        this->limit = limit;
        sieve();
    }
 
    int nextPrime() {
        if (size == 0)
            return 0;
        int prime = primes.back();
        primes.pop_back();
        --size;
        return prime;
    }
};
 
int main() {
    PrimeGenerator primeGen(100000000);
    vector<vector<int>> primesByDigits;
    vector<int> primes;
    for (int p = 10; p <= 100000000; ) {
        int prime = primeGen.nextPrime();
        if (prime > p) {
            primesByDigits.push_back(primes);
            primes.clear();
            p *= 10;
        }
        primes.push_back(prime);
    }
    cout << "First 100 brilliant numbers:" << endl;
    vector<int> brilliantNumbers;
    for (auto& primes : primesByDigits) {
        int n = primes.size();
        for (int i = 0; i < n; ++i) {
            int prime1 = primes[i];
            for (int j = i; j < n; ++j) {
                int prime2 = primes[j];
                brilliantNumbers.push_back(prime1 * prime2);
            }
        }
        if (brilliantNumbers.size() >= 100)
            break;
    }
    sort(brilliantNumbers.begin(), brilliantNumbers.end());
    for (int i = 0; i < 100; ++i) {
        char c = (i + 1) % 10 == 0? '\n' :'';
        cout << brilliantNumbers[i] << c;
    }
    cout << endl;
    long long power = 10;
    long long count = 0;
    for (int p = 1; p < 2 * primesByDigits.size(); ++p) {
        auto& primes = primesByDigits[p / 2];
        long long position = count + 1;
        long long minProduct = 0;
        int n = primes.size();
        for (int i = 0; i < n; ++i) {
            long long prime1 = primes[i];
            auto primes2 = vector<int>(primes.begin() + i, primes.end());
            long long q = (power + prime1 - 1) / prime1;
            auto it = lower_bound(primes2.begin(), primes2.end(), q);
            if (it == primes2.end())
                continue;
            long long prime2 = *it;
            long long product = prime1 * prime2;
            if (minProduct == 0 || product < minProduct)
                minProduct = product;
            position += it - primes2.begin();
            if (prime1 >= prime2)
                break;
        }
        cout << "First brilliant number >= 10^" << p << " is " << minProduct << " at position " << position << endl;
        power *= 10;
        if (p % 2 == 1) {
            long long size = primes.size();
            count += size * (size + 1) / 2;
        }
    }
}

#include <iostream>
#include <string>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <string.h>
 
int main(int argc, char *argv[]) {
    int sockfd, newsockfd, portno;
    socklen_t clilen;
    char buffer[256];
    struct sockaddr_in serv_addr, cli_addr;
    int n;
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }
    bzero((char *) &serv_addr, sizeof(serv_addr));
    portno = 8080;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(portno);
    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR on binding");
        exit(1);
    }
    listen(sockfd, 5);
    clilen = sizeof(cli_addr);
    newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &clilen);
    if (newsockfd < 0) {
        perror("ERROR on accept");
        exit(1);
    }
    n = write(newsockfd, "Goodbye, World!", 15);
    if (n < 0) {
        perror("ERROR writing to socket");
        exit(1);
    }
    close(newsockfd);
    close(sockfd);
    return 0;
}

#include <cmath>
#include <cstdlib>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
#include <Windows.h>
 
using namespace std;
 
class Form1
{
private:
    double inc;
 
public:
    Form1()
    {
        Width = Height = 640;
        StartPosition = FormStartPosition::CenterScreen;
        SetStyle(
            ControlStyles::AllPaintingInWmPaint |
            ControlStyles::UserPaint |
            ControlStyles::DoubleBuffer,
            true);
 
        var timer = new DispatcherTimer();
        timer.Tick += (s, e) => { inc = (inc + 0.05) % 360; Refresh(); };
        timer.Interval = new TimeSpan(0, 0, 0, 0, 40);
        timer.Start();
    }
 
    void DrawSpiral(Graphics g, int len, double angleIncrement)
    {
        double x1 = Width / 2;
        double y1 = Height / 2;
        double angle = angleIncrement;
 
        for (int i = 0; i < 150; i++)
        {
            double x2 = x1 + Math.Cos(angle) * len;
            double y2 = y1 - Math.Sin(angle) * len;
            g.DrawLine(Pens.Blue, (int)x1, (int)y1, (int)x2, (int)y2);
            x1 = x2;
            y1 = y2;
 
            len += 3;
 
            angle = (angle + angleIncrement) % (Math.PI * 2);
        }
    }
 
    void OnPaint(PaintEventArgs args)
    {
        var g = args.Graphics;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.Clear(Color.White);
 
        DrawSpiral(g, 5, ToRadians(inc));
    }
 
    double ToRadians(double angle)
    {
        return Math.PI * angle / 180.0;
    }
};
 
int main()
{
    Form1 form;
    return 0;
}

#include <cassert>
#include <cstdint>
#include <string>
#include <iostream>
#include <stdexcept>
 
std::string format_with_radix(uint32_t n, uint32_t radix) {
    assert(2 <= radix && radix <= 36);
 
    std::string result;
 
    while (n!= 0) {
        result.push_back(std::to_string(n % radix)[0]);
        n /= radix;
    }
 
    std::reverse(result.begin(), result.end());
    return result;
}
 
int main() {
    std::cout << format_with_radix(0xdeadbeef, 2) << std::endl;
    std::cout << format_with_radix(0xdeadbeef, 36) << std::endl;
    std::cout << format_with_radix(0xdeadbeef, 16) << std::endl;
    std::cout << std::stoul("DeadBeef", nullptr, 16) << std::endl;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cmath>
 
// version 1.2.0
 
// Holes A=0, B=1, …, H=7
// With connections:
const std::string conn = R"(
       A   B
      /|\ /|\
     / | X | \
    /  |/ \|  \
   C - D - E - F
    \  |\ /|  /
     \ | X | /
      \|/ \|/
       G   H
)";
 
const std::vector<std::pair<int, int>> connections = {
    {0, 2}, {0, 3}, {0, 4},   // A to C, D, E
    {1, 3}, {1, 4}, {1, 5},   // B to D, E, F
    {6, 2}, {6, 3}, {6, 4},   // G to C, D, E
    {7, 3}, {7, 4}, {7, 5},   // H to D, E, F
    {2, 3}, {3, 4}, {4, 5}    // C-D, D-E, E-F
};
 
// 'isValid' checks if the pegs are a valid solution.
// If the absolute difference between any pair of connected pegs is
// greater than one it is a valid solution.
bool isValid(const std::vector<int>& pegs) {
    for (const auto& [a, b] : connections) {
        if (std::abs(pegs[a] - pegs[b]) <= 1) return false;
    }
    return true;
}
 
//'solve' is a simple recursive brute force solver,
// it stops at the first found solution.
// It returns the solution, the number of positions tested,
// and the number of pegs swapped.
 
std::tuple<std::vector<int>, int, int> solve() {
    std::vector<int> pegs(8);
    std::iota(pegs.begin(), pegs.end(), 1);
    int tests = 0;
    int swaps = 0;
 
    auto recurse = [&](int i) -> bool {
        if (i >= pegs.size() - 1) {
            tests++;
            return isValid(pegs);
        }
        // Try each remaining peg from pegs[i] onwards
        for (int j = i; j < pegs.size(); j++) {
            swaps++;
            std::swap(pegs[i], pegs[j]);
            if (recurse(i + 1)) return true;
            std::swap(pegs[i], pegs[j]);
        }
        return false;
    };
 
    recurse(0);
    return {pegs, tests, swaps};
}
 
std::string pegsAsString(const std::vector<int>& pegs) {
    std::string ca = conn;
    for (int i = 0; i < ca.size(); i++) {
        if (ca[i] >= 'A' && ca[i] <= 'H') ca[i] = '0' + pegs[ca[i] - 'A'];
    }
    return ca;
}
 
int main() {
    auto [p, tests, swaps] = solve();
    std::cout << pegsAsString(p) << '\n';
    std::cout << "Tested " << tests << " positions and did " << swaps << " swaps.\n";
}

#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <string>
#include <algorithm>
#include <limits>
 
using namespace std;
 
typedef pair<string,int> edge;
 
vector<edge> get_neighbors(string u, map<string,vector<edge>> adj, set<string> Q) {
    vector<edge> neighbors;
    for (auto v : adj[u]) {
        if (Q.find(v.first)!= Q.end()) {
            neighbors.push_back(v);
        }
    }
    return neighbors;
}
 
string vertex_with_min_dist(set<string> Q, map<string,int> dist) {
    int min_distance = numeric_limits<int>::max();
    string u = "";
    for (auto v : Q) {
        if (dist[v] < min_distance) {
            min_distance = dist[v];
            u = v;
        }
    }
    return u;
}
 
vector<string> dijkstra(vector<vector<string>> edges, string source, string target) {
    set<string> Q;
    map<string,string> prev;
    map<string,int> dist;
    map<string,vector<edge>> adj;
 
    for (auto e : edges) {
        string v1 = e[0], v2 = e[1];
        int len = stoi(e[2]);
 
        Q.insert(v1);
        Q.insert(v2);
 
        dist[v1] = numeric_limits<int>::max();
        dist[v2] = numeric_limits<int>::max();
 
        if (adj.find(v1) == adj.end()) adj[v1] = vector<edge>();
        if (adj.find(v2) == adj.end()) adj[v2] = vector<edge>();
 
        adj[v1].push_back(make_pair(v2,len));
        adj[v2].push_back(make_pair(v1,len));
    }
 
    dist[source] = 0;
 
    while (Q.size()) {
        string u = vertex_with_min_dist(Q,dist);
        vector<edge> neighbors = get_neighbors(u,adj,Q);
 
        Q.erase(u);
 
        if (u == target) break;
 
        for (auto v : neighbors) {
            int alt = dist[u] + v.second;
            if (alt < dist[v.first]) {
                dist[v.first] = alt;
                prev[v.first] = u;
            }
        }
    }
 
    vector<string> path;
    string u = target;
    int len = 0;
 
    while (prev.find(u)!= prev.end()) {
        path.push_back(u);
        len += adj[u][0].second;
        u = prev[u];
    }
    path.push_back(u);
    reverse(path.begin(),path.end());
 
    return path;
}
 
int main() {
    vector<vector<string>> graph;
    graph.push_back({"a", "b", "7"});
    graph.push_back({"a", "c", "9"});
    graph.push_back({"a", "f", "14"});
    graph.push_back({"b", "c", "10"});
    graph.push_back({"b", "d", "15"});
    graph.push_back({"c", "d", "11"});
    graph.push_back({"c", "f", "2"});
    graph.push_back({"d", "e", "6"});
    graph.push_back({"e", "f", "9"});
 
    vector<string> path = dijkstra(graph, "a", "e");
    for (auto v : path) {
        cout << v << " ";
    }
    cout << endl;
 
    return 0;
}

