    ".....x.x....." +
    "....xxxxx...." +
    ".....xxx....." +
    "..x..x.x..x.." +
    "xxxxx...xxxxx" +
    "..xx.....xx.." +
    "xxxxx...xxxxx" +
    "..x..x.x..x.." +
    ".....xxx....." +
    "....xxxxx...." +
    ".....x.x....." +
    ".....x.x.....";
 
bool solve(int pz[][13], int sz, int sx, int sy, int idx, int cnt) {
    if (idx > cnt) return true;
    for (int i = 0; i < 8; i++) {
        int x = sx + moves[i][0];
        int y = sy + moves[i][1];
        if ((x >= 0) && (x < sz) && (y >= 0) && (y < sz) && (pz[x][y] == 0)) {
            pz[x][y] = idx;
            if (solve(pz, sz, x, y, idx + 1, cnt)) return true;
            pz[x][y] = 0;
        }
    }
    return false;
}
 
void findSolution(string b, int sz) {
    int pz[13][13];
    int x = 0;
    int y = 0;
    int idx = 0;
    int cnt = 0;
    for (int j = 0; j < sz; j++) {
        for (int i = 0; i < sz; i++) {
            if (b[idx] == 'x') {
                pz[i][j] = 0;
                cnt++;
            }
            else if (b[idx] =='s') {
                pz[i][j] = 1;
                cnt++;
                x = i;
                y = j;
            }
            idx++;
        }
    }
 
    if (solve(pz, sz, x, y, 2, cnt)) {
        for (int j = 0; j < sz; j++) {
            for (int i = 0; i < sz; i++) {
                if (pz[i][j]!= -1)
                    cout << setw(3) << pz[i][j] << "  ";
                else
                    cout << "    ";
            }
            cout << endl;
        }
    }
    else cout << "Cannot solve this puzzle!" << endl;
}
 
int main() {
    findSolution(board1,  8); 
    cout << endl;
    findSolution(board2, 13);
}

