#include <iostream>
#include <vector>
#include <algorithm>
 
using namespace std;
 
const string board[] = {
    ".00.00.",
    "0000000",
    "0000000",
    ".00000.",
    "..000..",
    "...0...",
};
 
const int moves[][2] = {
    {-3, 0}, {0, 3}, {3, 0}, {0, -3},
    {2, 2}, {2, -2}, {-2, 2}, {-2, -2},
};
 
int grid[100][100];
 
int totalToFill = 0;
 
bool solve(int r, int c, int count) {
    if (count > totalToFill) {
        return true;
    }
    vector<array<int, 3>> nbrs = neighbors(r, c);
    if (nbrs.size() == 0 && count!= totalToFill) {
        return false;
    }
    sort(nbrs.begin(), nbrs.end(), [](const array<int, 3>& a, const array<int, 3>& b) {
        return a[2] < b[2];
    });
 
    for (auto& nb : nbrs) {
        r = nb[0];
        c = nb[1];
        grid[r][c] = count;
        if (solve(r, c, count + 1)) {
            return true;
        }
        grid[r][c] = 0;
    }
    return false;
}
 
vector<array<int, 3>> neighbors(int r, int c) {
    vector<array<int, 3>> nbrs;
    for (auto& m : moves) {
        int x = m[0];
        int y = m[1];
        if (grid[r + y][c + x] == 0) {
            int num = countNeighbors(r + y, c + x) - 1;
            nbrs.push_back({r + y, c + x, num});
        }
    }
    return nbrs;
}
 
int countNeighbors(int r, int c) {
    int num = 0;
    for (auto& m : moves) {
        if (grid[r + m[1]][c + m[0]] == 0) {
            num++;
        }
    }
    return num;
}
 
void printResult() {
    for (int r = 0; r < 10; r++) {
        for (int c = 0; c < 10; c++) {
            if (grid[r][c] == -1) {
                cout << "   ";
            } else {
                cout << grid[r][c] << "  ";
            }
        }
        cout << endl;
    }
}
 
int main() {
    int nRows = sizeof(board) / sizeof(board[0]) + 6;
    int nCols = board[0].size() + 6;
    for (int r = 0; r < nRows; r++) {
        for (int c = 0; c < nCols; c++) {
            grid[r][c] = -1;
        }
        for (int c = 3; c < nCols - 3; c++) {
            if (r >= 3 && r < nRows - 3) {
                if (board[r - 3][c - 3] == '0') {
                    grid[r][c] = 0;
                    totalToFill++;
                }
            }
        }
    }
    int pos = -1, r = 0, c = 0;
    while (true) {
        while (true) {
            pos++;
            r = pos / nCols;
            c = pos % nCols;
            if (grid[r][c]!= -1) {
                break;
            }
        }
        grid[r][c] = 1;
        if (solve(r, c, 2)) {
            break;
        }
        grid[r][c] = 0;
        if (pos >= nRows * nCols) {
            break;
        }
    }
    printResult();
    return 0;
}

