// version 1.1.2
 
template <typename E>
class LinkedList {
    class Node {
        E data;
        Node *prev;
        Node *next;
        Node(E data, Node *prev, Node *next) : data(data), prev(prev), next(next) {}
    };
 
    Node *first;
    Node *last;
 
    LinkedList() : first(nullptr), last(nullptr) {}
 
    void addFirst(E value) {
        if (first == nullptr) {
            first = new Node(value, nullptr, nullptr);
            last = first;
        }
        else {
            Node *node = first;
            first = new Node(value, nullptr, node);
            node->prev = first;
        }
    }
 
    void addLast(E value) {
        if (last == nullptr) {
            last = new Node(value, nullptr, nullptr);
            first = last;
        }
        else {
            Node *node = last;
            last = new Node(value, node, nullptr);
            node->next = last;
        }
    }
 
    void insert(Node *after, E value) {
        if (after == nullptr)
            addFirst(value);
        else if (after == last)
            addLast(value);
        else {
            Node *next = after->next;
            Node *newNode = new Node(value, after, next);
            after->next = newNode;
            if (next!= nullptr) next->prev = newNode;
        }
    }
 
    std::string toString() {
        std::stringstream ss;
        Node *node = first;
        while (node!= nullptr) {
            ss << node->data;
            if (node->next!= nullptr) ss << " -> ";
            node = node->next;
        }
        return ss.str();
    }
};
 
int main() {
    LinkedList<int> ll;
    ll.addFirst(1);
    ll.addLast(4);
    ll.insert(ll.first, 2);
    ll.insert(ll.last->prev, 3);
    std::cout << ll.toString() << std::endl;
}

// Version 1.3.21
 
#include <iostream>
 
const int MAX = 15;
 
int countDivisors(int n) {
    int count = 0;
    int i = 1;
    while (i * i <= n) {
        if (n % i == 0) {
            count += (i == n / i)? 1 : 2;
        }
        i++;
    }
    return count;
}
 
int main() {
    std::cout << "The first " << MAX << " terms of the sequence are:" << std::endl;
    int i = 1;
    int next = 1;
    while (next <= MAX) {
        if (next == countDivisors(i)) {
            std::cout << i << " ";
            next++;
        }
        i++;
    }
    std::cout << std::endl;
}

