int middleThree(int x) {
    string s = to_string(abs(x));
    if (s.length() < 3) {
        throw invalid_argument("too short!");
    }
    if (s.length() % 2 == 0) {
        throw invalid_argument("even number of digits");
    }
    int i = (s.length() / 2) - 1;
    return stoi(s.substr(i, 3));
}

