#include <iostream>
#include <cmath>
using namespace std;
int main()
{
	double e0 = 0;
	double e = 2;
	int n = 0;
	double fact = 1;
	while(e-e0 > 1e-15)
	{
		e0 = e;
		n += 1;
		fact *= 2*n*(2*n+1);
		e += (2.*n+2)/fact;
	}
	cout << "Computed e = " << e << endl;
	cout << "Real e = " << exp(1) << endl;
	cout << "Error = " << exp(1)-e << endl;
	cout << "Number of iterations = " << n << endl;
	return 0;
}

