#include <iostream>
#include <vector>
#include <random>
 
using namespace std;
 
pair<int,int> countBullsAndCows(const vector<int>& guess, const vector<int>& answer) {
    int bulls = 0;
    int cows = 0;
    for (int i = 0; i < guess.size(); i++) {
        if (answer[i] == guess[i]) bulls++;
        else if (find(answer.begin(), answer.end(), guess[i])!= answer.end()) cows++;
    }
    return make_pair(bulls, cows);
}
 
int main() {
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(1, 9);
 
    vector<vector<int>> choices;
    // generate all possible distinct 4 digit (1 to 9) integer arrays  
    for (int i = 1; i <= 9; i++) {
        for (int j = 1; j <= 9; j++) {
            if (j == i) continue;
            for (int k = 1; k <= 9; k++) {
                if (k == i || k == j) continue;
                for (int l = 1; l <= 9; l++) {
                    if (l == i || l == j || l == k) continue;
                    choices.push_back(vector<int>{i, j, k, l});
                }
            }
        }
    } 
 
    // pick one at random as the answer
    vector<int> answer = choices[dis(gen)];
 
    // keep guessing, pruning the list as we go based on the score, until answer found
    while (true) {
        vector<int> guess = choices[dis(gen)];
        pair<int,int> score = countBullsAndCows(guess, answer);
        cout << "Guess = " << guess[0] << guess[1] << guess[2] << guess[3] << "  Bulls = " << score.first << "  Cows = " << score.second << endl;
        if (score.first == 4) {
            cout << "You've just found the answer!" << endl;
            return 0;
        }
        for (int i = choices.size() - 1; i >= 0; i--) {
            pair<int,int> score2 = countBullsAndCows(choices[i], answer);
            // if score is no better remove it from the list of choices 
            if (score2.first <= score.first && score2.second <= score.second) choices.erase(choices.begin() + i);
        }
        if (choices.size() == 0) {
            cout << "Something went wrong as no choices left! Aborting program" << endl;
            return 1;
        }
    }
}

