#include <iostream>
#include <iomanip>
#include <cmath>
#include <boost/multiprecision/C++_dec_float.hpp>
#include <boost/multiprecision/C++_int.hpp>
 
using namespace boost::multiprecision;
 
int main()
{
    typedef number<C++_dec_float<72> > mp_t;
    typedef number<C++_int> int_t;
 
    mp_t summed, nextadd;
    int_t n;
 
    for (n = 0; n < 10; ++n)
    {
        int_t p = 532 * n * n + 126 * n + 9;
        mp_t term = (p * 2 * 2 * 2 * 2 * 2 * mp_t(factorial(6 * n))) / (3 * mp_t(factorial(n)) * mp_t(factorial(n)) * mp_t(factorial(n)) * mp_t(factorial(n)) * mp_t(factorial(n)) * mp_t(factorial(n)));
        std::cout << "Term " << n << "  " << term << std::endl;
    }
 
    for (n = 0; n < 100000000; ++n)
    {
        mp_t term = (mp_t(532) * n * n + mp_t(126) * n + mp_t(9)) * mp_t(2) * mp_t(2) * mp_t(2) * mp_t(2) * mp_t(2) * mp_t(factorial(6 * n)) / (mp_t(3) * mp_t(factorial(n)) * mp_t(factorial(n)) * mp_t(factorial(n)) * mp_t(factorial(n)) * mp_t(factorial(n)) * mp_t(factorial(n)));
        nextadd = summed + term;
        if (abs(nextadd - summed) < mp_t(10.0) * mp_t(-70))
            break;
        summed = nextadd;
    }
 
    std::cout << std::endl << "π to 70 digits is " << std::setprecision(71) << std::fixed << 1.0 / sqrt(nextadd) << std::endl;
}

#include <iostream>
