#include <codecvt>
 
using namespace std;
 
class get_next_character {
public:
    get_next_character(ifstream& f) : f(f) {
        f.imbue(locale(locale(), new codecvt_utf8<wchar_t>));
    }
 
    wchar_t operator()() {
        wchar_t c;
        while (f.get(c)) {
            while (true) {
                try {
                    return c;
                } catch (range_error) {
                    // we've encountered a multibyte character
                    // read another byte and try again
                    f.get(c);
                }
            }
        }
        return 0;
    }
 
private:
    ifstream& f;
};
 
int main() {
    ifstream f("input.txt");
    for (wchar_t c : get_next_character(f)) {
        wcout << c;
    }
}

#include <iostream>
#include <vector>
#include <stdexcept>
 
using namespace std;
 
int egyptianDivide(int dividend, int divisor) {
    if (dividend < 0 || divisor <= 0) {
        throw invalid_argument("Invalid argument(s)");
    }
    if (dividend < divisor) {
        return 0;
    }
    vector<int> powersOfTwo = {1};
    vector<int> doublings = {divisor};
    int doubling = divisor;
    while (true) {
        doubling *= 2;
        if (doubling > dividend) {
            break;
        }
        int l = powersOfTwo.size();
        powersOfTwo.push_back(powersOfTwo[l-1]*2);
        doublings.push_back(doubling);
    }
    int answer = 0;
    int accumulator = 0;
    for (int i = doublings.size() - 1; i >= 0; i--) {
        if (accumulator + doublings[i] <= dividend) {
            accumulator += doublings[i];
            answer += powersOfTwo[i];
            if (accumulator == dividend) {
                break;
            }
        }
    }
    return answer;
}
 
int main() {
    int dividend = 580;
    int divisor = 34;
    int quotient = egyptianDivide(dividend, divisor);
    cout << dividend << " divided by " << divisor << " is " << quotient << endl;
    return 0;
}

template <typename T>
class LinkedList {
public:
    LinkedList(T value, LinkedList<T>* next) : _value(value), _next(next) {}
    T value() { return _value; }
    LinkedList<T>* next() { return _next; }
    void next(LinkedList<T>* next) { _next = next; }
    void insertAfter(T searchValue, LinkedList<T>* nodeToInsert) {
        if (_value == searchValue) {
            nodeToInsert->next(_next);
            _next = nodeToInsert;
        }
        else if (_next == nullptr)
            throw std::runtime_error("value '" + searchValue + "' not found in linked list.");
        else
            _next->insertAfter(searchValue, nodeToInsert);
    }
private:
    T _value;
    LinkedList<T>* _next;
};

int main() {
    LinkedList<std::string> list("A", new LinkedList<std::string>("B", nullptr));
    list.insertAfter("A", new LinkedList<std::string>("C", nullptr));
}

