#include <iostream>
#include <random>
#include <thread>
#include <vector>
 
using namespace std;
 
int nWorkers = 0;
int nTasks = 0;
 
class Worker {
private:
    int threadID;
public:
    Worker(int threadID) {
        this->threadID = threadID;
    }
 
    void run() {
        try {
            random_device rd;
            mt19937 gen(rd());
            uniform_int_distribution<> dist(100, 999);
            int workTime = dist(gen);
            cout << "Worker " << threadID << " will work for " << workTime << " msec." << endl;
            this_thread::sleep_for(chrono::milliseconds(workTime));
            nFinished++;
            cout << "Worker " << threadID << " is ready" << endl;
        }
        catch (const exception& e) {
            cout << "Error: thread execution interrupted" << endl;
            cout << e.what() << endl;
        }
    }
 
    static int nFinished;
 
    static void checkPoint() {
        while (nFinished!= nWorkers) {
            this_thread::sleep_for(chrono::milliseconds(10));
        }
        nFinished = 0;  // reset
    }
};
 
int Worker::nFinished = 0;
 
void runTasks() {
    for (int i = 1; i <= nTasks; i++) {
        cout << "\nStarting task number " << i << "." << endl;
        // Create a thread for each worker and run it.
        vector<thread> threads;
        for (int j = 1; j <= nWorkers; j++) {
            threads.push_back(thread(&Worker::run, Worker(j)));
        }
        Worker::checkPoint();  // wait for all workers to finish the task
        for (auto& t : threads) t.join();
    }
}
 
int main() {
    cout << "Enter number of workers to use: ";
    cin >> nWorkers;
    cout << "Enter number of tasks to complete: ";
    cin >> nTasks;
    runTasks();
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
 
enum class Color {
    Red,
    White,
    Blue
};
 
bool is_sorted(const std::vector<Color>& list) {
    Color state = Color::Red;
    for (auto current : list) {
        if (current < state) return false;
        if (current > state) state = current;
    }
    return true;
}
 
int main() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 2);
    std::vector<Color> colors;
 
    for (int i = 0; i < 10; ++i) {
        int r = dis(gen);
        if      (r == 0) colors.push_back(Color::Red);
        else if (r == 1) colors.push_back(Color::White);
        else if (r == 2) colors.push_back(Color::Blue);
    }
 
    while (is_sorted(colors)) {
        std::shuffle(colors.begin(), colors.end(), gen);
    }
 
    std::cout << "Before: ";
    for (auto c : colors) {
        std::cout << static_cast<int>(c) << " ";
    }
    std::cout << std::endl;
 
    std::sort(colors.begin(), colors.end());
 
    std::cout << "After:  ";
    for (auto c : colors) {
        std::cout << static_cast<int>(c) << " ";
    }
    std::cout << std::endl;
 
    if (!is_sorted(colors)) {
        std::cout << "Oops, did not sort colors correctly!" << std::endl;
    }
}

#include<graphics.h>
#include<stdlib.h>
#include<stdio.h>
#include<time.h>
 
void barnsleyFern(int windowWidth, unsigned long iter){
 
	double x0=0,y0=0,x1,y1;
	int diceThrow;
	time_t t;
	srand((unsigned)time(&t));
 
	while(iter>0){
		diceThrow = rand()%100;
 
		if(diceThrow==0){
			x1 = 0;
			y1 = 0.16*y0;
		}
 
		else if(diceThrow>=1 && diceThrow<=7){
			x1 = -0.15*x0 + 0.28*y0;
			y1 = 0.26*x0 + 0.24*y0 + 0.44;
		}
 
		else if(diceThrow>=8 && diceThrow<=15){
			x1 = 0.2*x0 - 0.26*y0;
			y1 = 0.23*x0 + 0.22*y0 + 1.6;
		}
 
		else{
			x1 = 0.85*x0 + 0.04*y0;
			y1 = -0.04*x0 + 0.85*y0 + 1.6;
		}
 
		putpixel(30*x1 + windowWidth/2.0,30*y1,GREEN);
 
		x0 = x1;
		y0 = y1;
 
		iter--;
	}
 
}
 
int main()
{
	unsigned long num;
 
	printf("Enter number of iterations : ");
	scanf("%ld",&num);
 
	initwindow(500,500,"Barnsley Fern");
 
	barnsleyFern(500,num);
 
	getch();
 
	closegraph();
 
	return 0;
}

