#include <iostream>
#include <string>
#include <algorithm>
 
void swap(std::string& str, int i, int j) {
    char c = str[i];
    str[i] = str[j];
    str[j] = c;
}
 
void reverse(std::string& str, int i, int j) {
    for (; i < j; ++i, --j)
        swap(str, i, j);
}
 
bool next_permutation(std::string& str) {
    int len = str.length();
    if (len < 2)
        return false;
    for (int i = len - 1; i > 0; ) {
        int j = i, k;
        if (str[--i] < str[j]) {
            k = len;
            while (str[i] >= str[--k]) {}
            swap(str, i, k);
            reverse(str, j, len - 1);
            return true;
        }
    }
    return false;
}
 
int main() {
    std::string numbers[] = {"0", "9", "12", "21", "12453", "738440", "45072010", "95322020"};
    const int count = sizeof(numbers)/sizeof(std::string);
    for (int i = 0; i < count; ++i) {
        std::string next = numbers[i];
        if (next_permutation(next))
            std::cout << numbers[i] << " -> " << next << std::endl;
        else
            std::cout << numbers[i] << " -> 0" << std::endl;
    }
    // Last one is too large to convert to an integer
    const char big[] = "9589776899767587796600";
    std::string next(big);
    if (next_permutation(next))
        std::cout << big << " -> " << next << std::endl;
    else
        std::cout << big << " -> 0" << std::endl;
    return 0;
}

#include <iostream>
#include <string>
#include <sstream>
using namespace std;
 
int firstNum(int n)
{
    /*Divide by ten until the leading digit remains.*/
    while (n >= 10)
    {
        n /= 10;
    }
    return (n);
}
 
int lastNum(int n)
{
    /*Modulo gives you the last digit. */
    return (n % 10);
}
 
void FindGap(int n, int gaps)
{
    int count = 0;
    while (count < gaps)
    {
 
        /* We have to convert our first and last digits to strings to concatenate.*/
        stringstream ss;
        ss << firstNum(n) << lastNum(n);
        string concat = ss.str();
        /* And then convert our concatenated string back to an integer. */
        int i = atoi(concat.c_str());
 
        /* Modulo with our new integer and output the result. */
        if (n % i == 0)
        {
            cout << n << " ";
            count++;
            n++;
        }
        else
        {
            n++;
            continue;
        }
    }
}
 
int main()
{
    cout << "The first 30 gapful numbers are: " << endl;
    /* Starting at 100, find 30 gapful numbers */
    FindGap(100, 30);
 
    cout << "The first 15 gapful numbers > 1,000,000 are: " << endl;
    FindGap(1000000, 15);
 
    cout << "The first 10 gapful numbers > 1,000,000,000 are: " << endl;
    FindGap(1000000000, 10);
 
    return 0;
}

/*
 * Program seconds2string, C++ version.
 *
 * Read input from argv[1] or stdin, write output to stdout.
 */
 
#include <iostream>
#include <sstream>
#include <string>
#include <cstdlib>
 
/*
 * Converting the number of seconds in a human-readable string.
 * It is worth noting that direct output to stdout would be even simpler.
 */
std::string seconds2string(unsigned long seconds) 
{
    int i;
 
    const unsigned long s =  1;
    const unsigned long m = 60 * s;
    const unsigned long h = 60 * m;
    const unsigned long d = 24 * h;
    const unsigned long w =  7 * d;
 
    const unsigned long coeff[5] = { w, d, h, m, s };
    const char units[5][4] = { "wk", "d", "hr", "min", "sec" };
 
    std::ostringstream buffer;
 
    for ( i = 0; i < 5; i++ )
    {
        unsigned long value;
        value   = seconds / coeff[i];
        seconds = seconds % coeff[i];
        if ( value )
        {
            if ( buffer.tellp() ) 
                buffer << ", ";
            buffer << value << " " << units[i];
        }
    }
 
    return buffer.str();
}
 
/*
 * Main function for seconds2string program.
 */
int main(int argc, char argv[])
{
    unsigned long seconds;
 
    if ( (argc <  2) && std::cin >> seconds 
    ||   (argc >= 2) && std::istringstream(argv[1]) >> seconds )
    {
        std::cout << seconds2string(seconds) << std::endl;
        return EXIT_SUCCESS;
    }
 
    return EXIT_FAILURE;
}

#include <iostream>
#include <vector>
#include <cmath>
 
using namespace std;
 
vector<vector<double>> cholesky(vector<vector<double>> array) {
	vector<vector<double>> zeros(array.size(), vector<double>(array.size(), 0));
	vector<vector<double>> L(zeros);
	for (int r = 0; r < array.size(); r++) {
		for (int c = 0; c < array.size(); c++) {
			double sum = 0;
			for (int i = 0; i < c; i++) {
				sum += L[r][i] * L[c][i];
			}
			if (c < r + 1) {
				if (r == c) {
					L[r][c] = sqrt(array[r][r] - sum);
				} else {
					L[r][c] = (array[r][c] - sum) / L[c][c];
				}
			}
		}
	}
	return L;
}
 
int main() {
	vector<vector<double>> arr3 = {{25, 15, -5}, {15, 18, 0}, {-5, 0, 11}};
	vector<vector<double>> arr4 = {{18, 22, 54, 42}, {22, 70, 86, 62}, {54, 86, 174, 134}, {42, 62, 134, 106}};
	vector<vector<double>> L3 = cholesky(arr3);
	vector<vector<double>> L4 = cholesky(arr4);
	for (int i = 0; i < L3.size(); i++) {
		for (int j = 0; j < L3.size(); j++) {
			cout << L3[i][j] << " ";
		}
		cout << endl;
	}
	cout << endl;
	for (int i = 0; i < L4.size(); i++) {
		for (int j = 0; j < L4.size(); j++) {
			cout << L4[i][j] << " ";
		}
		cout << endl;
	}
	return 0;
}

#include <iostream>
#include <cstdlib>
#include <ctime>
#include <cmath>
 
// "given"
int dice5() {
    return rand() % 5 + 1;
}
 
// function specified by task "Seven-sided dice from five-sided dice"
int dice7() {
    int i;
    do {
        i = 5*dice5() + dice5();
    } while (i >= 27);
    return (i / 3) - 1;
}
 
// function specified by task "Verify distribution uniformity/Naive"
//
// Parameter "f" is expected to return a random integer in the range 1..n.
// (Values out of range will cause an unceremonious crash.)
// "Max" is returned as an "indication of distribution achieved."
// It is the maximum delta observed from the count representing a perfectly
// uniform distribution.
// Also returned is a boolean, true if "max" is less than threshold
// parameter "delta."
std::pair<double, bool> distCheck(int (*f)(), int n,
    int repeats, double delta) {
    int count[n];
    for (int i = 0; i < n; i++) {
        count[i] = 0;
    }
    for (int i = 0; i < repeats; i++) {
        count[f()-1]++;
    }
    double expected = double(repeats) / double(n);
    double max = 0;
    for (int i = 0; i < n; i++) {
        max = std::max(max, std::abs(double(count[i])-expected));
    }
    return std::make_pair(max, max < delta);
}
 
// Driver, produces output satisfying both tasks.
int main() {
    srand(time(NULL));
    const int calls = 1000000;
    std::pair<double, bool> result = distCheck(dice7, 7, calls, 500);
    std::cout << "Max delta: " << result.first << " Flat enough: " << result.second << std::endl;
    result = distCheck(dice7, 7, calls, 500);
    std::cout << "Max delta: " << result.first << " Flat enough: " << result.second << std::endl;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>
 
using namespace std;
 
class CantorSet {
public:
    CantorSet(int lines) {
        // Convert from base 10- to base 3
        int base = 10;
        int to_base = 3;
        for (int line = 0; line < lines; line++) {
            // calculate how many repeating sequence will be in the given line
            int segment_size = pow(to_base, lines - line - 1);
            vector<bool> segment;
            for (int n = 0; n < pow(to_base, line); n++) {
                string output = convert(n, base, to_base);
                // return false in case the base 3 number contains at least one "1"
                // otherwise return true
                segment.push_back(output.find('1') == string::npos);
            }
 
            // copy the segment "segment_size" time
            vector<bool> accum;
            for (int i = 0; i < segment.size(); i++) {
                for (int j = 0; j < segment_size; j++) {
                    accum.push_back(segment[i]);
                }
            }
 
            cells.push_back(accum);
        }
    }
 
    string convert(int n, int base, int to_base) {
        string output;
        while (n > 0) {
            output += to_string(n % to_base);
            n /= to_base;
        }
        reverse(output.begin(), output.end());
        return output;
    }
 
    void print() {
        for (int i = 0; i < cells.size(); i++) {
            for (int j = 0; j < cells[i].size(); j++) {
                cout << (cells[i][j]? "█" : " ");
            }
            cout << endl;
        }
    }
 
private:
    vector<vector<bool>> cells;
};
 
int main() {
    CantorSet cs(5);
    cout << "Cantor set:" << endl;
    cs.print();
}

task_description:
Jensen's Device

You are encouraged to solve this task according to the task description, using any language you may know.
This task is an exercise in call by name.

Jensen's Device is a computer programming technique devised by Danish computer scientist Jørn Jensen after studying the ALGOL 60 Report.

The following program was proposed to illustrate the technique. It computes the 100th harmonic number:

begin
   integer i;
   real procedure sum (i, lo, hi, term);
      value lo, hi;
      integer i, lo, hi;
      real term;
      comment term is passed by-name, and so is i;
   begin
      real temp;
      temp := 0;
      for i := lo step 1 until hi do
         temp := temp + term;
      sum := temp
   end;
   comment note the correspondence between the mathematical notation and the call to sum;
   print (sum (i, 1, 100, 1/i))
end

The above exploits call by name to produce the correct answer (5.187...). It depends on the assumption that an expression passed as an actual parameter to a procedure would be re-evaluated in the caller's context every time the corresponding formal parameter's value was required. If the last parameter to sum had been passed by value, and assuming the initial value of i were 1, the result would have been 100 × 1/1 = 100.

Moreover, the first parameter to sum, representing the "bound" variable of the summation, must also be passed by name (or at least by reference), otherwise changes to it (made within sum) would not be visible in the caller's context when computing each of the values to be added.
(On the other hand, the global variable does not have to use the same identifier, in this case i, as the formal parameter.)

Donald Knuth later proposed the Man or Boy Test as a more rigorous exercise.

code:
double sum(const char* var, int lo, int hi, const char* term, void* context)
{
  double sum = 0.0;
  for (int n = lo; n <= hi; n++) {
    sum += eval(var, n, term, context);
  }
  return sum;
}

#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
#include <iterator>
 
using namespace std;
 
struct Config {
    string full_name;
    string favourite_fruit;
    bool needs_peeling;
    bool seeds_removed;
    vector<string> other_family;
};
 
Config config_from_file(string path) {
    Config cfg;
 
    ifstream file(path);
    if (!file.is_open()) {
        cout << "File not found or cannot be opened" << endl;
        return cfg;
    }
 
    string line;
    while (getline(file, line)) {
        // Remove whitespaces at the beginning and end
        line.erase(line.begin(), find_if(line.begin(), line.end(), [](int ch) {
            return!isspace(ch);
        }));
        line.erase(find_if(line.rbegin(), line.rend(), [](int ch) {
            return!isspace(ch);
        }).base(), line.end());
 
        // Ignore comments and empty lines
        if (line.empty() || line[0] == '#' || line[0] == ';') {
            continue;
        }
 
        // Split line into parameter name and rest tokens
        vector<string> tokens;
        string token;
        istringstream iss(line);
        while (iss >> token) {
            tokens.push_back(token);
        }
        string name = tokens[0];
        tokens.erase(tokens.begin());
 
        // Remove the equal signs
        tokens.erase(remove_if(tokens.begin(), tokens.end(), [](string s) {
            return s.find('=')!= string::npos;
        }), tokens.end());
        // Remove comment after the parameters
        tokens.erase(remove_if(tokens.begin(), tokens.end(), [](string s) {
            return s.find('#')!= string::npos || s.find(';')!= string::npos;
        }), tokens.end());
 
        // Concat back the parameters into one string to split for separated parameters
        string parameters;
        for (auto& s : tokens) {
            parameters += s + " ";
        }
        // Splits the parameters and trims
        vector<string> parameters_vec;
        istringstream iss2(parameters);
        while (iss2 >> token) {
            parameters_vec.push_back(token);
        }
 
        // Setting the config parameters
        if (name == "fullname") {
            cfg.full_name = parameters_vec[0];
        } else if (name == "favouritefruit") {
            cfg.favourite_fruit = parameters_vec[0];
        } else if (name == "needspeeling") {
            cfg.needs_peeling = true;
        } else if (name == "seedsremoved") {
            cfg.seeds_removed = true;
        } else if (name == "otherfamily") {
            cfg.other_family = parameters_vec;
        }
    }
 
    return cfg;
}
 
int main() {
    string path = "file.conf";
    Config cfg = config_from_file(path);
    cout << "full_name: " << cfg.full_name << endl;
    cout << "favourite_fruit: " << cfg.favourite_fruit << endl;
    cout << "needs_peeling: " << cfg.needs_peeling << endl;
    cout << "seeds_removed: " << cfg.seeds_removed << endl;
    cout << "other_family: ";
    for (auto& s : cfg.other_family) {
        cout << s << " ";
    }
    cout << endl;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cassert>
 
using namespace std;
 
template <typename T>
void order_disjoint_list_items(vector<T>& data, const vector<T>& items)
{
    //Modifies data list in-place
    vector<int> itemindices;
    for (auto item : items)
    {
        auto itemcount = count(items.begin(), items.end(), item);
        //assert(count(data.begin(), data.end(), item) >= itemcount);
        auto lastindex = -1;
        for (int i = 0; i < itemcount; ++i)
        {
            lastindex = find(data.begin(), data.end(), item) - data.begin();
            itemindices.push_back(lastindex);
        }
    }
    sort(itemindices.begin(), itemindices.end());
    for (int i = 0; i < itemindices.size(); ++i)
    {
        data[itemindices[i]] = items[i];
    }
}
 
int main()
{
    auto tostring = [](const vector<string>& v)
    {
        string s;
        for (auto& item : v)
        {
            s += item + " ";
        }
