    for (auto& data : { vector<string>{"the", "cat", "sat", "on", "the", "mat"},
                        vector<string>{"the", "cat", "sat", "on", "the", "mat"},
                        vector<string>{"the", "cat", "sat", "on", "the", "mat"},
                        vector<string>{"A", "B", "C", "A", "B", "C", "A", "B", "C"},
                        vector<string>{"A", "B", "C", "A", "B", "D", "A", "B", "E"},
                        vector<string>{"A", "B"},
                        vector<string>{"A", "B"},
                        vector<string>{"A", "B", "B", "A"},
                        vector<string>{""},
                        vector<string>{"A"},
                        vector<string>{"A", "B"},
                        vector<string>{"A", "B", "A", "B"},
                        vector<string>{"A", "B", "A", "B"},
                        vector<string>{"A", "B", "C", "C", "B", "A"},
                        vector<string>{"A", "B", "C", "C", "B", "A"} })
    {
        for (auto& items : { vector<string>{"mat", "cat"},
                             vector<string>{"cat", "mat"},
                             vector<string>{"C", "A", "C", "A"},
                             vector<string>{"E", "A", "D", "A"},
                             vector<string>{"B"},
                             vector<string>{"B", "A"},
                             vector<string>{"B", "A"},
                             vector<string>{""},
