#include <iostream>
#include <string>
#include <map>
 
using namespace std;
 
class Wheel {
public:
    Wheel(string seq) {
        this->seq = seq;
        this->len = seq.length();
        this->pos = 0;
    }
 
    char cycle() {
        char c = this->seq[this->pos];
        this->pos = (this->pos + 1) % this->len;
        return c;
    }
 
private:
    string seq;
    int len;
    int pos;
};
 
void printOne(char k, map<char, Wheel*> m) {
    Wheel *w = m[k];
    char c;
 
    if (w == NULL) {
        cout << "Missing the wheel for: " << k << endl;
        exit(1);
    }
 
    c = w->cycle();
    if ('0' <= c && c <= '9') {
        cout << " " << c;
    } else {
        printOne(c, m);
    }
}
 
void exec(char start, map<char, Wheel*> m) {
    Wheel *w;
    int i;
 
    if (m.empty()) {
        cout << "Unable to proceed." << endl;
        return;
    }
 
    for (i = 0; i < 20; i++) {
        printOne(start, m);
    }
    cout << endl;
}
 
void group1() {
    Wheel *a = new Wheel("123");
 
    map<char, Wheel*> m;
    m['A'] = a;
 
    exec('A', m);
}
 
void group2() {
    Wheel *a = new Wheel("1B2");
    Wheel *b = new Wheel("34");
 
    map<char, Wheel*> m;
    m['A'] = a;
    m['B'] = b;
 
    exec('A', m);
}
 
void group3() {
    Wheel *a = new Wheel("1DD");
    Wheel *d = new Wheel("678");
 
    map<char, Wheel*> m;
    m['A'] = a;
    m['D'] = d;
 
    exec('A', m);
}
 
void group4() {
    Wheel *a = new Wheel("1BC");
    Wheel *b = new Wheel("34");
    Wheel *c = new Wheel("5B");
 
    map<char, Wheel*> m;
    m['A'] = a;
    m['B'] = b;
    m['C'] = c;
 
    exec('A', m);
}
 
int main() {
    group1();
    group2();
    group3();
    group4();
 
    return 0;
}

