#include <iostream>
#include <cmath>
using namespace std;

double vdc(int n){
	double vdc = 0;
	int denom = 1;
	while(n!= 0){
		vdc += n % 2.0 / (denom *= 2);
		n /= 2;
	}
	return vdc;
}

int main(){
	for(int i = 0; i <= 10; i++){
		cout << vdc(i) << endl;
	}
}

