#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <iterator>
 
template <typename T>
std::vector<T> squeezable_string(const std::string& s, T squeezable) {
    std::vector<T> result;
    T previous = {};
 
    for (auto c : s) {
        if (previous == squeezable && previous == c) {
            continue;
        }
        previous = c;
        result.push_back(c);
    }
 
    return result;
}
 
int main() {
    auto show = [](const std::string& input, char c) {
        std::cout << "Squeeze: '" << c << "'\n";
        std::cout << "Input (" << input.size() << " chars): \t" << input << "\n";
        auto output = squeezable_string(input, c);
        std::cout << "Output (" << output.size() << " chars): \t";
        std::copy(output.begin(), output.end(), std::ostream_iterator<char>(std::cout));
        std::cout << "\n\n";
    };
 
    const std::string harry = R"("I never give 'em hell, I just tell the truth, and they think it's hell.
    ---  Harry S Truman")";
 
    const std::vector<std::pair<std::string, char>> inputs = {
        {"",''},
        {R"("If I were two-faced, would I be wearing this one?" --- Abraham Lincoln )", '-'},
        {"..1111111111111111111111111111111111111111111111111111111111111117777888", '7'},
        {harry,''},
        {harry, '-'},
        {harry, 'r'},
        {"The better the 4-wheel drive, the further you'll be from help when ya get stuck!", 'e'},
        {"headmistressship",'s'},
    };
 
    for (const auto& [input, c] : inputs) {
        show(input, c);
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <iterator>
#include <cmath>
 
using namespace std;
 
// n -> [[n]]
vector<vector<int>> magic(int n) {
  return n % 2? rotation(
    transposed(
      rotation(
        table(n)
      )
    )
  ) : vector<vector<int>>();
}
 
// [[a]] -> [[a]]
vector<vector<int>> rotation(vector<vector<int>> lst) {
  vector<vector<int>> result;
  for (int i = 0; i < lst.size(); i++) {
    result.push_back(rotated(
      lst[i], ((lst[i].size() + 1) / 2) - (i + 1)
    ));
  }
  return result;
}
 
// [[a]] -> [[a]]
vector<vector<int>> transposed(vector<vector<int>> lst) {
  vector<vector<int>> result;
  for (int i = 0; i < lst[0].size(); i++) {
    vector<int> row;
    for (int j = 0; j < lst.size(); j++) {
      row.push_back(lst[j][i]);
    }
    result.push_back(row);
  }
  return result;
}
 
// [a] -> n -> [a]
vector<int> rotated(vector<int> lst, int n) {
  int lng = lst.size(),
    m = (n < 0? lng + n : (n > lng? n % lng : n));
 
  vector<int> result;
  for (int i = 0; i < lng; i++) {
    result.push_back(lst[(lng - m + i) % lng]);
  }
  return result;
}
 
// n -> [[n]]
vector<vector<int>> table(int n) {
  vector<int> rngTop = rng(1, n);
 
  vector<vector<int>> result;
  for (int i = 0; i < n; i++) {
    vector<int> row;
    for (int j = 0; j < rngTop.size(); j++) {
      row.push_back(i * n + rngTop[j]);
    }
    result.push_back(row);
  }
  return result;
}
 
// [m..n]
vector<int> rng(int m, int n) {
  vector<int> result;
  for (int i = m; i <= n; i++) {
    result.push_back(i);
  }
  return result;
}
 
// Results as right-aligned wiki tables
string wikiTable(vector<vector<int>> lstRows, bool blnHeaderRow, string strStyle) {
  stringstream ss;
  ss << "{| class=\"wikitable\" " << (strStyle.empty()? "" : "style=\"" + strStyle + "\"");
  for (int iRow = 0; iRow < lstRows.size(); iRow++) {
    string strDelim = ((blnHeaderRow &&!iRow)? "!" : "|"),
      strDbl = strDelim + strDelim;
 
    ss << "\n|-\n" << strDelim << " ";
    for (int i = 0; i < lstRows[iRow].size(); i++) {
      ss << lstRows[iRow][i] << (i < lstRows[iRow].size() - 1? strDbl : "");
    }
  }
  ss << "\n|}";
  return ss.str();
}
 
int main() {
  vector<int> ns = { 3, 5, 11 };
  for (int n : ns) {
    cout << "magic(" << n << ")\n\n" << wikiTable(
      magic(n), false, "text-align:center;width:" + to_string(2.5 * n) + "em;height:" + to_string(2.5 * n) + "em;table-layout:fixed;"
    ) << "\n\n";
  }
  return 0;
}

#include <iostream>
#include <string>
#include <random>
#include <algorithm>
#include <vector>
#include <iterator>
 
using namespace std;
 
const string target = "METHINKS IT IS LIKE A WEASEL";
const string possibilities = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";
const int C = 100; //number of spawn per generation
const double minMutateRate = 0.09;
const int perfectFitness = target.length();
 
int fitness(string trial){
  int retVal = 0;
  for(int i = 0;i < trial.length(); i++){
    if (trial[i] == target[i]) retVal++;
  }
  return retVal;
}
 
double newMutateRate(string parent){
  return (((double)perfectFitness - fitness(parent)) / perfectFitness * (1 - minMutateRate));
}
 
string mutate(string parent, double rate){
  string retVal = "";
  for(int i = 0;i < parent.length(); i++){
    retVal += (rand() / (double)RAND_MAX <= rate)?
      possibilities[rand() % possibilities.length()]:
      parent[i];
  }
  return retVal;
}
 
int main(){
  string parent = mutate(target, 1);
  int iter = 0;
  while(!target.equals(parent)){
    double rate = newMutateRate(parent);
    iter++;
    if(iter % 100 == 0){
      cout << iter <<": "<<parent<< ", fitness: "<<fitness(parent)<<", rate: "<<rate<<endl;
    }
    string bestSpawn = "";
    int bestFit = 0;
    for(int i = 0; i < C; i++){
      string spawn = mutate(parent, rate);
      int fitness = fitness(spawn);
      if(fitness > bestFit){
        bestSpawn = spawn;
        bestFit = fitness;
      }
    }
    parent = bestFit > fitness(parent)? bestSpawn : parent;
  }
  cout << parent<<", "<<iter<<endl;
}

#include <iostream>
#include <cmath>
 
using namespace std;
 
class GammaFunction {
public:
	double st_gamma(double x){
		return sqrt(2*M_PI/x)*pow((x/M_E), x);
	}
 
	double la_gamma(double x){
		double p[] = {0.99999999999980993, 676.5203681218851, -1259.1392167224028,
			     	  771.32342877765313, -176.61502916214059, 12.507343278686905,
			     	  -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7};
		int g = 7;
		if(x < 0.5) return M_PI / (sin(M_PI * x)*la_gamma(1-x));
 
		x -= 1;
		double a = p[0];
		double t = x+g+0.5;
		for(int i = 1; i < 9; i++){
			a += p[i]/(x+i);
		}
 
		return sqrt(2*M_PI)*pow(t, x+0.5)*exp(-t)*a;
	}
 
	static void main() {
		GammaFunction test = GammaFunction();
		cout << "Gamma \t\tStirling \t\tLanczos" << endl;
		for(double i = 1; i <= 20; i += 1){
			cout << i/10.0 << "\t\t" << test.st_gamma(i/10.0) << "\t" << test.la_gamma(i/10.0) << endl;
		}
	}
};
 
int main() {
	GammaFunction::main();
	return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <cstdlib>
#include <cstdint>
 
using namespace std;
 
// a parsed representation
class oid {
public:
    vector<int64_t> v;
 
    // "constructor" parses string representation
    oid(const string& s) {
        stringstream ss(s);
        string n;
        while (getline(ss, n, '.')) {
            v.push_back(stoll(n));
        }
    }
 
    // "stringer" formats into string representation
    string String() const {
        stringstream ss;
        for (auto i = v.begin(); i!= v.end(); ++i) {
            if (i!= v.begin()) {
                ss << '.';
            }
            ss << *i;
        }
        return ss.str();
    }
};
 
int main() {
    // parse test cases
    vector<oid> os;
    for (auto s : vector<string>{
        "1.3.6.1.4.1.11.2.17.19.3.4.0.10",
        "1.3.6.1.4.1.11.2.17.5.2.0.79",
        "1.3.6.1.4.1.11.2.17.19.3.4.0.4",
        "1.3.6.1.4.1.11150.3.4.0.1",
        "1.3.6.1.4.1.11.2.17.19.3.4.0.1",
        "1.3.6.1.4.1.11150.3.4.0",
    }) {
        os.push_back(oid(s));
    }
    // sort
    sort(os.begin(), os.end(), [](const oid& oi, const oid& oj) {
        // "less" function must return true if os[i] < os[j]
        for (auto i = oi.v.begin(), j = oj.v.begin(); i!= oi.v.end(); ++i, ++j) {
            // lexicographic defintion: less if prefix or if element is <
            if (j == oj.v.end() || *i < *j) {
                return true;
            }
            if (*i > *j) {
                break;
            }
        }
        return false;
    });
    // output sorted list
    for (auto& o : os) {
        cout << o.String() << endl;
    }
}

