// Compute Levenshtein Distance
// Martin Ettl, 2012-10-05
 
size_t uiLevenshteinDistance(const string &s1, const string &s2)
{
  const size_t
    m(s1.size()),
    n(s2.size());
 
  if( m==0 ) return n;
  if( n==0 ) return m;
 
  // allocation below is not ISO-compliant,
  // it won't work with -pedantic-errors.
  size_t costs[n + 1];
 
  for( size_t k=0; k<=n; k++ ) costs[k] = k;
 
  size_t i { 0 };
  for (char const &c1 : s1) 
  {
    costs[0] = i+1;
    size_t corner { i },
           j      { 0 };
    for (char const &c2 : s2)
    {
      size_t upper { costs[j+1] };
      if( c1 == c2 ) costs[j+1] = corner;
      else {
        size_t t(upper<corner? upper: corner);
        costs[j+1] = (costs[j]<t?costs[j]:t)+1;
      }
 
      corner = upper;
      j++;
    }
    i++;
  }
 
  return costs[n];
}
 
int main()
{
  string s0 { "rosettacode" },
         s1 { "raisethysword" };
  cout << "distance between " << s0 << " and " << s1 << " : " 
    << uiLevenshteinDistance(s0,s1) << endl;
 
  return 0;
}

#include <iostream>
#include <string>
#include <iterator>
#include <regex>
 
int main()
{
  std::regex re(".* string$");
  std::string s = "Hi, I am a string";
 
  // match the complete string
  if (std::regex_match(s, re))
    std::cout << "The string matches.\n";
  else
    std::cout << "Oops - not found?\n";
 
  // match a substring
  std::regex re2(" a.*a");
  std::smatch match;
  if (std::regex_search(s, match, re2))
  {
    std::cout << "Matched " << match.length()
              << " characters starting at " << match.position() << ".\n";
    std::cout << "Matched character sequence: \""
              << match.str() << "\"\n";
  }
  else
  {
    std::cout << "Oops - not found?\n";
  }
 
  // replace a substring
  std::string dest_string;
  std::regex_replace(std::back_inserter(dest_string),
                       s.begin(), s.end(),
                       re2,
                       "'m now a changed");
  std::cout << dest_string << std::endl;
}

#include <vector>
 
double mean(const std::vector<double>& numbers)
{
     if (numbers.size() == 0)
          return 0;
 
     double sum = 0;
     for (std::vector<double>::iterator i = numbers.begin(); i != numbers.end(); i++)
          sum += *i;
     return sum / numbers.size();
}

#define _USE_MATH_DEFINES
 
#include <math.h>
#include <iostream>
 
const static double EarthRadiusKm = 6372.8;
 
inline double DegreeToRadian(double angle)
{
	return M_PI * angle / 180.0;
}
 
class Coordinate
{
public:
	Coordinate(double latitude ,double longitude):myLatitude(latitude), myLongitude(longitude)
	{}
 
	double Latitude() const
	{
		return myLatitude;
	}
 
	double Longitude() const
	{
		return myLongitude;
	}
 
private:
 
	double myLatitude;
	double myLongitude;
};
 
double HaversineDistance(const Coordinate& p1, const Coordinate& p2)
{
	double latRad1 = DegreeToRadian(p1.Latitude());
	double latRad2 = DegreeToRadian(p2.Latitude());
	double lonRad1 = DegreeToRadian(p1.Longitude());
	double lonRad2 = DegreeToRadian(p2.Longitude());
 
	double diffLa = latRad2 - latRad1;
	double doffLo = lonRad2 - lonRad1;
 
	double computation = asin(sqrt(sin(diffLa / 2) * sin(diffLa / 2) + cos(latRad1) * cos(latRad2) * sin(doffLo / 2) * sin(doffLo / 2)));
	return 2 * EarthRadiusKm * computation;
}
 
int main()
{
	Coordinate c1(36.12, -86.67);
	Coordinate c2(33.94, -118.4);
 
	std::cout << "Distance = " << HaversineDistance(c1, c2) << std::endl;
	return 0;
}

