#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>
 
template <typename T>
std::vector<size_t> equilibrium(T first, T last)
{
    typedef typename std::iterator_traits<T>::value_type value_t;
 
    value_t left  = 0;
    value_t right = std::accumulate(first, last, value_t(0));
    std::vector<size_t> result;
 
    for (size_t index = 0; first != last; ++first, ++index)
    {
        right -= *first;
        if (left == right)
        {
            result.push_back(index);
        }
        left += *first;
    }
    return result;
}
 
template <typename T>
void print(const T& value)
{
    std::cout << value << "\n";
}
 
int main() 
{
    const int data[] = { -7, 1, 5, 2, -4, 3, 0 };
 
    std::vector<size_t> indices(equilibrium(data, data + 7));
 
    std::for_each(indices.begin(), indices.end(), print<size_t>);
}

#include <algorithm>
#include <string>
#include <cctype>
 
// compare character case-insensitive
struct icompare_char {
  bool operator()(char c1, char c2) {
    return std::toupper(c1) < std::toupper(c2);
  }
};
 
// return true if s1 comes before s2
struct compare {
  bool operator()(std::string const& s1, std::string const& s2) {
    if (s1.length() > s2.length())
      return true;
    if (s1.length() < s2.length())
      return false;
    return std::lexicographical_compare(s1.begin(), s1.end(),
                                        s2.begin(), s2.end(),
                                        icompare_char());
  }
};
 
int main() {
  std::string strings[8] = {"Here", "are", "some", "sample", "strings", "to", "be", "sorted"};
  std::sort(strings, strings+8, compare());
  return 0;
}

#include <iostream>
#include <iterator>
#include <cstddef>
 
template<typename InIter>
 void extract_ranges(InIter begin, InIter end, std::ostream& os)
{
  if (begin == end)
    return;
 
  int current = *begin++;
  os << current;
  int count = 1;
 
  while (begin != end)
  {
    int next = *begin++;
    if (next == current+1)
      ++count;
    else
    {
      if (count > 2)
        os << '-';
      else
        os << ',';
      if (count > 1)
        os << current << ',';
      os << next;
      count = 1;
    }
    current = next;
  }
 
  if (count > 1)
    os << (count > 2? '-' : ',') << current;
}
 
template<typename T, std::size_t n>
 T* end(T (&array)[n])
{
  return array+n;
}
 
