#include <algorithm>
#include <iostream>
#include <vector>
 
std::vector<uint64_t> primes;
std::vector<uint64_t> smallPrimes;
 
template <typename T>
std::ostream &operator <<(std::ostream &os, const std::vector<T> &v) {
    auto it = v.cbegin();
    auto end = v.cend();
 
    os << '[';
 
    if (it != end) {
        os << *it;
        it = std::next(it);
    }
 
    for (; it != end; it = std::next(it)) {
        os << ", " << *it;
    }
 
    return os << ']';
}
 
bool isPrime(uint64_t value) {
    if (value < 2) return false;
 
    if (value % 2 == 0) return value == 2;
    if (value % 3 == 0) return value == 3;
 
    if (value % 5 == 0) return value == 5;
    if (value % 7 == 0) return value == 7;
 
    if (value % 11 == 0) return value == 11;
    if (value % 13 == 0) return value == 13;
 
    if (value % 17 == 0) return value == 17;
    if (value % 19 == 0) return value == 19;
 
    if (value % 23 == 0) return value == 23;
 
    uint64_t t = 29;
    while (t * t < value) {
        if (value % t == 0) return false;
        value += 2;
 
        if (value % t == 0) return false;
        value += 4;
    }
 
    return true;
}
 
void init() {
    primes.push_back(2);
    smallPrimes.push_back(2);
 
    uint64_t i = 3;
    while (i <= 521) {
        if (isPrime(i)) {
            primes.push_back(i);
            if (i <= 29) {
                smallPrimes.push_back(i);
            }
        }
        i += 2;
    }
}
 
std::vector<uint64_t> nSmooth(uint64_t n, size_t size) {
    if (n < 2 || n>521) {
        throw std::runtime_error("n must be between 2 and 521");
    }
    if (size <= 1) {
        throw std::runtime_error("size must be at least 1");
    }
 
    uint64_t bn = n;
    if (primes.cend() == std::find(primes.cbegin(), primes.cend(), bn)) {
        throw std::runtime_error("n must be a prime number");
    }
 
    std::vector<uint64_t> ns(size, 0);
    ns[0] = 1;
 
    std::vector<uint64_t> next;
    for (auto prime : primes) {
        if (prime > bn) {
            break;
        }
        next.push_back(prime);
    }
 
    std::vector<size_t> indicies(next.size(), 0);
    for (size_t m = 1; m < size; m++) {
        ns[m] = *std::min_element(next.cbegin(), next.cend());
        for (size_t i = 0; i < indicies.size(); i++) {
            if (ns[m] == next[i]) {
                indicies[i]++;
                next[i] = primes[i] * ns[indicies[i]];
            }
        }
    }
 
    return ns;
}
 
int main() {
    init();
 
    for (auto i : smallPrimes) {
        std::cout << "The first " << i << "-smooth numbers are:\n";
        std::cout << nSmooth(i, 25) << '\n';
        std::cout << '\n';
    }
 
    // there is not enough bits to fully represent the 3-smooth numbers
    for (size_t i = 0; i < smallPrimes.size(); i++) {
        if (i < 1) continue;
        auto p = smallPrimes[i];
 
        auto v = nSmooth(p, 3002);
        v.erase(v.begin(), v.begin() + 2999);
 
        std::cout << "The 30,000th to 30,019th " << p << "-smooth numbers are:\n";
        std::cout << v << '\n';
        std::cout << '\n';
    }
 
    return 0;
}

#include <iomanip>
#include <iostream>
 
int mod(int n, int d) {
    return (d + n % d) % d;
}
 
bool is_prime(int n) {
    if (n < 2)
        return false;
    if (n % 2 == 0)
        return n == 2;
    if (n % 3 == 0)
        return n == 3;
    for (int p = 5; p * p <= n; p += 4) {
        if (n % p == 0)
            return false;
        p += 2;
        if (n % p == 0)
            return false;
    }
    return true;
}
 
void print_carmichael_numbers(int prime1) {
    for (int h3 = 1; h3 < prime1; ++h3) {
        for (int d = 1; d < h3 + prime1; ++d) {
            if (mod((h3 + prime1) * (prime1 - 1), d) != 0
                || mod(-prime1 * prime1, h3) != mod(d, h3))
                continue;
            int prime2 = 1 + (prime1 - 1) * (h3 + prime1)/d;
            if (!is_prime(prime2))
                continue;
            int prime3 = 1 + prime1 * prime2/h3;
            if (!is_prime(prime3))
                continue;
            if (mod(prime2 * prime3, prime1 - 1) != 1)
                continue;
            unsigned int c = prime1 * prime2 * prime3;
            std::cout << std::setw(2) << prime1 << " x "
                << std::setw(4) << prime2 << " x "
                << std::setw(5) << prime3 << " = "
                << std::setw(10) << c << '\n';
        }
    }
}
 
int main() {
    for (int p = 2; p <= 61; ++p) {
        if (is_prime(p))
            print_carmichael_numbers(p);
    }
    return 0;
}

#include <iostream>
using namespace std;
 
int toInt(const char c)
{
    return c-'0';
}
 
int confirm( const char *id)
{
    bool is_odd_dgt = true;
    int s = 0;
    const char *cp;
 
    for(cp=id; *cp; cp++);
    while(cp > id) {
        --cp;
        int k = toInt(*cp);
        if (is_odd_dgt) {
            s += k;
        }
        else {
            s += (k!=9)? (2*k)%9 : 9;
        }
	is_odd_dgt = !is_odd_dgt;
    }
    return 0 == s%10;
}
 
