        "fire. favor who those with hold I",
        "",
        "... elided paragraph last ...",
        "",
        "Frost Robert -----------------------"
    };
 
   std::for_each(begin(str1), end(str1), [](std::string& s){
      block_reverse_C++11(begin(s), end(s), ' ');
      std::cout << s << std::endl;
   });
 
   std::for_each(begin(str1), end(str1), [](std::string& s){
      block_reverse_C++03(begin(s), end(s), ' ');
