code:
// Calculate the Digital Root and Additive Persistance of an Integer - Compiles with gcc4.7
//
// Nigel Galloway. July 23rd., 2012
//
#include <iostream>
#include <cmath>
#include <utility>
 
template<class P_> P_ IncFirst(const P_& src) {return P_(src.first + 1, src.second);}
 
std::pair<int, int> DigitalRoot(unsigned long long digits, int base = 10) 
{
    int x = SumDigits(digits, base);
    return x < base ? std::make_pair(1, x) : IncFirst(DigitalRoot(x, base));  // x is implicitly converted to unsigned long long; this is lossless
}
 
int main() {
    const unsigned long long ip[] = {961038,923594037444,670033,448944221089};
    for (auto i:ip){
        auto res = DigitalRoot(i);
        std::cout << i << " has digital root " << res.second << " and additive persistance " << res.first << "\n";
    }
    std::cout << "\n";
    const unsigned long long hip[] = {0x7e0,0x14e344,0xd60141,0x12343210};
    for (auto i:hip){
        auto res = DigitalRoot(i,16);
        std::cout << std::hex << i << " has digital root " << res.second << " and additive persistance " << res.first << "\n";
    }
    return 0;
}

#include <set>
#include <iostream>
#include <iterator>
#include <algorithm>
 
namespace set_display {
template <class T>
std::ostream& operator<<(std::ostream& os, const std::set<T>& set)
{
    os << '[';
    if (!set.empty()) {
        std::copy(set.begin(), --set.end(), std::ostream_iterator<T>(os, ", "));
        os << *--set.end();
    }
    return os << ']';
}
}
 
template <class T>
bool contains(const std::set<T>& set, const T& key)
{
    return set.count(key) != 0;
}
 
template <class T>
std::set<T> set_union(const std::set<T>& a, const std::set<T>& b)
{
    std::set<T> result;
    std::set_union(a.begin(), a.end(), b.begin(), b.end(), std::inserter(result, result.end()));
    return result;
}
 
template <class T>
std::set<T> set_intersection(const std::set<T>& a, const std::set<T>& b)
{
    std::set<T> result;
    std::set_intersection(a.begin(), a.end(), b.begin(), b.end(), std::inserter(result, result.end()));
    return result;
}
 
template <class T>
std::set<T> set_difference(const std::set<T>& a, const std::set<T>& b)
{
    std::set<T> result;
    std::set_difference(a.begin(), a.end(), b.begin(), b.end(), std::inserter(result, result.end()));
    return result;
}
 
template <class T>
bool is_subset(const std::set<T>& set, const std::set<T>& subset)
{
    return std::includes(set.begin(), set.end(), subset.begin(), subset.end());
}
 
int main()
{
    using namespace set_display;
    std::set<int> a{2, 5, 7, 5, 9, 2}; //C++11 initialization syntax
    std::set<int> b{1, 5, 9, 7, 4 };
    std::cout << "a = " << a << '\n';
    std::cout << "b = " << b << '\n';
 
    int value1 = 8, value2 = 5;
    std::cout << "Set a " << (contains(a, value1) ? "contains " : "does not contain ") << value1 << '\n';
    std::cout << "Set a " << (contains(a, value2) ? "contains " : "does not contain ") << value2 << '\n';
 
    std::cout << "Union of a and b: " << set_union(a, b) << '\n';
    std::cout << "Intersection of a and b: " << set_intersection(a, b) << '\n';
    std::cout << "Difference of a and b: " << set_difference(a, b) << '\n';
 
    std::set<int> sub{5, 9};
    std::cout << "Set b " << (is_subset(a, b) ? "is" : "is not") << " a subset of a\n";
    std::cout << "Set " << sub << ' ' << (is_subset(a, sub) ? "is" : "is not") << " a subset of a\n";
 
    std::set<int> copy = a;
    std::cout << "a " << (a == copy ? "equals " : "does not equal ") << copy << '\n';
 
    return 0;
}

template<typename F> class fivetoseven
{
public:
  fivetoseven(F f): d5(f), rem(0), max(1) {}
  int operator()();
private:
  F d5;
  int rem, max;
};
 
template<typename F>
 int fivetoseven<F>::operator()()
{
  while (rem/7 == max/7)
  {
    while (max < 7)
    {
      int rand5 = d5()-1;
      max *= 5;
      rem = 5*rem + rand5;
    }
 
    int groups = max / 7;
    if (rem >= 7*groups)
    {
      rem -= 7*groups;
      max -= 7*groups;
    }
  }
 
  int result = rem % 7;
  rem /= 7;
  max /= 7;
  return result+1;
}
 
int d5()
{
  return 5.0*std::rand()/(RAND_MAX + 1.0) + 1;
}
 
fivetoseven<int(*)()> d7(d5);
 
int main()
{
  srand(time(0));
  test_distribution(d5, 1000000, 0.001);
  test_distribution(d7, 1000000, 0.001);
}

#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
 
auto load_dictionary(const std::string& path) {
    std::ifstream in(path);
    if (!in)
        throw std::runtime_error("Cannot open file " + path);
    std::string line;
    std::vector<std::string> words;
    while (getline(in, line))
        words.push_back(line);
    return words;
}
 
double jaro_winkler_distance(std::string str1, std::string str2) {
    size_t len1 = str1.size();
    size_t len2 = str2.size();
    if (len1 < len2) {
        std::swap(str1, str2);
        std::swap(len1, len2);
    }
    if (len2 == 0)
        return len1 == 0 ? 0.0 : 1.0;
    size_t delta = std::max(size_t(1), len1/2) - 1;
    std::vector<bool> flag(len2, false);
    std::vector<char> ch1_match;
    ch1_match.reserve(len1);
    for (size_t idx1 = 0; idx1 < len1; ++idx1) {
        char ch1 = str1[idx1];
        for (size_t idx2 = 0; idx2 < len2; ++idx2) {
            char ch2 = str2[idx2];
            if (idx2 <= idx1 + delta && idx2 + delta >= idx1
                && ch1 == ch2 && !flag[idx2]) {
                flag[idx2] = true;
                ch1_match.push_back(ch1);
                break;
            }
        }
    }
    size_t matches = ch1_match.size();
    if (matches == 0)
        return 1.0;
    size_t transpositions = 0;
    for (size_t idx1 = 0, idx2 = 0; idx2 < len2; ++idx2) {
        if (flag[idx2]) {
            if (str2[idx2] != ch1_match[idx1])
                ++transpositions;
            ++idx1;
        }
    }
    double m = matches;
    double jaro = (m/len1 + m/len2 + (m - transpositions/2.0)/m)/3.0;
    size_t common_prefix = 0;
    len2 = std::min(size_t(4), len2);
    for (size_t i = 0; i < len2; ++i) {
        if (str1[i] == str2[i])
            ++common_prefix;
    }
    return 1.0 - (jaro + common_prefix * 0.1 * (1.0 - jaro));
}
 
auto within_distance(const std::vector<std::string>& words,
                     double max_distance, const std::string& str,
                     size_t max_to_return) {
    using pair = std::pair<std::string, double>;
    std::vector<pair> result;
    for (const auto& word : words) {
        double jaro = jaro_winkler_distance(word, str);
        if (jaro <= max_distance)
            result.emplace_back(word, jaro);
    }
    std::stable_sort(result.begin(), result.end(),
        [](const pair& p1, const pair& p2) { return p1.second < p2.second; });
    if (result.size() > max_to_return)
        result.resize(max_to_return);
    return result;
}
 
int main() {
    try {
        auto words(load_dictionary("linuxwords.txt"));
        std::cout << std::fixed << std::setprecision(4);
        for (auto str : {"accomodate", "definately", "goverment",
                            "occured", "publically", "recieve",
                            "seperate", "untill", "wich"}) {
            std::cout << "Close dictionary words (distance < 0.15 using Jaro-Winkler distance) to '"
                << str << "' are:\n        Word   |  Distance\n";
            for (const auto& pair : within_distance(words, 0.15, str, 5)) {
                std::cout << std::setw(14) << pair.first << " | "
                    << std::setw(6) << pair.second << '\n';
            }
            std::cout << '\n';
        }
    } catch (const std::exception& ex) {
        std::cerr << ex.what() << '\n';
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

#include <iostream> // required for debug code in main() only
#include <iomanip>  // required for debug code in main() only
#include <string>
 
std::string soundex( char const* s )
{
    static char const code[] = { 0, -1,  1,  2,  3, -1,  1,  2,  0, -1,  2,  2,  4,  5,  5, -1,  1,  2,  6,  2,  3, -1,  1,  0,  2,  0,  2,  0,  0,  0,  0,  0 };
 
    if( !s || !*s )
        return std::string();
 
    std::string out( "0000" );
    out[0] = (*s >= 'a' && *s <= 'z') ? *s - ('a' - 'A') : *s;
    ++s;
 
    char prev = code[out[0] & 0x1F]; // first letter, though not coded, can still affect next letter: Pfister
    for( unsigned i = 1; *s && i < 4; ++s )
    {
        if( (*s & 0xC0) != 0x40 ) // process only letters in range [0x40 - 0x7F]
            continue;
        auto const c = code[*s & 0x1F];
        if( c == prev )
            continue;
 
        if( c == -1 )
            prev = 0;    // vowel as separator
        else if( c )
        {
            out[i] = c + '0';
            ++i;
            prev = c;
        }
    }
    return out;
}
 
