mt19937 engine; //mersenne twister
 
unsigned int one_of_n(unsigned int n) {
	unsigned int choice;
	for(unsigned int i = 0; i < n; ++i) {
		uniform_int_distribution<unsigned int> distribution(0, i);
		if(!distribution(engine))
			choice = i;
	}
	return choice;
}
 
int main() {
	engine = mt19937(random_device()()); //seed random generator from system
	unsigned int results[10] = {0};
	for(unsigned int i = 0; i < 1000000; ++i)
		results[one_of_n(10)]++;
	ostream_iterator<unsigned int> out_it(cout, " ");
	copy(results, results+10, out_it);
	cout << '\n';
}

#include <cassert>
#include <functional>
#include <iostream>
 
#define _USE_MATH_DEFINES
#include <math.h>
 
enum RangeType {
    CLOSED,
    BOTH_OPEN,
    LEFT_OPEN,
    RIGHT_OPEN
};
 
class RealSet {
private:
    double low, high;
    double interval = 0.00001;
    std::function<bool(double)> predicate;
 
public:
    RealSet(double low, double high, const std::function<bool(double)>& predicate) {
        this->low = low;
        this->high = high;
        this->predicate = predicate;
    }
 
    RealSet(double start, double end, RangeType rangeType) {
        low = start;
        high = end;
 
        switch (rangeType) {
        case CLOSED:
            predicate = [start, end](double d) { return start <= d && d <= end; };
            break;
        case BOTH_OPEN:
            predicate = [start, end](double d) { return start < d && d < end; };
            break;
        case LEFT_OPEN:
            predicate = [start, end](double d) { return start < d && d <= end; };
            break;
        case RIGHT_OPEN:
            predicate = [start, end](double d) { return start <= d && d < end; };
            break;
        default:
            assert(!"Unexpected range type encountered.");
        }
    }
 
    bool contains(double d) const {
        return predicate(d);
    }
 
    RealSet unionSet(const RealSet& rhs) const {
        double low2 = fmin(low, rhs.low);
        double high2 = fmax(high, rhs.high);
        return RealSet(
            low2, high2,
            [this, &rhs](double d) { return predicate(d) || rhs.predicate(d); }
        );
    }
 
    RealSet intersect(const RealSet& rhs) const {
        double low2 = fmin(low, rhs.low);
        double high2 = fmax(high, rhs.high);
        return RealSet(
            low2, high2,
            [this, &rhs](double d) { return predicate(d) && rhs.predicate(d); }
        );
    }
 
    RealSet subtract(const RealSet& rhs) const {
        return RealSet(
            low, high,
            [this, &rhs](double d) { return predicate(d) && !rhs.predicate(d); }
        );
    }
 
    double length() const {
        if (isinf(low) || isinf(high)) return -1.0; // error value
        if (high <= low) return 0.0;
 
        double p = low;
        int count = 0;
        do {
            if (predicate(p)) count++;
            p += interval;
        } while (p < high);
        return count * interval;
    }
 
    bool empty() const {
        if (high == low) {
            return !predicate(low);
        }
        return length() == 0.0;
    }
};
 
int main() {
    using namespace std;
 
    RealSet a(0.0, 1.0, LEFT_OPEN);
    RealSet b(0.0, 2.0, RIGHT_OPEN);
    RealSet c(1.0, 2.0, LEFT_OPEN);
    RealSet d(0.0, 3.0, RIGHT_OPEN);
    RealSet e(0.0, 1.0, BOTH_OPEN);
    RealSet f(0.0, 1.0, CLOSED);
    RealSet g(0.0, 0.0, CLOSED);
 
    for (int i = 0; i <= 2; ++i) {
        cout << "(0, 1] ∪ [0, 2) contains " << i << " is " << boolalpha << a.unionSet(b).contains(i) << "\n";
        cout << "[0, 2) ∩ (1, 2] contains " << i << " is " << boolalpha << b.intersect(c).contains(i) << "\n";
        cout << "[0, 3) - (0, 1) contains " << i << " is " << boolalpha << d.subtract(e).contains(i) << "\n";
        cout << "[0, 3) - [0, 1] contains " << i << " is " << boolalpha << d.subtract(f).contains(i) << "\n";
        cout << endl;
    }
 
    cout << "[0, 0] is empty is " << boolalpha << g.empty() << "\n";
    cout << endl;
 
    RealSet aa(
        0.0, 10.0,
        [](double x) { return (0.0 < x && x < 10.0) && abs(sin(M_PI * x * x)) > 0.5; }
    );
    RealSet bb(
        0.0, 10.0,
        [](double x) { return (0.0 < x && x < 10.0) && abs(sin(M_PI * x)) > 0.5; }
    );
    auto cc = aa.subtract(bb);
    cout << "Approximate length of A - B is " << cc.length() << endl;
 
    return 0;
}

#include <cassert>
#include <iostream>
#include <vector>
 
class totient_calculator {
public:
    explicit totient_calculator(int max) : totient_(max + 1) {
        for (int i = 1; i <= max; ++i)
            totient_[i] = i;
        for (int i = 2; i <= max; ++i) {
            if (totient_[i] < i)
                continue;
            for (int j = i; j <= max; j += i)
                totient_[j] -= totient_[j] / i;
        }
    }
    int totient(int n) const {
        assert (n >= 1 && n < totient_.size());
        return totient_[n];
    }
    bool is_prime(int n) const {
        return totient(n) == n - 1;
    }
private:
    std::vector<int> totient_;
};
 
bool perfect_totient_number(const totient_calculator& tc, int n) {
    int sum = 0;
    for (int m = n; m > 1; ) {
        int t = tc.totient(m);
        sum += t;
        m = t;
    }
    return sum == n;
}
 
int main() {
    totient_calculator tc(10000);
    int count = 0, n = 1;
    std::cout << "First 20 perfect totient numbers:\n";
    for (; count < 20; ++n) {
        if (perfect_totient_number(tc, n))  {
            if (count > 0)
                std::cout << ' ';
            ++count;
            std::cout << n;
        }
    }
    std::cout << '\n';
    return 0;
}

